    brand_id, has_fragrance, has_alcohol, key_actives_summary, created_at, updated_at
) VALUES
(101, 'Kem Nền L''Oreal Paris Infallible 32H Fresh Wear Foundation 30ml', 'kem-nen-l-oreal-paris-infallible-32h-fresh-wear-foundation-30ml', 'Kem nền dạng lỏng che phủ cao, lâu trôi suốt 32 giờ với công nghệ thoáng khí Oxygen độc quyền.', 'Kem nền L''Oreal Paris Infallible 32H Fresh Wear ứng dụng công nghệ đột phá cho phép làn da trao đổi oxy tự nhiên, tạo lớp nền mỏng nhẹ như không khí nhưng vẫn che phủ hoàn hảo các khuyết điểm, vết thâm mụn và đốm đỏ. Khả năng kháng nước, kháng mồ hôi và chống lem trôi vượt trội giúp lớp trang điểm bền đẹp suốt cả ngày dài năng động mà không gây bít tắc lỗ chân lông hay sinh mụn.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua/Water, Dimethicone, Isododecane, Alcohol Denat., Ethylhexyl Methoxycinnamate, Trimethylsiloxysilicate, Butylene Glycol, PEG-10 Dimethicone, Titanium Dioxide, Perlite, Synthetic Fluorphlogopite, Nylon-12, Isopropyl Lauroyl Sarcosinate, Diisopropyl Sebacate, Disteardimonium Hectorite, HDI/Trimethylol Hexyllactone Crosspolymer, Bis-PEG/PPG-14/14 Dimethicone, Magnesium Sulfate, Aluminum Hydroxide, Phenoxyethanol, Disodium Stearoyl Glutamate, Hydrogen Dimethicone, Dipentaerythrityl Tetrahydroxystearate/Tetraisostearate, Parfum/Fragrance, Silica Silylate, Acrylonitrile/Methyl Methacrylate/Vinylidene Chloride Copolymer, Tocopherol, Hexyl Cinnamal, Silica, Isobutane, Benzyl Salicylate, Linalool, Alpha-Isomethyl Ionone, Benzyl Alcohol, BHT, Citronellol.', 'Lấy một lượng kem nền vừa đủ (khoảng 1-2 lần nhấn) chấm đều lên 5 điểm trên mặt: trán, mũi, hai má và cằm. Sử dụng mút trang điểm hoặc cọ tán nền tán đều từ trong ra ngoài theo chiều cấu trúc da.', 'Pháp', '30ml', 1, 4.92, 51, 151, 1, 0, 0, 'Vitamin C, SPF 25, Oxygen Technology', NOW(), NOW()),
(102, 'Serum Siêu Cấp Ẩm Sáng Da L''Oreal Paris Revitalift Pure Hyaluronic Acid 1.5% 30ml', 'serum-sieu-cap-am-sang-da-l-oreal-paris-revitalift-pure-hyaluronic-acid-1-5-30ml', 'Serum chứa 1.5% Hyaluronic Acid nguyên chất đa tầng giúp cấp ẩm sâu và làm căng mọng da tức thì.', 'Tinh chất L''Oreal Paris Revitalift Pure Hyaluronic Acid 1.5% là giải pháp cấp nước chuyên sâu với sự kết hợp tối ưu giữa 0.5% Macro Hyaluronic Acid (cấp ẩm tầng thượng bì, làm mịn bề mặt da) và 1.0% Micro Hyaluronic Acid (thẩm thấu sâu vào tầng trung bì, làm đầy các nếp nhăn li ti từ bên trong). Kết cấu dạng gel lỏng trong suốt, thẩm thấu nhanh, không nhờn rít, giúp da căng mướt và rạng rỡ ngay sau lần thoa đầu tiên.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water, Glycerin, Hydroxyethylpiperazine Ethane Sulfonic Acid, Sodium Hyaluronate, PEG-60 Hydrogenated Castor Oil, Secale Cereale Seed Extract/Rye Seed Extract, Calcium Pantothenate, Dipeptide Diaminobutyroyl Benzylamide Diacetate, Ascorbyl Glucoside, Disodium EDTA, Pentylene Glycol, Phenoxyethanol, Chlorphenesin.', 'Sau khi làm sạch mặt và dùng nước hoa hồng, nhỏ 3-4 giọt serum lên mặt và cổ, vỗ nhẹ nhàng bằng các đầu ngón tay cho dưỡng chất thẩm thấu hoàn toàn. Khóa ẩm lại bằng kem dưỡng.', 'Pháp', '30ml', 1, 4.85, 52, 152, 1, 0, 0, '1.5% Hyaluronic Acid (Macro & Micro HA), Glycerin', NOW(), NOW()),
(103, 'Nước Tẩy Trang Sạch Sâu Kiềm Dầu L''Oreal Paris Micellar Water 3-in-1 Deep Cleansing 400ml', 'nuoc-tay-trang-sach-sau-kiem-dau-l-oreal-paris-micellar-water-3-in-1-deep-cleansing-400ml', 'Nước tẩy trang 2 lớp Bi-Phase giúp làm sạch sâu lớp trang điểm chống nước và bụi mịn PM2.5.', 'Nước tẩy trang L''Oreal Paris Micellar Water Deep Cleansing sở hữu công nghệ Micellar đột phá kết hợp cùng lớp dầu dưỡng nhẹ (Bi-phase), dễ dàng hút sạch mọi cặn trang điểm đậm, mascara chống thấm nước, son lì lâu trôi và bã nhờn sâu trong lỗ chân lông. Sản phẩm không chứa cồn, không gây cảm giác khô căng hay cay mắt, giữ cho làn da luôn tươi mát và mềm mại sau khi làm sạch.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Aqua/Water, Cyclopentasiloxane, Isohexadecane, Potassium Phosphate, Sodium Chloride, Dipotassium Phosphate, Disodium EDTA, Decyl Glucoside, Hexylene Glycol, Polyaminopropyl Biguanide.', 'Lắc đều chai trước khi dùng để 2 lớp dầu và nước hòa quyện. Thấm một lượng vừa đủ ra bông tẩy trang, nhẹ nhàng lau khắp mặt, mắt và môi theo hướng từ trong ra ngoài. Không cần rửa lại với nước.', 'Pháp', '400ml', 1, 4.92, 53, 153, 1, 0, 0, 'Micellar Technology, Bi-Phase Oil, Glycerin', NOW(), NOW()),
(104, 'Mascara Làm Dày Và Cong Mi L''Oreal Paris Voluminous Lash Paradise Mascara 7.6ml', 'mascara-lam-day-va-cong-mi-l-oreal-paris-voluminous-lash-paradise-mascara-7-6ml', 'Mascara đầu cọ đồng hồ cát với sợi tơ mềm mại giúp mi dày tơi bồng bềnh và giữ nếp cong vút suốt ngày.', 'Mascara L''Oreal Paris Voluminous Lash Paradise là sản phẩm trang điểm mắt kinh điển với công thức chứa dầu hoa ngô dịu nhẹ và hoa hồng, giúp nuôi dưỡng sợi mi chắc khỏe. Đầu cọ lượn sóng hơn 200 sợi lông chải ôm trọn từng sợi mi từ gốc đến ngọn, mang lại độ dày gấp nhiều lần mà không hề vón cục hay nặng mi, khả năng chống lem và chống thấm nước tối ưu.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Isododecane, Cera Alba/Beeswax, Copernicia Cerifera Cera/Carnauba Wax, Disteardimonium Hectorite, Dilinoleic Acid/Butanediol Copolymer, Aqua/Water, Allyl Stearate/VA Copolymer, Oryza Sativa Cera/Rice Bran Wax, Paraffin, Alcohol Denat., Polyvinyl Laurate, VP/Eicosene Copolymer, Propylene Carbonate, Talc, Synthetic Beeswax, Ethylenediamine/Stearyl Dimer Dilinoleate Copolymer, PEG-30 Glyceryl Stearate, Candelilla Cera/Candelilla Wax, Ricinus Communis Seed Oil/Castor Seed Oil, Panthenol, Maltodextrin, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, BHT, Centaurea Cyanus Flower Extract. [+/- May Contain: CI 77499/Iron Oxides].', 'Bấm mi nhẹ nhàng trước khi chuốt. Đặt đầu cọ mascara ở sát chân mi, chuốt ziczac từ chân đến ngọn mi. Chuốt thêm 1-2 lớp để đạt độ dày và dài mong muốn.', 'Pháp', '7.6ml', 1, 4.85, 54, 154, 1, 0, 0, 'Cornflower Oil, Castor Oil, Carnauba Wax', NOW(), NOW()),
(105, 'Dầu Dưỡng Tóc Cao Cấp Chiết Xuất 6 Loại Hoa L''Oreal Paris Elseve Extraordinary Oil Serum 100ml', 'dau-duong-toc-cao-cap-chiet-xuat-6-loai-hoa-l-oreal-paris-elseve-extraordinary-oil-serum-100ml', 'Dầu dưỡng tóc phục hồi hư tổn với tinh dầu chiết xuất từ 6 loài hoa quý giá giúp tóc mềm mượt óng ả.', 'L''Oreal Paris Elseve Extraordinary Oil Serum được đặc chế từ sự kết hợp của 6 loại tinh dầu hoa thiên nhiên (hoa sen, hoa cúc, hoa tiaré, hoa hồng, hoa lanh và hoa đậu chổi), cung cấp dưỡng chất thẩm thấu sâu nuôi dưỡng sợi tóc từ lõi. Sản phẩm giúp giảm xơ rối, bảo vệ tóc trước nhiệt độ cao lên đến 230°C và mang lại độ bóng khỏe mềm mại tự nhiên mà không gây bết dính sợi tóc.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Cyclopentasiloxane, Dimethiconol, Chamomilla Recutita Extract/Matricaria Flower Extract, Cocos Nucifera Oil/Coconut Oil, Helianthus Annuus Seed Oil/Sunflower Seed Oil, Nelumbium Speciosum Flower Extract, Benzyl Alcohol, Cinnamal, Linalool, Linum Usitatissimum Flower Extract, Caprylic/Capric Triglyceride, Gardenia Taitensis Flower Extract, Rosa Canina Flower Extract, Bisabolol, Glycine Soja Oil/Soybean Oil, Parfum/Fragrance.', 'Lấy 2-3 giọt dầu dưỡng xoa đều vào lòng bàn tay rồi thoa đều lên thân và ngọn tóc khi tóc còn ẩm hoặc sau khi sấy khô. Có thể dùng trước khi sấy để bảo vệ tóc khỏi nhiệt độ cao.', 'Pháp', '100ml', 1, 4.92, 20, 155, 1, 1, 0, '6 Flower Extracts (Lotus, Chamomile, Tiare, Rose, Flax, Chamomile)', NOW(), NOW()),
(106, 'Mascara Dài Và Cong Mi Không Trôi Maybelline Lash Sensational Sky High Waterproof 6ml', 'mascara-dai-va-cong-mi-khong-troi-maybelline-lash-sensational-sky-high-waterproof-6ml', 'Mascara nối dài mi không giới hạn với chiết xuất tre và đầu cọ tháp linh hoạt Flex Tower.', 'Maybelline Lash Sensational Sky High Waterproof mang lại hiệu ứng mi dài miên man và cong vút từ mọi góc nhìn nhờ đầu cọ uốn cong Flex Tower độc quyền chạm đến từng sợi mi ngắn nhất. Công thức bổ sung chiết xuất tre và sợi tơ cellulose giúp làm dài mi rõ rệt mà không gây nặng mí hay gãy rụng. Khả năng chống nước, mồ hôi và bã nhờn tuyệt đối suốt 24 giờ.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Isododecane, Cera Alba/Beeswax, Copernicia Cerifera Cera/Carnauba Wax, Disteardimonium Hectorite, Aqua/Water, Allyl Stearate/VA Copolymer, Oryza Sativa Cera/Rice Bran Wax, Paraffin, Alcohol Denat., Polyvinyl Laurate, VP/Eicosene Copolymer, Propylene Carbonate, Talc, Ethylenediamine/Stearyl Dimer Dilinoleate Copolymer, PEG-30 Glyceryl Stearate, Rayon, Hydrogenated Jojoba Oil, Caprylic/Capric Triglyceride, Silica, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Bambusa Vulgaris Extract, BHT. [+/- May Contain: CI 77491, CI 77492, CI 77499/Iron Oxides, CI 77007/Ultramarines, Mica, CI 77891/Titanium Dioxide].', 'Uốn mi cong bằng kẹp bấm mi. Giữ đầu cọ Flex Tower ở chân mi và chuốt nhẹ nhàng từ gốc đến ngọn nhiều lần để sợi mi nối dài tối đa.', 'Mỹ', '6ml', 1, 4.85, 21, 156, 2, 0, 0, 'Bamboo Extract, Rayon Fibers, Beeswax', NOW(), NOW()),
(107, 'Bút Kẻ Mắt Nước Nét Sắc Mảnh Maybelline Hyper Sharp Liner Extreme 0.4g', 'but-ke-mat-nuoc-net-sac-manh-maybelline-hyper-sharp-liner-extreme-0-4g', 'Kẻ mắt nước đầu cọ siêu mảnh 0.01mm cải tiến, mực ra đều và bền màu chống trôi đến 36 giờ.', 'Bút kẻ mắt Maybelline Hyper Sharp Liner Extreme sở hữu đầu cọ vi sợi dẻo dai với kích thước siêu mảnh chỉ 0.01mm giúp thao tác kẻ đuôi mắt chuẩn xác từ đường mảnh tự nhiên đến đường kẻ mắt mèo sắc sảo. Công nghệ màng phim polymer kháng nước, chống lem dầu và chống trôi hiệu quả suốt 36 giờ nhưng vẫn dễ dàng tẩy sạch bằng nước tẩy trang thông thường.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua/Water, Ammonium Acrylates Copolymer, Butylene Glycol, 1,2-Hexanediol, Alcohol, Phenoxyethanol, Beheneth-30, Aminomethyl Propanol, Simethicone, Sorbitan Laurate, Sorbitan Palmitate, Hydrogenated Palm Glycerides, Sorbitan Trioleate, Sucrose Palmitate. [+/- May Contain: CI 77266/Black 2].', 'Kẻ một đường mảnh sát chân mi từ đầu mắt đến đuôi mắt. Kéo nhẹ một đường hất lên ở phần đuôi mắt để tạo đuôi mắt sắc sảo quyến rũ.', 'Mỹ', '0.4g', 1, 4.92, 22, 157, 2, 0, 0, 'Polymer Film, Carbon Black Pigments', NOW(), NOW()),
(108, 'Kem Nền Kiềm Dầu Mịn Lì Tự Nhiên Maybelline Fit Me Matte + Poreless Foundation 30ml', 'kem-nen-kiem-dau-min-li-tu-nhien-maybelline-fit-me-matte-poreless-foundation-30ml', 'Kem nền quốc dân kiềm dầu và thu nhỏ lỗ chân lông với bột đất sét khoáng Aerogel siêu nhẹ.', 'Maybelline Fit Me Matte + Poreless Foundation là dòng kem nền bán chạy nhất thế giới dành cho da dầu và hỗn hợp thiên dầu. Chứa các hạt phấn siêu nhỏ khoáng chất kiềm dầu cùng đất sét tự nhiên, sản phẩm hút sạch bã nhờn dư thừa, làm mờ lỗ chân lông to và duy trì hiệu ứng mịn lì tự nhiên suốt 16 giờ mà không làm dày cộm da mặt.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Aqua/Water, Cyclohexasiloxane, Nylon-12, Isododecane, Alcohol Denat., Cyclopentasiloxane, PEG-10 Dimethicone, Cetyl PEG/PPG-10/1 Dimethicone, PEG-20, Polyglyceryl-4 Isostearate, Disteardimonium Hectorite, Phenoxyethanol, Magnesium Sulfate, Disodium Stearoyl Glutamate, HDI/Trimethylol Hexyllactone Crosspolymer, Titanium Dioxide, Methylparaben, Acrylates Copolymer, Tocopherol, Butylparaben, Aluminum Hydroxide, Alumina, Silica, Glycerin. [+/- May Contain: CI 77891/Titanium Dioxide, CI 77491, CI 77492, CI 77499/Iron Oxides].', 'Lấy lượng kem vừa đủ ra mu bàn tay. Dùng cọ hoặc mút ẩm dặm đều từ trung tâm khuôn mặt ra ngoài viền khuôn mặt để lớp nền tệp tự nhiên vào màu da.', 'Mỹ', '30ml', 1, 4.85, 23, 158, 2, 0, 0, 'Micro-Powders, Mineral Clay, SPF 22', NOW(), NOW()),
(109, 'Phấn Phủ Dạng Nén Kiềm Dầu Khóa Nền Maybelline Fit Me Matte + Poreless Powder 8.5g', 'phan-phu-dang-nen-kiem-dau-khoa-nen-maybelline-fit-me-matte-poreless-powder-8-5g', 'Phấn phủ nén kiểm soát dầu thừa 12H và làm mờ lỗ chân lông với chỉ số chống nắng SPF 28 PA+++.', 'Phấn phủ Maybelline Fit Me Matte + Poreless Powder được cấu tạo từ các hạt phấn Perlite khoáng chất siêu mịn, giúp khóa chặt lớp nền không xê dịch, kiểm soát dầu bóng nhờn suốt 12 giờ và đem lại làn da sáng mịn rạng rỡ. Thiết kế hộp phấn kèm gương soi và bông phấn tiện lợi cho việc dặm lại lớp trang điểm mọi lúc mọi nơi.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Talc, Perlite, Triisostearin, Phenyl Trimethicone, Magnesium Stearate, Caprylyl Glycol, Ethylhexyl Methoxycinnamate, Tocopherol. [+/- May Contain: CI 77891/Titanium Dioxide, CI 77491, CI 77492, CI 77499/Iron Oxides, Mica].', 'Dùng bông phấn hoặc cọ phủ lấy một lượng phấn vừa đủ, vỗ nhẹ rũ bớt phấn thừa rồi dặm nhẹ nhàng lên toàn bộ khuôn mặt, đặc biệt tập trung vào vùng chữ T đổ dầu.', 'Mỹ', '8.5g', 1, 4.92, 24, 159, 2, 0, 0, 'Perlite Mineral, Micro-Powders, SPF 28 PA+++', NOW(), NOW()),
(110, 'Son Kem Lì Giữ Màu 16 Giờ Maybelline SuperStay Matte Ink Liquid Lipstick 5ml', 'son-kem-li-giu-mau-16-gio-maybelline-superstay-matte-ink-liquid-lipstick-5ml', 'Son kem lì bám màu đỉnh cao 16 tiếng không lem, không trôi khi ăn uống với bảng màu thời thượng.', 'Maybelline SuperStay Matte Ink là dòng son kem lì được yêu thích bậc nhất nhờ công nghệ mực đàn hồi Elastic Ink giữ màu chuẩn xác đến 16 giờ không trôi, không lem ra khẩu trang hay ly tách khi ăn uống. Đầu cọ son hình mũi tên nhọn độc đáo giúp viền môi sắc nét và lấy lượng son chuẩn xác chỉ trong một lần quẹt.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Trimethylsiloxysilicate, Isododecane, Nylon-611/Dimethicone Copolymer, Dimethicone Crosspolymer, C30-45 Alkyldimethylsilyl Polypropylsilsesquioxane, Lauroyl Lysine, Alumina, Silica Silylate, Phenoxyethanol, Disodium Stearoyl Glutamate, Aluminum Hydroxide, Limonene, Silica, Synthetic Fluorphlogopite, Paraffin, Benzyl Benzoate, Caprylyl Glycol, Benzyl Alcohol, Citronellol, Parfum/Fragrance. [+/- May Contain: CI 77891/Titanium Dioxide, CI 77491, CI 77492, CI 77499/Iron Oxides, CI 15850/Red 7, CI 45410/Red 28 Lake, CI 15985/Yellow 6 Lake, CI 19140/Yellow 5 Lake, CI 42090/Blue 1 Lake].', 'Dùng đầu cọ thoa son từ lòng môi ra khóe môi. Để son khô tự nhiên trong khoảng 1-2 phút để lớp son cố định hoàn toàn tạo hiệu ứng lì mượt.', 'Mỹ', '5ml', 1, 4.85, 25, 160, 2, 1, 0, 'Elastic Ink Technology, High-Intensity Pigments', NOW(), NOW()),
(111, 'Sữa Rửa Mặt Cấp Ẩm Cho Da Khô CeraVe Hydrating Facial Cleanser 473ml', 'sua-rua-mat-cap-am-cho-da-kho-cerave-hydrating-facial-cleanser-473ml', 'Sữa rửa mặt không tạo bọt chứa 3 Ceramide thiết yếu và Hyaluronic Acid phục hồi hàng rào bảo vệ da.', 'CeraVe Hydrating Cleanser được nghiên cứu bởi các bác sĩ da liễu hàng đầu, giúp làm sạch bụi bẩn, dầu thừa và cặn trang điểm một cách êm dịu mà không phá vỡ màng ẩm sinh học của da. Công nghệ nhả chậm MVE Technology cung cấp dưỡng chất liên tục suốt 24 giờ, kết hợp cùng 3 loại Ceramide thiết yếu (1, 3, 6-II) và Hyaluronic Acid giữ cho da mềm mịn, ẩm mượt sau khi rửa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua/Water/Eau, Glycerin, Cetearyl Alcohol, Peg-40 Stearate, Stearyl Alcohol, Potassium Phosphate, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Glyceryl Stearate, Behentrimonium Methosulfate, Sodium Lauroyl Lactylate, Sodium Hyaluronate, Cholesterol, Phenoxyethanol, Disodium EDTA, Dipotassium Phosphate, Tocopherol, Phytosphingosine, Xanthan Gum, Cetyl Alcohol, Polysorbate 20, Ethylhexylglycerin.', 'Làm ướt mặt bằng nước ấm. Lấy một lượng sữa rửa mặt vừa đủ thoa đều và massage nhẹ nhàng khắp mặt theo chuyển động tròn trong 60 giây, sau đó rửa sạch lại với nước.', 'Mỹ', '473ml', 1, 4.92, 26, 161, 3, 0, 0, 'Ceramides 1, 3, 6-II, Hyaluronic Acid, MVE Technology', NOW(), NOW()),
(112, 'Sữa Tắm Dưỡng Ẩm Làm Sạch Dịu Nhẹ Cho Da Khô CeraVe Hydrating Body Wash 296ml', 'sua-tam-duong-am-lam-sach-diu-nhe-cho-da-kho-cerave-hydrating-body-wash-296ml', 'Sữa tắm dạng kem chứa 3 Ceramide thiết yếu và Hyaluronic Acid nhẹ nhàng làm sạch cơ thể không khô da.', 'CeraVe Hydrating Body Wash được phát triển bởi các bác sĩ da liễu Hoa Kỳ dành riêng cho làn da cơ thể khô rát và nhạy cảm. Công thức tạo bọt nhẹ dịu làm sạch hoàn hảo bụi bẩn và mồ hôi mà không phá vỡ màng ẩm sinh học tự nhiên của da, chứa 3 Ceramide thiết yếu (1, 3, 6-II) và Hyaluronic Acid khóa ẩm sâu suốt 24 giờ, đã nhận dấu chứng nhận chấp thuận của Hiệp hội Eczema Quốc gia (NEA).', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua/Water/Eau, Glycerin, Cetearyl Alcohol, Peg-40 Stearate, Stearyl Alcohol, Potassium Phosphate, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Glyceryl Stearate, Behentrimonium Methosulfate, Sodium Lauroyl Lactylate, Sodium Hyaluronate, Cholesterol, Phenoxyethanol, Disodium EDTA, Dipotassium Phosphate, Tocopherol, Phytosphingosine, Xanthan Gum, Ethylhexylglycerin.', 'Làm ướt cơ thể bằng nước ấm. Cho một lượng sữa tắm vừa đủ ra bông tắm hoặc lòng bàn tay, tạo bọt nhẹ nhàng rồi mát xa toàn thân trong 2-3 phút, sau đó tắm sạch lại với nước.', 'Mỹ', '296ml', 1, 4.85, 27, 162, 3, 0, 0, 'Ceramides 1, 3, 6-II, Hyaluronic Acid, Emollient Complex, NEA Accepted', NOW(), NOW()),
(113, 'Kem Dưỡng Tái Tạo Da Chân Khô Nứt Nẻ CeraVe Renewing SA Foot Cream 88ml', 'kem-duong-tai-tao-da-chan-kho-nut-ne-cerave-renewing-sa-foot-cream-88ml', 'Kem dưỡng trị nứt nẻ gót chân chứa Salicylic Acid, Ammonium Lactate và Ceramide làm mềm mịn gót chân.', 'CeraVe Renewing SA Foot Cream là liệu pháp chăm sóc da chân chuyên sâu giúp làm mềm mịn vùng da gót chân chai sần, nứt nẻ và thô ráp. Công thức kết hợp Salicylic Acid tẩy tế bào chết nhẹ dịu, Ammonium Lactate dưỡng ẩm làm mềm tế bào sừng cùng 3 Ceramide sinh học tái tạo màng bảo vệ da, đem lại đôi chân mềm mại mượt mà không còn cảm giác đau rát.', 'https://images.unsplash.com/photo-1556228852-80b6e5eeff06?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua/Water, Glycerin, Paraffinum Liquidum/Mineral Oil, Glyceryl Stearate SE, Cetearyl Alcohol, Niacinamide, Cetyl Alcohol, Ammonium Lactate, Triethanolamine, Salicylic Acid, Behentrimonium Methosulfate, PEG-100 Stearate, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Dimethicone, Methylparaben, Sodium Lauroyl Lactylate, Cholecalciferol, Cholesterol, Disodium EDTA, Propylparaben, Hydrolyzed Hyaluronic Acid, Phytosphingosine, Xanthan Gum.', 'Rửa sạch và lau khô chân. Lấy một lượng kem vừa đủ thoa đều lên toàn bộ bàn chân và gót chân, mát xa nhẹ nhàng cho kem thẩm thấu. Nên thoa trước khi đi ngủ và mang tất cotton để đạt hiệu quả cao nhất.', 'Mỹ', '88ml', 1, 4.92, 28, 163, 3, 0, 0, 'Salicylic Acid, Ammonium Lactate, Ceramides 1, 3, 6-II, Niacinamide', NOW(), NOW()),
(114, 'Kem Dưỡng Da Tay Phục Hồi Chuyên Sâu CeraVe Therapeutic Hand Cream 85g', 'kem-duong-da-tay-phuc-hoi-chuyen-sau-cerave-therapeutic-hand-cream-85g', 'Kem dưỡng da tay kháng nước chứa Dimethicone, Ceramide và HA làm dịu da tay khô nứt nẻ do hóa chất.', 'CeraVe Therapeutic Hand Cream là dòng kem dưỡng tay dược mỹ phẩm bán chạy hàng đầu thế giới được Hiệp hội Eczema Quốc gia Hoa Kỳ công nhận. Công thức bảo vệ da tay với 4% Dimethicone tạo lớp màng vô hình kháng nước chống lại các tác nhân gây khô ráp như xà phòng và cồn rửa tay, kết hợp cùng 3 Ceramide thiết yếu, Niacinamide và Hyaluronic Acid phục hồi độ ẩm và làm mềm mượt các khớp ngón tay khô ráp tức thì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Water, Cyclopentasiloxane, Aluminum Starch Octenylsuccinate, Isopentyldiol, Cetearyl Alcohol, Glycerin, Ceteareth-20, Butyrospermum Parkii (Shea) Butter, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Niacinamide, Sodium Hyaluronate, Cholesterol, Phenoxyethanol, Tocopheryl Acetate, Phytosphingosine, Xanthan Gum, Ethylhexylglycerin.', 'Thoa một lượng nhỏ kem lên mu bàn tay và lòng bàn tay, mát xa đều khắp các kẽ ngón tay và móng tay sau mỗi lần rửa tay hoặc bất cứ khi nào thấy tay khô căng.', 'Mỹ', '85g', 1, 4.85, 29, 164, 3, 0, 0, '4% Dimethicone, Ceramides 1, 3, 6-II, Niacinamide, Hyaluronic Acid, NEA Accepted', NOW(), NOW()),
(115, 'Sữa Dưỡng Thể Cấp Ẩm Toàn Thân Dịu Nhẹ CeraVe Daily Moisturizing Lotion 236ml', 'sua-duong-the-cap-am-toan-than-diu-nhe-cerave-daily-moisturizing-lotion-236ml', 'Sữa dưỡng ẩm toàn thân mỏng nhẹ không dầu (Oil-Free) chứa 3 Ceramide và Hyaluronic Acid cấp ẩm suốt 24h.', 'CeraVe Daily Moisturizing Lotion là dòng sữa dưỡng thể dịu nhẹ hấp thu nhanh vào da mà không để lại bất kỳ vệt bóng nhờn hay cảm giác bết dính. Với công nghệ MVE độc quyền giúp giải phóng dưỡng chất Ceramide và Hyaluronic Acid thẩm thấu suốt ngày dài, sản phẩm phục hồi hiệu quả màng lipid sinh học cho da cơ thể, ngăn ngừa hiện tượng bong tróc và thô ráp.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water/Eau, Glycerin, Caprylic/Capric Triglyceride, Cetearyl Alcohol, Cetyl Alcohol, Potassium Phosphate, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Dimethicone, Ceteareth-20, Behentrimonium Methosulfate, Methylparaben, Sodium Lauroyl Lactylate, Sodium Hyaluronate, Cholesterol, Phenoxyethanol, Disodium EDTA, Dipotassium Phosphate, Propylparaben, Phytosphingosine, Xanthan Gum, Polysorbate 20, Polyglyceryl-3 Diisostearate.', 'Sau khi tắm xong và lau khô cơ thể, lấy lượng sữa dưỡng vừa đủ thoa đều khắp vùng da tay, chân và toàn thân. Mát xa nhẹ nhàng theo chiều xoắn ốc để dưỡng chất thấm sâu.', 'Mỹ', '236ml', 1, 4.92, 30, 165, 3, 0, 0, 'Ceramides 1, 3, 6-II, Hyaluronic Acid, MVE Delivery', NOW(), NOW()),
(116, 'Kem Chống Nắng Kiểm Soát Dầu Ngừa Mụn La Roche-Posay Anthelios Oil Correct SPF50+ 50ml', 'kem-chong-nang-kiem-soat-dau-ngua-mun-la-roche-posay-anthelios-oil-correct-spf50-50ml', 'Kem chống nắng quang phổ rộng bảo vệ da trước tia UV và bụi mịn, kết hợp Salicylic Acid & Niacinamide giảm mụn.', 'La Roche-Posay Anthelios Oil Correct SPF50+ là dòng sản phẩm chống nắng thế hệ mới ứng dụng công nghệ Cellox-B3 Tech cùng phức hợp điều trị mụn Salicylic Acid, Niacinamide và Zinc PCA. Sản phẩm vừa tạo màng chắn bảo vệ da tối đa trước tia UVA/UVB và ô nhiễm môi trường, vừa hỗ trợ giảm dầu nhờn đến 12 giờ, thu nhỏ lỗ chân lông và ngăn ngừa mụn tái phát rõ rệt.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua/Water/Eau, Silica, Isopropyl Palmitate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Ethylhexyl Salicylate, Ethylhexyl Triazone, Butyl Methoxydibenzoylmethane, Dicaprylyl Ether, Niacinamide, Drometrizole Trisiloxane, Phenylbenzimidazole Sulfonic Acid, Triethanolamine, C12-22 Alkyl Copolymer, Zea Mays Starch/Corn Starch, Salicylic Acid, Zinc PCA, Caprylyl Glycol, Citric Acid, Poloxamer 407, Tocopherol.', 'Thoa kem chống nắng mỗi buổi sáng trước khi ra ngoài 20 phút. Lấy lượng kem bằng khoảng một đồng xu thoa đều khắp mặt và cổ. Thoa lại sau mỗi 2-3 giờ khi vận động ngoài trời.', 'Pháp', '50ml', 1, 4.85, 31, 166, 4, 0, 0, 'Cellox-B3 Tech, Salicylic Acid, Niacinamide, Zinc PCA', NOW(), NOW()),
(117, 'Nước Xịt Khoáng Làm Dịu Chống Kích Ứng La Roche-Posay Thermal Spring Water 300ml', 'nuoc-xit-khoang-lam-diu-chong-kich-ung-la-roche-posay-thermal-spring-water-300ml', 'Nước khoáng thiên nhiên giàu nguyên tố vi lượng Selenium giúp làm dịu da nhạy cảm và chống oxy hóa mạnh mẽ.', 'Nước khoáng La Roche-Posay Thermal Spring Water bắt nguồn từ nguồn khoáng tinh khiết tại thị trấn La Roche-Posay nước Pháp, nổi tiếng với hàm lượng chất chống oxy hóa tự nhiên Selenium cực cao. Nước xịt khoáng giúp hạ nhiệt làn da tức thì, làm dịu các nốt mẩn đỏ, rát nắng, kích ứng da sau thủ thuật thẩm mỹ và củng cố hàng rào phòng thủ của tế bào biểu bì.', 'https://images.unsplash.com/photo-1617897903246-719242758050?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua/Water/Eau La Roche-Posay (Rich in Selenium, Zinc, Copper, Silica, Calcium, Bicarbonate).', 'Đặt bình xịt song song với mặt cách khoảng 20cm, xịt đều theo hình chữ X hoặc vòng tròn quanh mặt. Để nước khoáng ngấm tự nhiên trong 2-3 phút rồi vỗ nhẹ hoặc dùng khăn giấy thấm nhẹ bớt nước thừa.', 'Pháp', '300ml', 1, 4.92, 32, 167, 4, 0, 0, '100% La Roche-Posay Thermal Spring Water, Natural Selenium', NOW(), NOW()),
(118, 'Tinh Chất Giảm Mụn Mờ Thâm Gom Cồi La Roche-Posay Effaclar Serum 30ml', 'tinh-chat-giam-mun-mo-tham-gom-coi-la-roche-posay-effaclar-serum-30ml', 'Serum chứa phức hợp 3 Acid điều trị (Salicylic, Glycolic, LHA) cùng Niacinamide giảm mụn ẩn và thâm mụn.', 'La Roche-Posay Effaclar Serum là tinh chất trị mụn chuyên sâu ứng dụng công thức Tri-Acid Complex: 1.5% Salicylic Acid thông thoáng lỗ chân lông, 3.5% Glycolic Acid kích thích tái tạo da và 0.45% LHA tẩy tế bào chết siêu vi điểm. Kết hợp cùng Niacinamide và nước khoáng dịu da, serum làm giảm mụn viêm, gom khô cồi mụn ẩn và làm mờ vết thâm sạm sau mụn chỉ sau 28 ngày sử dụng.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua/Water/Eau, Alcohol Denat., Propanediol, Glycolic Acid, Niacinamide, Dimethyl Isosorbide, Pentylene Glycol, Salicylic Acid, Sodium Hydroxide, PEG-60 Hydrogenated Castor Oil, Hydroxyethylpiperazine Ethane Sulfonic Acid, Citric Acid, PEG-30 Glyceryl Cocoate, Capryloyl Salicylic Acid, Biosaccharide Gum-1, Maltodextrin, Phytic Acid, Polyquaternium-10, Parfum/Fragrance.', 'Sử dụng vào buổi tối sau bước làm sạch và nước cân bằng. Nhỏ 3 giọt lên trán và hai má, thoa đều và vỗ nhẹ. Bắt buộc dùng kem chống nắng có chỉ số bảo vệ cao vào ban ngày.', 'Pháp', '30ml', 1, 4.85, 33, 168, 4, 0, 0, 'Tri-Acid Complex (Salicylic 1.5%, Glycolic 3.5%, LHA 0.45%), Niacinamide', NOW(), NOW()),
(119, 'Kem Dưỡng Giảm Nứt Nẻ Khô Ráp Da Chân La Roche-Posay Lipikar Podologics Lipid-Replenishing Foot Cream 100ml', 'kem-duong-giam-nut-ne-kho-rap-da-chan-la-roche-posay-lipikar-podologics-100ml', 'Kem dưỡng gót chân chứa LHA tẩy tế bào chết và bơ hạt mỡ làm lành gót chân nứt nẻ trong 5 ngày.', 'La Roche-Posay Lipikar Podologics Lipid-Replenishing Foot Cream là giải pháp chuyên khoa da liễu phục hồi da bàn chân khô ráp chai sần và nứt nẻ gót chân. Công thức độc đáo kết hợp hoạt chất vi tẩy tế bào chết LHA giúp làm mịn các lớp sừng chai cứng, bơ hạt mỡ Shea Butter bổ sung lipid tự nhiên làm lành các vết nứt đau rát và nước khoáng La Roche-Posay xoa dịu làn da mệt mỏi chỉ sau 5 ngày sử dụng.', 'https://images.unsplash.com/photo-1556228852-80b6e5eeff06?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua/Water, Glycerin, Paraffinum Liquidum/Mineral Oil, Propylene Glycol, Butyrospermum Parkii Butter/Shea Butter, Octyldodecanol, Dimethicone, Glyceryl Stearate, Stearyl Alcohol, Cetyl Alcohol, Stearic Acid, Palmitic Acid, Phenoxyethanol, Carbomer, Triethanolamine, Capryloyl Salicylic Acid (LHA), Xanthan Gum, Disodium EDTA, Parfum/Fragrance.', 'Thoa kem đều đặn mỗi tối lên toàn bộ bàn chân đã rửa sạch và lau khô, đặc biệt mát xa kỹ vùng gót chân bị nứt nẻ và các vết chai sần.', 'Pháp', '100ml', 1, 4.92, 34, 169, 4, 0, 0, 'LHA (Capryloyl Salicylic Acid), Shea Butter, La Roche-Posay Thermal Spring Water', NOW(), NOW()),
(120, 'Sữa Tắm Làm Sạch Dịu Nhẹ Giảm Ngứa Khô Da La Roche-Posay Lipikar Syndet AP+ 400ml', 'sua-tam-lam-sach-diu-nhe-giam-ngua-kho-da-la-roche-posay-lipikar-syndet-ap-plus-400ml', 'Gel tắm không chứa xà phòng chứa hoạt chất độc quyền Aqua Posae Filiformis giảm ngứa và làm dịu viêm da.', 'La Roche-Posay Lipikar Syndet AP+ là kem gel tắm làm sạch dịu nhẹ không chứa xà phòng, không hương liệu, dành riêng cho làn da rất khô, nhạy cảm và dễ bị chàm dị ứng ngứa ngáy. Sáng chế Aqua Posae Filiformis độc quyền giúp cân bằng hệ vi sinh microbiome trên da, kết hợp Niacinamide kháng viêm và 20% bơ hạt mỡ Shea Butter nuôi dưỡng và củng cố màng lipid bảo vệ toàn thân cho cả gia đình từ trẻ sơ sinh đến người lớn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua/Water, Glycerin, Sodium Laureth Sulfate, PEG-200 Hydrogenated Glyceryl Palmate, Coco-Betaine, Polysorbate 20, PEG-7 Glyceryl Cocoate, Niacinamide, Acrylates Copolymer, Butyrospermum Parkii Butter/Shea Butter, Citric Acid, Cocamide MEA, Disodium EDTA, Mannose, Polyquaternium-11, Sodium Benzoate, Sodium Chloride, Sodium Hydroxide, Vitreoscilla Ferment.', 'Lấy một lượng gel tắm bằng 1-2 lần nhấn ra lòng bàn tay ướt, xoa đều tạo bọt nhẹ và thoa khắp cơ thể đã làm ướt. Mát xa nhẹ nhàng và tắm sạch lại với nước, không chà xát mạnh khi lau khô.', 'Pháp', '400ml', 1, 4.85, 35, 50, 4, 0, 0, 'Aqua Posae Filiformis, Niacinamide, Shea Butter, Soap-Free Formula', NOW(), NOW()),
(121, 'Nước Cân Bằng Làm Dịu Cấp Ẩm Da Nhạy Cảm Bioderma Sensibio Tonique 250ml', 'nuoc-can-bang-lam-diu-cap-am-da-nhay-cam-bioderma-sensibio-tonique-250ml', 'Nước hoa hồng cấp nước tức thì chứa chiết xuất dưa leo và sáng chế D.A.F tăng cường ngưỡng dung nạp da.', 'Bioderma Sensibio Tonique là nước cân bằng sinh học hoàn hảo cho làn da nhạy cảm dễ kích ứng. Chứa chiết xuất dưa leo làm dịu mát làn da tức thì cùng phức hợp tự nhiên D.A.F (Dermatological Advanced Formulation) củng cố ngưỡng chịu đựng của da trước các tác nhân môi trường. Công thức không chứa cồn, không paraben, mang lại độ ẩm mượt tự nhiên và chuẩn bị da sẵn sàng đón nhận các bước dưỡng tiếp theo.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua/Water/Eau, Glycerin, Xylitol, Polysorbate 20, Mannitol, Rhamnose, Fructooligosaccharides, Cucumis Sativus (Cucumber) Fruit Extract, PEG-40 Hydrogenated Castor Oil, Allantoin, Propylene Glycol, Disodium EDTA, Cetrimonium Bromide, Sodium Hydroxide, Citric Acid.', 'Sau khi làm sạch mặt, đổ một lượng vừa đủ toner ra bông tẩy trang hoặc trực tiếp lên lòng bàn tay, vỗ nhẹ nhàng khắp mặt và cổ cho đến khi sản phẩm thẩm thấu hoàn toàn.', 'Pháp', '250ml', 1, 4.92, 36, 51, 5, 0, 0, 'Cucumber Extract, Allantoin, D.A.F. Patent, Glycerin', NOW(), NOW()),
(122, 'Kem Dưỡng Cấp Nước Chuyên Sâu Cho Da Khô Bioderma Hydrabio Crème 50ml', 'kem-duong-cap-nuoc-chuyen-sau-cho-da-kho-bioderma-hydrabio-creme-50ml', 'Kem dưỡng ẩm sinh học chứa sáng chế Aquagenium và Vitamin PP kích hoạt lại cơ chế ngậm nước tự nhiên.', 'Bioderma Hydrabio Crème mang lại giải pháp cấp ẩm chuyên sâu cho làn da khô mất nước. Bằng sáng chế sinh học Aquagenium giúp kích thích sản sinh các kênh vận chuyển nước Aquaporins giữa các tế bào da và tổng hợp Lipid biểu bì. Bổ sung Niacinamide (Vitamin PP) và Vitamin E chống oxy hóa, kem mang lại kết cấu mượt mà như nhung, nuôi dưỡng làn da sáng khỏe rạng rỡ từ bên trong.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua/Water/Eau, Glycerin, Isododecane, Cyclopentasiloxane, Dipropylene Glycol, Niacinamide, Squalane, Polymethylsilsesquioxane, C14-22 Alcohols, HDI/Trimethylol Hexyllactone Crosspolymer, Ammonium Acryloyldimethyltaurate/VP Copolymer, C12-20 Alkyl Glucoside, Tocopheryl Acetate, Pentylene Glycol, Polysilicone-11, Disodium EDTA, Salicylic Acid, Pyrus Malus (Apple) Seed Extract, Hexyldecanol, Sodium Hydroxide, Mannitol, Xylitol, Rhamnose, Sodium Hyaluronate, Parfum/Fragrance.', 'Thoa kem lên mặt và cổ vào mỗi buổi sáng và/hoặc tối sau bước tinh chất. Mát xa nhẹ nhàng theo chiều nâng cơ cho đến khi kem thẩm thấu hết.', 'Pháp', '50ml', 1, 4.85, 37, 52, 5, 1, 0, 'Aquagenium Patent, Niacinamide (Vitamin PP), Vitamin E, Salicylic Acid', NOW(), NOW()),
(123, 'Gel Tẩy Tế Bào Chết Dành Cho Da Dầu Mụn Bioderma Sébium Gel Gommant 100ml', 'gel-tay-te-bao-chet-danh-cho-da-dau-mun-bioderma-sebium-gel-gommant-100ml', 'Tẩy da chết kết hợp hạt vi cầu Polyethylene cùng Acid Glycolic và Salicylic làm sạch bít tắc lỗ chân lông.', 'Bioderma Sébium Gel Gommant là sản phẩm tẩy da chết cơ học kết hợp hóa học được thiết kế đặc thù cho da dầu mụn. Các hạt vi cầu siêu mịn nhẹ nhàng cuốn trôi tế bào sừng già cỗi bề mặt, trong khi bộ đôi Glycolic Acid & Salicylic Acid thẩm thấu sâu loại bỏ bã nhờn bít tắc trong lỗ chân lông. Phức hợp độc quyền Fluidactiv giúp điều hòa chất lượng bã nhờn sinh học, ngăn hình thành mụn mới.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua/Water/Eau, Polyethylene, Sodium Laureth Sulfate, Xanthan Gum, Lauryl Glucoside, Ginkgo Biloba Leaf Extract, Mannitol, Xylitol, Rhamnose, Fructooligosaccharides, Glycolic Acid, Salicylic Acid, Sodium Hydroxide, Disodium EDTA, Propylene Glycol, Fragrance (Parfum).', 'Thoa gel lên mặt còn hơi ẩm, tránh vùng mắt. Massage nhẹ nhàng bằng đầu ngón tay theo chuyển động tròn trong 1-2 phút rồi rửa sạch với nước. Dùng 1-2 lần mỗi tuần.', 'Pháp', '100ml', 1, 4.92, 38, 53, 5, 1, 0, 'Fluidactiv Patent, Glycolic Acid, Salicylic Acid, Micro-beads', NOW(), NOW()),
(124, 'Xịt Khoáng Làm Dịu Và Cấp Nước Tức Thì Bioderma Hydrabio Brume 300ml', 'xit-khoang-lam-diu-va-cap-nuoc-tuc-thi-bioderma-hydrabio-brume-300ml', 'Xịt khoáng cân bằng ion sinh học chứa Kẽm, Kali và sáng chế D.A.F xoa dịu làn da kích ứng.', 'Bioderma Hydrabio Brume là nước xịt khoáng đẳng trương sinh học được cân bằng nồng độ muối khoáng tương đồng với tế bào cơ thể, giúp da hấp thu trọn vẹn nước mà không gây khô ngược. Bổ sung Kẽm (Zinc) kháng viêm và Kali điều hòa độ ẩm, sản phẩm là cứu tinh cho làn da khi bị nóng rát, cháy nắng, ngồi phòng điều hòa lâu hay sau khi cạo râu/triệt lông.', 'https://images.unsplash.com/photo-1617897903246-719242758050?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water/Eau, Zinc Sulfate, Mannitol, Xylitol, Rhamnose, Fructooligosaccharides, Potassium Phosphate, Magnesium Sulfate, Sodium Citrate, Citric Acid, Sodium Chloride, Nitrogen.', 'Xịt cách mặt khoảng 20cm bất cứ khi nào cảm thấy da bị khô, căng rát hoặc nóng bừng. Để khô tự nhiên, không cần dùng khăn lau lại.', 'Pháp', '300ml', 1, 4.85, 39, 54, 5, 0, 0, 'Isotonic Minerals (Zinc, Potassium, Calcium), D.A.F. Patent', NOW(), NOW()),
(125, 'Son Dưỡng Môi Tái Tạo Căng Mọng Bioderma Atoderm Lèvres Baume 15ml', 'son-duong-moi-tai-tao-cang-mong-bioderma-atoderm-levres-baume-15ml', 'Sáp dưỡng môi giàu bơ hạt mỡ và dầu bơ tái tạo bờ môi khô nứt, bong tróc vảy môi hiệu quả.', 'Bioderma Atoderm Lèvres Baume là dòng dưỡng môi sinh học đặc trị cho môi cực kỳ khô ráp, nứt nẻ và tổn thương. Với thành phần bơ hạt mỡ hữu cơ nguyên chất kết hợp cùng chiết xuất tinh dầu quả bơ và tảo nâu Laminaria, sáp dưỡng tạo lớp màng nuôi dưỡng sâu, làm lành các vết nứt môi đau rát và trả lại đôi môi căng mịn, hồng hào tự nhiên.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Paraffinum Liquidum/Mineral Oil/Huile Minerale, Paraffin, Ozokerite, Butyrospermum Parkii (Shea) Butter, Tocopherol, Lecithin, Arachidyl Propionate, Tocopheryl Acetate, Retinyl Palmitate, Ethyl Linolenate, BHT, Ethyl Oleate, Ethyl Linoleate, Laminaria Ochroleuca Extract.', 'Thoa trực tiếp lên môi bất cứ khi nào thấy môi khô hoặc trước khi đi ngủ như một lớp mặt nạ ngủ cho môi. Thoa lót trước khi dùng son màu để bảo vệ môi.', 'Pháp', '15ml', 1, 4.92, 40, 55, 5, 0, 0, 'Shea Butter, Avocado Oil, Laminaria Ochroleuca Extract', NOW(), NOW()),
(126, 'Nước Khoáng Núi Lửa Làm Dịu Và Bảo Vệ Da Vichy Mineralizing Thermal Water 300ml', 'nuoc-khoang-nui-lua-lam-diu-va-bao-ve-da-vichy-mineralizing-thermal-water-300ml', 'Nước khoáng tự nhiên từ vùng núi lửa Auvergne với 15 khoáng chất quý giá giúp tái tạo đề kháng da.', 'Nước khoáng núi lửa Vichy Mineralizing Thermal Water được hình thành qua hàng ngàn năm dưới lòng sâu các ngọn núi lửa tại Pháp. Nguồn nước tích tụ 15 khoáng chất thiết yếu gồm Sắt, Canxi, Magiê, Kali, Natri, Silicon... đã được kiểm nghiệm lâm sàng có khả năng cân bằng độ pH cho da, tăng cường màng bảo vệ tế bào và kích thích quá trình tái tạo biểu bì tự nhiên.', 'https://images.unsplash.com/photo-1617897903246-719242758050?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water (Vichy Mineralizing Thermal Water 100% Pure & Natural).', 'Xịt đều khắp mặt cách khoảng 20-30cm. Để các giọt khoáng ngấm tự nhiên vào da khoảng 1 phút rồi dùng bông tẩy trang hoặc khăn giấy thấm nhẹ bớt phần nước dư.', 'Pháp', '300ml', 1, 4.85, 41, 56, 6, 0, 0, '15 Rare Minerals (Iron, Potassium, Calcium, Manganese, Silicon)', NOW(), NOW()),
(127, 'Gel Rửa Mặt Giảm Mụn Sạch Sâu Vichy Normaderm Phytosolution Intensive Purifying Gel 400ml', 'gel-rua-mat-giam-mun-sach-sau-vichy-normaderm-phytosolution-intensive-purifying-gel-400ml', 'Gel rửa mặt làm sạch sâu nguồn gốc thực vật chứa Kẽm, Đồng và Salicylic Acid kiềm dầu giảm mụn.', 'Vichy Normaderm Phytosolution Intensive Purifying Gel là sữa rửa mặt dạng gel làm sạch chuyên sâu gốc thực vật dành riêng cho làn da dầu mụn nhạy cảm. Công thức kết hợp Kẽm (Zinc Gluconate) kháng khuẩn, Đồng (Copper Gluconate) thanh lọc bã nhờn, Salicylic Acid tự nhiên tẩy tế bào chết và men vi sinh Probiotic củng cố hệ vi sinh vật có lợi trên da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua/Water, Coco-Betaine, Propanediol, PEG-120 Methyl Glucose Dioleate, Sodium Chloride, Sodium Cocoyl Glycinate, Dipropylene Glycol, Zinc Gluconate, Salicylic Acid, Bifida Ferment Lysate, Sodium Hydroxide, Sodium Benzoate, Phenoxyethanol, Copper Gluconate, Caprylyl Glycol, Tetrasodium Glutamate Diacetate, Parfum/Fragrance.', 'Lấy một lượng nhỏ tạo bọt với nước trong lòng bàn tay. Massage nhẹ nhàng lên mặt theo chuyển động tròn trong 1 phút, đặc biệt là vùng chữ T nhiều dầu, sau đó rửa sạch lại với nước mát.', 'Pháp', '400ml', 1, 4.92, 42, 57, 6, 1, 0, 'Zinc Gluconate, Copper Gluconate, Salicylic Acid, Bifida Ferment Lysate', NOW(), NOW()),
(128, 'Tinh Chất Tái Tạo Da Chống Lão Hóa Vichy Liftactiv Retinol Specialist Deep Wrinkles Serum 30ml', 'tinh-chat-tai-tao-da-chong-lao-hoa-vichy-liftactiv-retinol-specialist-deep-wrinkles-serum-30ml', 'Serum chứa 0.2% Retinol tinh khiết và 1% phân đoạn Probiotic làm mờ các nếp nhăn sâu trên da.', 'Vichy Liftactiv Retinol Specialist Serum được tối ưu hóa với công nghệ chống nếp nhăn chuyên sâu Retinol Guard, bảo vệ phân tử 0.2% Retinol nguyên chất ổn định đến giọt cuối cùng. Kết hợp cùng 1% phân đoạn lợi khuẩn Probiotic giúp tăng cường sức đề kháng và giảm thiểu tối đa kích ứng đỏ rát, serum tác động sâu vào các rãnh cười và nếp nhăn trán, trả lại bề mặt da mịn màng săn chắc.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water/Eau, Glycerin, Pentylene Glycol, Isononyl Isononanoate, Alcohol Denat., Dicaprylyl Ether, Glycine Soja Oil/Soybean Oil, Propylene Glycol, PEG-6 Caprylic/Capric Glycerides, Hydrolyzed Rice Protein, Hydroxyethylpiperazine Ethane Sulfonic Acid, Palmitoyl Tetrapeptide-7, Palmitoyl Tripeptide-1, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Sodium Hyaluronate, Sodium Hydroxide, Trisodium Ethylenediamine Disuccinate, Vitreoscilla Ferment, Retinol, Dicaprylyl Carbonate, Ammonium Polyacryloyldimethyl Taurate, Butylene Glycol, Caprylyl Glycol, Carbomer, Glyceryl Isostearate, Polysorbate 20, PPG-6-Decyltetradeceth-30, Sodium Lactate, Tocopherol, Xanthan Gum.', 'Sử dụng vào buổi tối. Tuần đầu dùng 2 lần/tuần, tăng dần tần suất theo phản ứng của da. Nhỏ 3-4 giọt lên mặt trước bước kem dưỡng. Ban ngày luôn thoa kem chống nắng SPF50+.', 'Pháp', '30ml', 1, 4.85, 43, 58, 6, 0, 0, '0.2% Pure Retinol, 1% Probiotic Fractions, Peptide Complex', NOW(), NOW()),
(129, 'Lăn Khử Mùi Khô Thoáng 48 Giờ Không Mùi Vichy Traitement Anti-Transpirant 48h 50ml', 'lan-khu-mui-kho-thoang-48-gio-khong-mui-vichy-traitement-anti-transpirant-48h-50ml', 'Lăn khử mùi và ức chế mồ hôi suốt 48 giờ chứa muối nhôm tinh khiết và nước khoáng núi lửa Vichy.', 'Lăn khử mùi Vichy Traitement Anti-Transpirant 48h là dòng lăn nách dược mỹ phẩm cao cấp với công nghệ vi hạt Aluminum Chlorohydrate hoạt tính kép tác động trực tiếp vào lỗ chân lông vùng da dưới cánh tay, kiểm soát lượng mồ hôi tiết ra hiệu quả suốt 48 giờ. Công thức êm dịu, không chứa cồn, không paraben, không để lại vệt ố vàng trên áo và an toàn cho cả làn da mới cạo nhổ.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water, Aluminum Chlorohydrate, Cetearyl Alcohol, Ceteareth-33, PPG-15 Stearyl Ether, Dimethicone, Iodopropynyl Butylcarbamate, PEG-4 Dilaurate, PEG-4 Laurate.', 'Lăn trực tiếp lên vùng da dưới cánh tay khô ráo và sạch sẽ mỗi sáng sau khi tắm. Để khô vài giây trước khi mặc áo.', 'Pháp', '50ml', 1, 4.92, 44, 59, 6, 0, 0, 'Aluminum Chlorohydrate, Vichy Volcanic Water, Dimethicone', NOW(), NOW()),
(130, 'Sữa Dưỡng Thể Cấp Ẩm Trẻ Hóa Làn Da Vichy Ideal Body Serum-Milk 200ml', 'sua-duong-the-cap-am-tre-hoa-lan-da-vichy-ideal-body-serum-milk-200ml', 'Sữa dưỡng thể dạng serum kết hợp Hyaluronic Acid, LHA và 10 loại dầu tinh chất cho da mịn màng sáng bóng.', 'Vichy Ideal Body Serum-Milk kết hợp sức mạnh phục hồi của một loại serum chống lão hóa cùng độ ẩm mượt dịu nhẹ của sữa dưỡng thể. Chứa Hyaluronic Acid cấp ẩm sâu, LHA tẩy da chết vi điểm làm mềm mịn bề mặt và 10 loại dầu thực vật quý (dầu jojoba, dầu quả mơ, dầu hạt chanh leo, v.v.), sản phẩm nuôi dưỡng da cơ thể săn chắc, đều màu và mềm mượt như lụa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua/Water, Glycerin, Isopropyl Palmitate, Alcohol Denat., Methyl Methacrylate Crosspolymer, Isononyl Isononanoate, Pentaerythrityl Tetraethylhexanoate, Zea Mays Starch/Corn Starch, Tin Oxide, CI 77891/Titanium Dioxide, CI 77491/Iron Oxides, Mica, Macadamia Ternifolia Seed Oil, Rosa Canina Fruit Oil, Ribes Nigrum Seed Oil/Black Currant Seed Oil, Sodium Polyacrylate, Helianthus Annuus Seed Oil/Sunflower Seed Oil, Sodium Hyaluronate, Coriandrum Sativum Fruit Oil/Coriander Fruit Oil, Simmondsia Chinensis Oil/Jojoba Seed Oil, Prunus Armeniaca Kernel Oil/Apricot Kernel Oil, Ammonium Polyacryldimethyltauramide, Disodium EDTA, Capryloyl Salicylic Acid, Caprylyl Glycol, Passiflora Edulis Seed Oil, Oryza Sativa Bran Oil/Rice Bran Oil, Parfum/Fragrance.', 'Thoa đều khắp cơ thể sau khi tắm khi da còn hơi ẩm, mát xa nhẹ nhàng cho sữa dưỡng thẩm thấu hoàn toàn. Không thoa lên vùng da có vết thương hở.', 'Pháp', '200ml', 1, 4.85, 45, 60, 6, 1, 0, 'Hyaluronic Acid, LHA, 10 Essential Botanical Oils', NOW(), NOW()),
(131, 'Nước Tẩy Trang Giảm Dầu Mụn Dịu Da SVR Sebiaclear Eau Micellaire 400ml', 'nuoc-tay-trang-giam-dau-mun-diu-da-svr-sebiaclear-eau-micellaire-400ml', 'Nước tẩy trang chứa Gluconolactone (PHA) và Micelles làm sạch sâu bã nhờn, thông thoáng chân lông.', 'SVR Sebiaclear Eau Micellaire là nước tẩy trang làm sạch da chuyên biệt cho da dầu mụn nhạy cảm. Công thức đột phá chứa hoạt chất Gluconolactone (PHA) làm sạch tế bào chết dịu nhẹ gấp nhiều lần AHA mà không gây châm chích, kết hợp cùng các hạt Micelles sinh học hút trọn lớp trang điểm cứng đầu và bã nhờn dư thừa, mang lại làn da sạch thoáng tinh khiết.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua (Purified Water), Poloxamer 184, PEG-7 Glyceryl Cocoate, Pentylene Glycol, Propanediol, Gluconolactone, 1,2-Hexanediol, Citric Acid, Sodium Hydroxide, Cetrimonium Bromide, Parfum (Fragrance).', 'Thấm ướt bông tẩy trang với dung dịch SVR Micellaire, lau nhẹ nhàng khắp mặt và vùng mắt môi theo hướng từ trong ra ngoài. Lặp lại cho đến khi miếng bông sạch hoàn toàn.', 'Pháp', '400ml', 1, 4.92, 46, 61, 7, 0, 0, 'Gluconolactone (PHA), Micelles, Purifying Agents', NOW(), NOW()),
(132, 'Nước Cân Bằng Tinh Chỉnh Lỗ Chân Lông SVR Sebiaclear Micro-Peel 150ml', 'nuoc-can-bang-tinh-chinh-lo-chan-long-svr-sebiaclear-micro-peel-150ml', 'Nước hoa hồng dạng lỏng chứa 4% Niacinamide, Salicylic Acid và Kẽm 1% thanh lọc dầu thừa và mờ thâm.', 'SVR Sebiaclear Micro-Peel là sản phẩm toner dạng tinh chất dưỡng da đầu tiên kết hợp nồng độ cao các hoạt chất da liễu: 4% Niacinamide làm dịu sưng viêm và mờ thâm mụn, Salicylic Acid (BHA) thông thoáng lỗ chân lông cùng Kẽm 1% điều hòa lượng bã nhờn tiết ra. Kết cấu lỏng nhẹ như nước, thẩm thấu ngay sau 5 giây, mang lại làn da mịn màng sạch mụn chỉ sau 7 ngày.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua/Water/Eau, Alcohol Denat., Niacinamide, Zinc Gluconate, Salicylic Acid, Sodium Hydroxide, Lactobionic Acid, Propanediol, Caprylyl Glycol, Citric Acid, Polysorbate 20, Parfum/Fragrance.', 'Thoa mỗi ngày vào buổi sáng và tối bằng bông tẩy trang hoặc vỗ trực tiếp bằng tay lên toàn bộ khuôn mặt, tập trung vào những vùng có lỗ chân lông to và mụn đầu đen.', 'Pháp', '150ml', 1, 4.85, 47, 62, 7, 0, 0, '4% Niacinamide, Salicylic Acid (BHA), 1% Zinc, Lactobionic Acid', NOW(), NOW()),
(133, 'Tinh Chất Phục Hồi Cấp Ẩm Chuyên Sâu SVR [B3] Ampoule Hydra 30ml', 'tinh-chat-phuc-hoi-cap-am-chuyen-sau-svr-b3-ampoule-hydra-30ml', 'Ampoule chứa 5% Vitamin B3 (Niacinamide) và 3 loại Hyaluronic Acid làm dịu và phục hồi màng ẩm bảo vệ da.', 'SVR [B3] Ampoule Hydra là huyết thanh cô đặc giúp củng cố hàng rào phòng thủ của làn da yếu, nhạy cảm và mất nước. Chứa 5% Niacinamide tinh khiết giúp kích thích tổng hợp Ceramide tự nhiên, kết hợp cùng 3 kích thước phân tử Hyaluronic Acid (trọng lượng phân tử trung bình, cao và rất cao) cung cấp độ ẩm đa tầng, làm dịu tức thì hiện tượng ửng đỏ và căng rát khó chịu.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua/Water/Eau, Glycerin, Niacinamide, Isopentyldiol, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, 1,2-Hexanediol, Carbomer, Caprylyl Glycol, Pentylene Glycol, Sodium Hydroxide.', 'Nhỏ 2-3 giọt serum vào sáng và tối lên mặt và cổ trước bước kem dưỡng ẩm, hoặc trộn trực tiếp 1 giọt vào kem dưỡng hàng ngày của bạn.', 'Pháp', '30ml', 1, 4.92, 48, 63, 7, 0, 0, '5% Niacinamide (Vitamin B3), 3 Hyaluronic Acids', NOW(), NOW()),
(134, 'Kem Dưỡng Phục Hồi Làm Dịu Da Khẩn Cấp SVR Cicavit+ Crème 40ml', 'kem-duong-phuc-hoi-lam-diu-da-khan-cap-svr-cicavit-plus-creme-40ml', 'Kem dưỡng phục hồi tổn thương da nhanh gấp 7 lần chứa phức hợp Erasyal và đường sinh học Prebiotic.', 'SVR Cicavit+ Crème là giải pháp da liễu giúp tăng tốc quá trình làm lành vết thương trên da gấp 7 lần so với cơ chế tự nhiên. Công thức chứa 43% phức hợp phục hồi Erasyal kích thích tái tạo mô da, Polysaccharide chống bám dính vi khuẩn và đường Prebiotic cân bằng hệ vi sinh da. Sản phẩm êm dịu tuyệt đối, không gây nhờn dính, phù hợp cho da trầy xước, sau nặn mụn, laser hay peel da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua/Water/Eau, Hydrogenated Polyisobutene, Butyrospermum Parkii (Shea) Butter, Glycerin, Dimethiconol Behenate, Orbignya Oleifera Seed Oil, Cetyl Alcohol, Glyceryl Stearate, PEG-100 Stearate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Cera Alba/Beeswax, Glyceryl Behenate, Dimethicone, Tocopheryl Acetate, Alpha-Glucan Oligosaccharide, Disodium Acetyl Glucosamine Phosphate, Caffeyl Glucoside, Citric Acid, Disodium EDTA, Sodium Polyacrylate, Xanthan Gum, Polysorbate 60, Sorbitan Isostearate, Pentylene Glycol, Caprylyl Glycol.', 'Thoa lên vùng da bị tổn thương, kích ứng đã được làm sạch và lau khô 2 lần mỗi ngày cho đến khi da phục hồi hoàn toàn.', 'Pháp', '40ml', 1, 4.85, 49, 64, 7, 0, 0, '43% Micro-Repair Complex, Prebiotic Sugar, Erasyal', NOW(), NOW()),
(135, 'Nước Xịt Chống Nắng Trong Suốt Không Trôi SVR Sun Secure Eau Solaire SPF50+ 200ml', 'nuoc-xit-chong-nang-trong-suot-khong-troi-svr-sun-secure-eau-solaire-spf50-200ml', 'Nước chống nắng phân tầng độc đáo 60% dầu dưỡng và 40% nước khoáng bảo vệ da toàn diện trước 4 loại tia.', 'SVR Sun Secure Eau Solaire SPF50+ là sản phẩm chống nắng đột phá với kết cấu dạng nước 2 pha (Bi-phase) cực kỳ tươi mát và trong suốt vô hình trên da. Bảo vệ quang phổ rộng trước 100% các loại tia: UVA, UVB, ánh sáng nhìn thấy được (HEV) và tia hồng ngoại (IR). Công thức phân hủy sinh học thân thiện với môi trường biển và san hô, chống trôi nước và mồ hôi tối ưu.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua/Water/Eau, Dicaprylyl Carbonate, Coco-Caprylate/Caprate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Diethylhexyl Butamido Triazone, Ethylhexyl Triazone, Silica, Niacinamide, Bixa Orellana Seed Extract, Glycine Soja (Soybean) Oil, Lepidium Sativum Sprout Extract, Tocopherol, Parfum (Fragrance).', 'Lắc kỹ bình xịt ít nhất 5 giây trước khi dùng để 2 pha hòa lẫn hoàn toàn. Xịt đều lên mặt và cơ thể cách khoảng 20cm trước khi ra ngoài nắng 15 phút.', 'Pháp', '200ml', 1, 4.92, 50, 65, 7, 1, 0, '4 Organic UV Filters, Bi-Phase Technology, Niacinamide, Detoxophane', NOW(), NOW()),
(136, 'Gel Rửa Mặt Không Chứa Xà Phòng Cho Da Dầu Mụn Avène Cleanance Cleansing Gel 400ml', 'gel-rua-mat-khong-chua-xa-phong-cho-da-dau-mun-avene-cleanance-cleansing-gel-400ml', 'Gel rửa mặt làm sạch dịu nhẹ kiểm soát bã nhờn chứa hoạt chất độc quyền Comedoclastin và nước khoáng Avène.', 'Avène Cleanance Cleansing Gel là sữa rửa mặt dịu nhẹ với độ pH 5.5 chuẩn sinh lý, không chứa xà phòng, phù hợp cho da dầu mụn và da đang điều trị da liễu. Chứa hoạt chất được cấp bằng sáng chế Comedoclastin chiết xuất từ cây kế sữa giúp điều hòa quá trình tăng tiết bã nhờn và giảm thiểu hình thành vi nhân mụn, kết hợp nước khoáng Avène làm dịu da tức thì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Avene Thermal Spring Water (Avene Aqua), Water (Aqua), Zinc Coceth Sulfate, Lauryl Betaine, Decyl Glucoside, Ceteareth-60 Myristyl Glycol, PEG-7 Glyceryl Cocoate, Polysorbate 20, Citric Acid, Fragrance (Parfum), Green 5 (CI 61570), Isopropyl Alcohol, PEG-40 Hydrogenated Castor Oil, PEG-6, Silybum Marianum Fruit Extract, Sodium Benzoate, Sodium Chloride, Sodium Hydroxide, Trisodium Ethylenediamine Disuccinate, Yellow 5 (CI 19140), Zinc Gluconate.', 'Thoa lên mặt ẩm vào sáng và tối, tạo bọt nhẹ nhàng bằng nước ấm rồi xoa đều khắp mặt và cổ. Rửa sạch lại bằng nước và lau khô bằng khăn mềm.', 'Pháp', '400ml', 1, 4.85, 51, 66, 8, 1, 0, 'Comedoclastin (Milk Thistle), Avène Thermal Spring Water, Zinc Gluconate', NOW(), NOW()),
(137, 'Nước Cân Bằng Dịu Da Kiềm Dầu Hai Pha Avène Cleanance Mat Mattifying Toner 200ml', 'nuoc-can-bang-diu-da-kiem-dau-hai-pha-avene-cleanance-mat-mattifying-toner-200ml', 'Nước hoa hồng kiềm dầu 2 lớp kết hợp bột khoáng hấp thu bã nhờn và Kẽm Gluconate kháng viêm.', 'Avène Cleanance Mat Mattifying Toner sở hữu kết cấu 2 tầng độc đáo gồm lớp nước khoáng thanh lọc và lớp bột silica khoáng hấp thụ dầu nhờn. Lắc đều trước khi dùng giúp các vi hạt bột khoáng phân tán đều, hút sạch lượng dầu thừa bóng loáng tức thì trên bề mặt da, làm se khít lỗ chân lông và giữ cho khuôn mặt luôn khô ráo, mịn màng suốt cả ngày dài.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Avene Thermal Spring Water (Avene Aqua), Dipropylene Glycol, Alcohol Denat., SD Alcohol 39-C, Zinc Gluconate, Fragrance (Parfum), Glyceryl Laurate, PEG-40 Hydrogenated Castor Oil, PPG-26-Buteth-26, Salicylic Acid, Silica, Stearalkonium Hectorite, Triethanolamine, Water (Aqua).', 'Lắc thật kỹ trước khi sử dụng. Đổ toner ra bông tẩy trang và thoa đều lên toàn bộ khuôn mặt đã làm sạch, tập trung vào vùng chữ T (trán, mũi, cằm).', 'Pháp', '200ml', 1, 4.92, 52, 67, 8, 1, 1, 'Silica Mineral Powders, Zinc Gluconate, Avène Thermal Spring Water', NOW(), NOW()),
(138, 'Kem Dưỡng Phục Hồi Tái Tạo Biểu Bì Avène Cicalfate+ Restorative Protective Cream 40ml', 'kem-duong-phuc-hoi-tai-tao-bieu-bi-avene-cicalfate-plus-restorative-protective-cream-40ml', 'Kem dưỡng phục hồi da tổn thương chứa hoạt chất sinh học [C+-Restore] và phức hợp Đồng - Kẽm kháng khuẩn.', 'Avène Cicalfate+ Restorative Protective Cream là dòng kem phục hồi huyền thoại được các chuyên gia da liễu toàn cầu tin dùng. Ứng dụng sáng chế độc quyền [C+-Restore] chiết xuất từ vi khuẩn sinh học trong nguồn khoáng Avène giúp tăng tốc độ tái tạo mô da non gấp 4 lần, kết hợp cùng phức hợp Đồng Sunfat (Copper Sulfate) và Kẽm Sunfat (Zinc Sulfate) tạo màng chắn bảo vệ kháng khuẩn tuyệt đối.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Avene Thermal Spring Water (Avene Aqua), Caprylic/Capric Triglyceride, Mineral Oil (Paraffinum Liquidum), Glycerin, Hydrogenated Vegetable Oil, Zinc Oxide, Propylene Glycol, Polyglyceryl-2 Sesquiisostearate, PEG-22/Dodecyl Glycol Copolymer, Aluminum Stearate, Aquaphilus Dolomiae Ferment Filtrate, Arginine, Beeswax (Cera Alba), Copper Sulfate, Magnesium Stearate, Magnesium Sulfate, Microcrystalline Wax (Cera Microcristallina), Tromethamine, Zinc Sulfate.', 'Thoa kem 1-2 lần mỗi ngày lên vùng da bị kích ứng, tổn thương sau khi đã được làm sạch và lau khô nhẹ nhàng. Có thể dùng cho cả trẻ sơ sinh, trẻ em và người lớn.', 'Pháp', '40ml', 1, 4.85, 53, 68, 8, 0, 0, '[C+-Restore] Postbiotic, Copper-Zinc Sulfate Complex, Avène Water', NOW(), NOW()),
(139, 'Nước Xịt Khoáng Làm Dịu Da Chống Kích Ứng Eau Thermale Avène Thermal Spring Water 300ml', 'nuoc-xit-khoang-lam-diu-da-chong-kich-ung-eau-thermale-avene-thermal-spring-water-300ml', 'Nước xịt khoáng vô trùng độc quyền từ suối khoáng Cévennes làm dịu mát hạ nhiệt da tức thì.', 'Eau Thermale Avène Thermal Spring Water là sản phẩm xịt khoáng huyền thoại số 1 châu Âu, được đóng chai trực tiếp tại nguồn khoáng vô trùng ở thung lũng Orb vùng Cévennes nước Pháp. Chứa hàm lượng khoáng cân bằng hoàn hảo tỷ lệ Canxi/Magie lý tưởng 2:1 và hoạt chất sinh học I-Modulia từ vi khuẩn Aquaphilus Dolomiae, nước xịt khoáng giúp giảm kích ứng đến 64% chỉ sau 5 phút, kháng viêm, làm dịu vết bỏng rát và phục hồi sinh khí cho làn da nhạy cảm nhất.', 'https://images.unsplash.com/photo-1617897903246-719242758050?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Avene Thermal Spring Water (Avene Aqua), Gas: Nitrogen.', 'Để bình xịt cách mặt 20cm, xịt đều theo vòng tròn quanh mặt. Giữ nguyên trên da trong 2-3 phút để khoáng chất tự thẩm thấu rồi vỗ nhẹ hoặc dùng bông lau bớt nước đọng thừa.', 'Pháp', '300ml', 1, 4.92, 54, 69, 8, 0, 0, '100% Avène Thermal Spring Water, Neutral pH 7.5, Low Mineral Content (266mg/l)', NOW(), NOW()),
(140, 'Kem Chống Nắng Dịu Nhẹ Không Mùi Avène Fluide Fragrance-Free SPF50+ 50ml', 'kem-chong-nang-diu-nhe-khong-mui-avene-fluide-fragrance-free-spf50-50ml', 'Kem chống nắng chứa màng lọc độc quyền TriAsorB bảo vệ da trước tia UV và ánh sáng xanh năng lượng cao HEV.', 'Avène Fluide Fragrance-Free SPF50+ ứng dụng công nghệ màng lọc chống nắng thế hệ mới nhất TriAsorB lấy cảm hứng từ sắc tố melanin tự nhiên của con người, mở rộng phổ bảo vệ chống lại cả tia UVA, UVB và ánh sáng xanh năng lượng cao HEV Blue Light lên đến 450nm. Kết cấu dạng sữa lỏng nhẹ tệp da sau 3 giây, không để lại vệt trắng, không mùi hương và không cay mắt.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Avene Thermal Spring Water (Avene Aqua), C12-15 Alkyl Benzoate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Ethylhexyl Triazone, Phenylene Bis-Diphenyltriazine, Water (Aqua), Glycerin, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Titanium Dioxide (CI 77891), Potassium Cetyl Phosphate, Myristyl Alcohol, Oryza Sativa (Rice) Starch, Stearyl Alcohol, Isononyl Isononanoate, VP/Eicosene Copolymer, Alumina, Benzoic Acid, Caprylic/Capric Triglyceride, Caprylyl Glycol, Glyceryl Behenate, Glyceryl Dibehenate, PPG-1-PEG-9 Lauryl Glycol Ether, Red 33 (CI 17200), Tocopheryl Glucoside, Tribehenin, Xanthan Gum, Zinc Gluconate.', 'Thoa một lượng kem tương đương 1 ngón tay lên mặt và cổ trước khi ra ngoài nắng 20 phút. Thoa lại đều đặn mỗi 2 tiếng khi tiếp xúc trực tiếp với ánh nắng mặt trời.', 'Pháp', '50ml', 1, 4.85, 20, 70, 8, 0, 0, 'TriAsorB Filter, Pre-tocopheryl, Avène Thermal Spring Water', NOW(), NOW()),
(141, 'Kem Chống Nắng Kiểm Soát Dầu Eucerin Sun Gel-Cream Dry Touch Oil Control SPF50+ 50ml', 'kem-chong-nang-kiem-soat-dau-eucerin-sun-gel-cream-dry-touch-oil-control-spf50-50ml', 'Kem chống nắng kiềm dầu 8H chứa Carnitine và Licochalcone A bảo vệ da và ngừa thâm mụn.', 'Eucerin Sun Gel-Cream Dry Touch Oil Control SPF50+ là sản phẩm chống nắng được ưa chuộng hàng đầu dành cho da dầu mụn. Ứng dụng công nghệ quang phổ tiên tiến Advanced Spectral Technology bảo vệ da trước tia UVA/UVB và tia HEV ánh sáng xanh, kết hợp hoạt chất L-Carnitine điều hòa bã nhờn và 3 loại hạt hấp thụ lipid tạo hiệu ứng khô thoáng tức thì kéo dài đến 8 giờ.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua, C12-15 Alkyl Benzoate, Alcohol Denat., Butyl Methoxydibenzoylmethane, Butylene Glycol Dicaprylate/Dicaprate, Ethylhexyl Triazone, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Dibutyl Adipate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Phenylbenzimidazole Sulfonic Acid, Silica, Tapioca Starch, Polymethylsilsesquioxane, Carnitine, Glycyrrhetinic Acid, Glycyrrhiza Inflata Root Extract, Glycerin, Sodium Hydroxide, Sodium Chloride, Trisodium EDTA, Hydroxypropyl Methylcellulose, Ethylhexylglycerin, Phenoxyethanol.', 'Thoa kem chống nắng mỗi sáng sau khi hoàn tất các bước dưỡng da. Chấm đều lên các điểm trán, má, mũi, cằm và thoa đều cho kem tiệp vào da.', 'Đức', '50ml', 1, 4.92, 21, 71, 9, 0, 0, 'L-Carnitine, Licochalcone A, Glycyrrhetinic Acid', NOW(), NOW()),
(142, 'Tinh Chất Giảm Thâm Nám Đột Phá Eucerin Spotless Brightening Booster Serum 30ml', 'tinh-chat-giam-tham-nam-dot-pha-eucerin-spotless-brightening-booster-serum-30ml', 'Serum giảm thâm nám gấp 10 lần chứa hoạt chất độc quyền Thiamidol và Hyaluronic Acid đậm đặc.', 'Eucerin Spotless Brightening Booster Serum chứa hoạt chất đột phá Thiamidol được các nhà khoa học Eucerin nghiên cứu suốt 10 năm từ hơn 50.000 hợp chất, tác động trực tiếp vào gốc rễ enzyme Tyrosinase ức chế sản sinh hắc tố Melanin. Kết hợp Hyaluronic Acid chuỗi ngắn và dài, serum làm mờ thâm nám đốm nâu chỉ sau 2 tuần sử dụng đều đặn và ngăn ngừa nám quay trở lại.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua, Alcohol Denat., Butylene Glycol, Glycerin, Octocrylene, Isopropyl Palmitate, Cetearyl Isononanoate, Distarch Phosphate, Methylpropanediol, Isobutylamido Thiazolyl Resorcinol (Thiamidol), Sodium Ascorbyl Phosphate, Sodium Hyaluronate, Glycyrrhiza Inflata Root Extract, Tocopherol, Glucosylrutin, Sodium Stearoyl Glutamate, Glyceryl Stearate, Sodium Polyacrylate, Dimethicone, Isoquercitrin, Citric Acid, Sodium Chloride, Trisodium EDTA, Caprylyl Glycol, Phenoxyethanol, Parfum.', 'Sử dụng mỗi ngày vào buổi sáng và tối sau khi làm sạch da mặt. Nhấn 1-2 lần thoa đều lên mặt và cổ trước kem dưỡng. Không dùng quá 4 lần các sản phẩm chứa Thiamidol mỗi ngày.', 'Đức', '30ml', 1, 4.85, 22, 72, 9, 1, 0, 'Patented Thiamidol, Concentrated Hyaluronic Acid, Licochalcone A', NOW(), NOW()),
(143, 'Kem Dưỡng Phục Hồi Khẩn Cấp Da Kích Ứng Eucerin UltraSensitive Repair Cream 50ml', 'kem-duong-phuc-hoi-khan-cap-da-kich-ung-eucerin-ultrasensitive-repair-cream-50ml', 'Kem dưỡng làm dịu da tức thì sau 2 giờ chứa hoạt chất SymSitive và 0% chất bảo quản với thiết kế vòi chống khuẩn.', 'Eucerin UltraSensitive Repair Cream là dòng kem dưỡng đặc trị cho làn da siêu nhạy cảm và tổn thương hàng rào bảo vệ. Hoạt chất độc quyền SymSitive tác động trực tiếp vào các thụ thể thần kinh cảm thụ trên da, ngăn chặn phản ứng kích ứng quá mức và làm dịu cảm giác châm chích nóng rát ngay tức thì. Thiết kế vỏ chai chân không kép chống nhiễm khuẩn và oxy hóa tuyệt đối.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua, Glycerin, Butyrospermum Parkii Butter, Panthenol, Cetyl Palmitate, Methyl Palmitate, Olus Oil, Pentylene Glycol, Methylpropanediol, Sodium Polyacrylate, 4-t-Butylcyclohexanol (Trans-Isomer), Caprylyl Glycol.', 'Thoa kem mỗi sáng và tối lên vùng mặt, cổ và ngực sau bước làm sạch. Nhẹ nhàng massage cho dưỡng chất thấm sâu vào da.', 'Đức', '50ml', 1, 4.92, 23, 73, 9, 0, 0, 'SymSitive (4-t-Butylcyclohexanol), Squalane, Shea Butter', NOW(), NOW()),
(144, 'Gel Tẩy Tế Bào Chết Ngừa Mụn Eucerin ProAcne Solution Scrub 100ml', 'gel-tay-te-bao-chet-ngua-mun-eucerin-proacne-solution-scrub-100ml', 'Tẩy tế bào chết không chứa dầu với các vi hạt Lactic Acid làm sạch nhẹ nhàng và thông thoáng lỗ chân lông.', 'Eucerin ProAcne Solution Scrub là sản phẩm tẩy da chết chuyên sâu cho da mụn với công thức không chứa dầu và hạt vi cầu làm sạch thông minh. Tinh chất Lactic Acid (AHA) dịu nhẹ len lỏi vào từng nang lông, làm tan rã các liên kết tế bào sừng chết bít tắc và vi khuẩn gây mụn mà không gây rách da hay trầy xước bề mặt mụn viêm.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Aqua, Coco Glucoside, Coco-Betaine, Microcrystalline Cellulose, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Lactic Acid, Sodium Chloride, Sodium Hydroxide, Cellulose, Mannitol, Polyquaternium-10, Sodium Benzoate, Phenoxyethanol, Benzophenone-4, Parfum, CI 77289.', 'Làm ẩm mặt, lấy một lượng nhỏ thoa lên da và massage nhẹ nhàng bằng chuyển động tròn trong 1-2 phút. Rửa sạch lại thật kỹ với nước ấm. Dùng 1 lần/tuần.', 'Đức', '100ml', 1, 4.85, 24, 74, 9, 1, 0, 'Lactic Acid (AHA), Micro-particles, Pore-refining Complex', NOW(), NOW()),
(145, 'Kem Dưỡng Giảm Khô Nứt Da Chân Eucerin UreaRepair Plus 10% Urea Foot Cream 100ml', 'kem-duong-giam-kho-nut-da-chan-eucerin-urearepair-plus-10-urea-foot-cream-100ml', 'Kem dưỡng gót chân chứa 10% Urea, Ceramide và NMFs phục hồi làn da chân khô ráp nứt nẻ suốt 48H.', 'Eucerin UreaRepair Plus 10% Urea Foot Cream được các chuyên gia da liễu khuyên dùng cho các trường hợp gót chân khô nứt, da chân chai cứng hoặc người mắc bệnh tiểu đường có da chân bong tróc. Sự phối hợp của 10% Urea giữ nước mạnh mẽ, Ceramide hàn gắn hàng rào lipid và các yếu tố giữ ẩm tự nhiên (NMFs) đem lại đôi bàn chân mềm mại, giảm nứt nẻ và ngăn tái phát trong 48 giờ.', 'https://images.unsplash.com/photo-1556228852-80b6e5eeff06?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Aqua, Urea, Glycerin, Cetearyl Alcohol, Caprylic/Capric Triglyceride, Glyceryl Stearate, Ethylhexyl Cocoate, Hydrogenated Coco-Glycerides, Octyldodecanol, Sodium Lactate, Glycine, Benzyl Alcohol, Dimethicone, Carbomer, Lactic Acid, Ceramide NP, Cholesterol, Alanine, Threonine, Carnitine, Helianthus Annuus Seed Oil, Phenoxyethanol.', 'Rửa chân sạch và lau khô. Thoa kem đều đặn mỗi sáng và tối lên vùng gót chân và bàn chân, mát xa nhẹ nhàng cho kem thẩm thấu hết.', 'Đức', '100ml', 1, 4.92, 25, 75, 9, 0, 0, '10% Urea, Ceramides, Natural Moisturizing Factors (NMFs)', NOW(), NOW()),
(146, 'Sữa Rửa Mặt Tạo Bọt Tơ Tằm Trắng Mịn Senka Perfect Whip 120g', 'sua-rua-mat-tao-bot-to-tam-trang-min-senka-perfect-whip-120g', 'Bọt tơ tằm trắng xốp dày mịn hạt bọt siêu nhỏ len lỏi làm sạch sâu mà không làm khô căng da mặt.', 'Senka Perfect Whip là dòng sữa rửa mặt tạo bọt số 1 Nhật Bản suốt 15 năm liền. Công nghệ tạo bọt độc quyền Aqua in Pool cùng tinh chất tơ tằm trắng Mayu Haku tự nhiên và gấp đôi phân tử Hyaluronic Acid tạo nên lớp bọt dày xốp mịn màng như đám mây. Lớp bọt hoạt động như đệm đỡ giảm ma sát cho da, nhẹ nhàng cuốn sạch bụi bẩn và bã nhờn sâu trong lỗ chân lông.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water (Aqua), Stearic Acid, PEG-8, Myristic Acid, Potassium Hydroxide, Glycerin, Lauric Acid, Alcohol, Butylene Glycol, Glyceryl Stearate SE, Polyquaternium-7, PEG/PPG-14/7 Dimethyl Ether, Sodium Hyaluronate, Sodium Acetylated Hyaluronate, Sericin, Hydrolyzed Silk, Disodium EDTA, Sodium Metabisulfite, Citric Acid, Potassium Sorbate, Fragrance (Parfum).', 'Lấy một lượng kem khoảng 2cm ra lòng bàn tay, thêm một chút nước và đánh bọt bông xốp dày đặc. Áp lớp bọt lên mặt và mát xa nhẹ nhàng trong 1 phút, sau đó rửa sạch với nước mát.', 'Nhật Bản', '120g', 1, 4.85, 26, 76, 10, 1, 1, 'White Cocoon Essence, Double Hyaluronic Acid, Aqua in Pool', NOW(), NOW()),
(147, 'Nước Tẩy Trang Dưỡng Sáng Mờ Thâm Senka All Clear Water Micellar Formula White 230ml', 'nuoc-tay-trang-duong-sang-mo-tham-senka-all-clear-water-micellar-formula-white-230ml', 'Nước tẩy trang dịu nhẹ chứa hoa anh đào Fuji Nhật Bản và cam thảo giúp làm sạch và dưỡng sáng mờ thâm.', 'Senka All Clear Water White kết hợp công nghệ Micellar làm sạch tinh khiết cùng chiết xuất hoa anh đào núi Phú Sĩ Fuji và rễ cam thảo tự nhiên. Sản phẩm nhẹ nhàng hòa tan và làm sạch 3 lớp cặn bẩn gồm cặn trang điểm, bụi mịn ô nhiễm và bã nhờn sâu trong lỗ chân lông, đồng thời ức chế hắc sắc tố Melanin, nuôi dưỡng làn da sáng mịn rạng ngời.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water (Aqua), Dipropylene Glycol, PE/PPG-50/40 Dimethyl Ether, Glycerin, Phenoxyethanol, Methylparaben, Sodium Citrate, Citric Acid, Disodium EDTA, Sodium Hyaluronate, Butylene Glycol, Sodium Acetylated Hyaluronate, Sericin, Potassium Sorbate, Prunus Speciosa Leaf Extract, Glycyrrhiza Glabra (Licorice) Root Extract.', 'Thấm đều dung dịch ra bông tẩy trang, nhẹ nhàng lau khắp mặt và cổ. Không cần chà xát mạnh. Có thể rửa lại với nước hoặc sữa rửa mặt nếu muốn.', 'Nhật Bản', '230ml', 1, 4.92, 27, 77, 10, 1, 1, 'Fuji Sakura Extract, Licorice Root Extract, White Silk Essence, Double HA', NOW(), NOW()),
(148, 'Sữa Chống Nắng Dịu Nhẹ Nâng Tông Senka Perfect UV Gentle Milk SPF50+ 50ml', 'sua-chong-nang-diu-nhe-nang-tong-senka-perfect-uv-gentle-milk-spf50-50ml', 'Sữa chống nắng vật lý lai hóa học kháng nước, nâng tông tự nhiên và không gây bết rít da.', 'Senka Perfect UV Gentle Milk là sữa chống nắng với chỉ số chống nắng tối ưu SPF50+ PA++++ bảo vệ da toàn diện trước tia tử ngoại. Công thức chứa tơ tằm trắng Mayu Haku và hạt phấn mịn siêu nhẹ giúp nâng tông da sáng hồng hào tự nhiên, kiềm dầu bề mặt và kháng nước, kháng mồ hôi hiệu quả, rất thích hợp dùng làm kem lót trang điểm hàng ngày.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'COMBINATION', 'Water (Aqua), Dimethicone, Zinc Oxide, Ethylhexyl Methoxycinnamate, Cyclopentasiloxane, Talc, Methyl Methacrylate Crosspolymer, Alcohol, Isopropyl Myristate, Octocrylene, Titanium Dioxide, PEG-9 Polydimethylsiloxyethyl Dimethicone, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Glycerin, Silica, Sodium Hyaluronate, Sodium Acetylated Hyaluronate, Sericin, Hydrolyzed Silk, Tocopherol, BHT.', 'Lắc đều chai trước khi dùng. Thoa một lượng vừa đủ lên mặt và cổ trước khi tiếp xúc ánh nắng 15-20 phút.', 'Nhật Bản', '50ml', 1, 4.85, 28, 78, 10, 0, 0, 'Zinc Oxide, Titanium Dioxide, White Silk Extract, Double HA', NOW(), NOW()),
(149, 'Mặt Nạ Dưỡng Trắng Dịu Mát Senka Perfect Aqua White Mask Extra White 25ml', 'mat-na-duong-trang-diu-mat-senka-perfect-aqua-white-mask-extra-white-25ml', 'Mặt nạ sợi vải không dệt giàu tinh chất dưỡng trắng Tranexamic Acid và chiết xuất hoa hồng Nhật Bản.', 'Senka Perfect Aqua White Mask Extra White được thiết kế từ chất liệu sợi vải không dệt 100% cotton ôm khít đường nét khuôn mặt, giúp dưỡng chất thẩm thấu tối đa vào da. Công thức chứa hoạt chất dưỡng trắng mờ thâm nám Tranexamic Acid kết hợp cùng tinh chất hoa hồng Rose Water và tơ tằm trắng giúp ức chế sự tích tụ sắc tố melanin, làm đều màu da và mang lại cảm giác dịu mát sảng khoái.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water (Aqua), Butylene Glycol, Dipropylene Glycol, Glycerin, Tranexamic Acid, PEG-6, PEG-32, PEG-8, PEG/PPG-14/7 Dimethyl Ether, Phenoxyethanol, Xanthan Gum, Isostearic Acid, Methylparaben, Hydrogenated Polydecene, PEG-60 Hydrogenated Castor Oil, Sodium Citrate, Disodium EDTA, Citric Acid, Sodium Metabisulfite, Sodium Hyaluronate, Sericin, Potassium Sorbate, Sodium Acetylated Hyaluronate, Rosa Roxburghii Fruit Extract.', 'Sau khi rửa mặt sạch và dùng toner, đắp mặt nạ đều lên khắp mặt. Thư giãn trong 15-20 phút, gỡ mặt nạ ra và vỗ nhẹ phần tinh chất còn lại trên da cho thẩm thấu hoàn toàn.', 'Nhật Bản', '25ml', 1, 4.92, 29, 79, 10, 0, 0, 'Tranexamic Acid, Rose Flower Extract, White Silk Essence, Double HA', NOW(), NOW()),
(150, 'Bông Tẩy Trang Tơ Tằm Tự Nhiên Senka Silky White Cotton Pads 80 miếng', 'bong-tay-trang-to-tam-tu-nhien-senka-silky-white-cotton-pads-80-mieng', 'Bông tẩy trang 100% cotton tự nhiên kết hợp sợi tơ tằm siêu mềm mại, không để lại xơ bông trên da.', 'Bông tẩy trang Senka Silky White Cotton Pads được dệt từ 100% sợi cotton thuần khiết tuyển chọn kết hợp công nghệ dập viền ép nhiệt hiện đại, đảm bảo miếng bông không bị biến dạng hay xơ xù rách khi tiếp xúc với dung dịch lỏng. Bề mặt bông mềm mịn như lụa lướt êm ái trên làn da nhạy cảm, tiết kiệm toner và nước tẩy trang gấp 2 lần.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', '100% Natural Cotton Fiber, Compressed Silk Thread Surface.', 'Thấm dung dịch nước tẩy trang hoặc nước hoa hồng lên miếng bông tẩy trang, nhẹ nhàng lau lên da theo chiều cấu trúc khuôn mặt từ dưới lên trên, từ trong ra ngoài.', 'Nhật Bản', '80 miếng', 1, 4.85, 30, 80, 10, 0, 0, '100% Pure Natural Cotton, Silk Fiber Edge-pressed', NOW(), NOW()),
(151, 'Dung Dịch Dưỡng Ẩm Chuyên Sâu Hada Labo Gokujyun Premium Hyaluronic Acid Lotion 170ml', 'dung-dich-duong-am-chuyen-sau-hada-labo-gokujyun-premium-hyaluronic-acid-lotion-170ml', 'Nước thần cấp ẩm chứa 7 loại phân tử Hyaluronic Acid đa tầng và chiết xuất tảo Sakuran ngậm nước gấp 5 lần.', 'Hada Labo Gokujyun Premium Lotion là tinh hoa công nghệ dưỡng ẩm của viện nghiên cứu Rohto Nhật Bản. Công thức chứa phức hợp 7 loại Hyaluronic Acid gồm HA, Super HA, Nano HA, 3D HA, Fermented HA, Penetrating HA và Adsorptive HA, kết hợp tinh chất tảo Sakuran quý hiếm tạo màng khóa ẩm sinh học, nuôi dưỡng làn da căng mọng, ngậm nước bóng khỏe từ bên trong suốt 24 giờ.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Water, Butylene Glycol, Glycerin, PPG-10 Methyl Glucose Ether, Hydroxyethyl Urea, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Lactococcus/Hyaluronic Acid Ferment Filtrate, Hydrolyzed Sodium Hyaluronate, Aphanothece Sacrum Exopolysaccharides (Sakuran), Hydrogenated Starch Hydrolysate, Glycosyl Trehalose, Diglycerin, Sorbitol, Triethyl Citrate, PEG-32, Carbomer, PEG-75, Disodium Succinate, Propanediol, Diethoxyethyl Succinate, Potassium Hydroxide, Succinic Acid, Disodium EDTA, Polyquaternium-51, Caprylhydroxamic Acid, Phenoxyethanol.', 'Sau khi rửa mặt sạch, đổ 4-5 giọt ra lòng bàn tay. Áp nhẹ hai lòng bàn tay vào nhau rồi vỗ đều khắp mặt trong 15-20 giây cho dung dịch thẩm thấu hoàn toàn.', 'Nhật Bản', '170ml', 1, 4.92, 31, 81, 11, 0, 0, '7 Types of Hyaluronic Acid, Sakuran Algae Extract, Urea', NOW(), NOW()),
(152, 'Bọt Rửa Mặt Dưỡng Ẩm Dịu Nhẹ Hada Labo Gokujyun Hyaluronic Acid Foaming Cleanser 160ml', 'bot-rua-mat-duong-am-diu-nhe-hada-labo-gokujyun-hyaluronic-acid-foaming-cleanser-160ml', 'Bọt rửa mặt tạo bọt sẵn với độ pH 5.5 cân bằng, chứa Super Hyaluronic Acid làm sạch không nhờn rít.', 'Hada Labo Gokujyun Foaming Cleanser là sữa rửa mặt tự tạo bọt tiện lợi với đầu bơm chuyên dụng biến dung dịch thành lớp bọt siêu mịn tơ tằm. Độ pH 5.5 lý tưởng tương thích hoàn hảo với màng lipid tự nhiên của da, kết hợp cùng Super Hyaluronic Acid và Nano Hyaluronic Acid giúp lấy đi bụi bẩn và bã nhờn mà vẫn duy trì độ ẩm mịn mềm mại sau khi rửa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Butylene Glycol, Disodium Cocoyl Glutamate, PEG-8, Cocamidopropyl Betaine, Cocamide DEA, PEG-80 Sorbitan Laurate, Glycerin, Sorbitol, Sodium Taurine Cocoyl Methyltaurate, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Petrolatum, Citric Acid, Polyquaternium-7, Disodium EDTA, BHT, Methylparaben.', 'Làm ướt mặt, nhấn 1-2 lần vòi bơm để lấy bọt ra tay. Massage nhẹ nhàng lên mặt theo chuyển động tròn trong khoảng 30-45 giây, sau đó rửa sạch lại với nước.', 'Nhật Bản', '160ml', 1, 4.85, 32, 82, 11, 0, 0, 'Super Hyaluronic Acid, Nano Hyaluronic Acid, pH 5.5 Balance', NOW(), NOW()),
(153, 'Dung Dịch Dưỡng Trắng Mờ Thâm Nám Hada Labo Shirojyun Premium Whitening Lotion 170ml', 'dung-dich-duong-trang-mo-tham-nam-hada-labo-shirojyun-premium-whitening-lotion-170ml', 'Nước hoa hồng dưỡng trắng chứa Tranexamic Acid, Vitamin C và Vitamin E làm mờ thâm mụn và đốm nâu.', 'Hada Labo Shirojyun Premium Whitening Lotion mang sức mạnh làm sáng da vượt trội nhờ hoạt chất Tranexamic Acid cao cấp có khả năng kháng viêm và chặn đứng tín hiệu kích hoạt sản sinh Melanin do tia UV gây ra. Bổ sung Vitamin C Phosphate và Vitamin E chống oxy hóa cùng Nano HA thẩm thấu sâu, sản phẩm làm mờ các vết thâm sau mụn và đem lại làn da sáng trong trẻo.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Active Ingredient: Tranexamic Acid. Inactive Ingredients: Water, Dipropylene Glycol, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Magnesium Ascorbyl Phosphate, Tocopherol, Coix Lacryma-Jobi Ma-yuen Seed Extract, Butylene Glycol, Diglycerin, Pentylene Glycol, PEG-8, PEG-30, Polysorbate 20, Disodium Succinate, Succinic Acid, Disodium EDTA, Phenoxyethanol.', 'Dùng 2 lần mỗi ngày sáng và tối. Đổ 4-5 giọt ra tay vỗ nhẹ khắp mặt cho thấm, có thể thấm ướt bông đắp lotion mask trong 3 phút để tăng cường hiệu quả làm sáng da.', 'Nhật Bản', '170ml', 1, 4.92, 33, 83, 11, 0, 0, 'Tranexamic Acid, Vitamin C Phosphate, Vitamin E, Nano HA', NOW(), NOW()),
(154, 'Kem Dưỡng Ẩm Toàn Diện Chuyên Sâu Hada Labo Advanced Nourish Supreme Cream 50g', 'kem-duong-am-toan-dien-chuyen-sau-hada-labo-advanced-nourish-supreme-cream-50g', 'Kem dưỡng ẩm cô đặc chứa 5 loại Hyaluronic Acid và bơ hạt mỡ khóa ẩm sâu suốt đêm cho da khô ráp.', 'Hada Labo Advanced Nourish Supreme Cream là giải pháp khóa ẩm tối ưu cho làn da mất nước nghiêm trọng. Kết cấu kem sánh mịn giàu dưỡng chất kết hợp 5 loại phân tử HA kích thước khác nhau len lỏi vào từng tế bào biểu bì, hòa quyện cùng bơ hạt mỡ hữu cơ Shea Butter củng cố lớp màng lipid, ngăn ngừa tình trạng mất nước qua da và cải thiện nếp nhăn do thiếu ẩm.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Water, Butylene Glycol, Glycerin, Butyrospermum Parkii (Shea) Butter, Caprylic/Capric Triglyceride, Hydroxyethyl Urea, Squalane, Triethylhexanoin, PPG-10 Methyl Glucose Ether, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Aphanothece Sacrum Exopolysaccharides, Dimethicone, Glyceryl Stearate, Behenyl Alcohol, Carbomer, Phenoxyethanol, Disodium EDTA.', 'Sau các bước toner và serum, lấy một lượng kem bằng hạt đậu chấm đều lên 5 điểm trên mặt rồi thoa đều, mát xa nhẹ nhàng cho kem thẩm thấu hoàn toàn.', 'Nhật Bản', '50g', 1, 4.85, 34, 84, 11, 0, 0, '5 Types of Hyaluronic Acid, Shea Butter, Hydroxyethyl Urea', NOW(), NOW()),
(155, 'Dầu Tẩy Trang Ô Liu Làm Sạch Sâu Hada Labo Gokujyun Cleansing Oil 200ml', 'dau-tay-trang-o-liu-lam-sach-sau-hada-labo-gokujyun-cleansing-oil-200ml', 'Dầu tẩy trang thuần khiết chiết xuất dầu quả ô liu Tây Ban Nha nhũ hóa nhanh, cuốn sạch mụn đầu đen.', 'Hada Labo Gokujyun Cleansing Oil chứa 100% tinh dầu quả ô liu tự nhiên nguyên chất tuyển chọn từ Tây Ban Nha kết hợp cùng 2 loại Hyaluronic Acid dưỡng ẩm. Dầu có độ sánh lý tưởng giúp hòa tan nhanh chóng lớp trang điểm dày, mascara kháng nước và bã nhờn sâu trong lỗ chân lông. Khả năng nhũ hóa siêu tốc chuyển hóa thành dạng sữa khi gặp nước, không để lại màng dầu nhờn dính.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Ethylhexyl Palmitate, Triethylhexanoin, Sorbeth-30 Tetraisostearate, PEG-20 Glyceryl Triisostearate, Olea Europaea (Olive) Fruit Oil, Water, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Simmondsia Chinensis (Jojoba) Seed Oil, Dextrin Palmitate/Ethylhexanoate, BHT.', 'Giữ mặt và tay khô ráo. Lấy 2-3 lần nhấn dầu thoa lên mặt và mát xa nhẹ nhàng trong 1-2 phút. Thêm một chút nước ấm vào tay để nhũ hóa dầu thành dạng sữa trắng, mát xa tiếp 30 giây rồi rửa sạch lại bằng nước ấm.', 'Nhật Bản', '200ml', 1, 4.92, 35, 85, 11, 0, 0, 'Pure Olive Oil, Super Hyaluronic Acid, Jojoba Seed Oil', NOW(), NOW()),
(156, 'Dầu Tẩy Trang Làm Dịu Lỗ Chân Lông Anua Heartleaf Pore Control Cleansing Oil 200ml', 'dau-tay-trang-lam-diu-lo-chan-long-anua-heartleaf-pore-control-cleansing-oil-200ml', 'Dầu tẩy trang thuần chay bán chạy số 1 Hàn Quốc chiết xuất lá diếp cá làm sạch mụn đầu đen không bít tắc.', 'Anua Heartleaf Pore Control Cleansing Oil là dòng dầu tẩy trang quốc dân Hàn Quốc đạt chứng nhận non-comedogenic an toàn cho da mụn. Chứa chiết xuất diếp cá Heartleaf kết hợp cùng dầu jojoba, dầu hạt hướng dương và dầu macadamia nhẹ nhàng đánh tan cặn trang điểm chống nước, bụi mịn và sợi bã nhờn tích tụ mà không gây cay mắt hay bít tắc sinh mụn ẩn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Ethylhexyl Palmitate, Sorbeth-30 Tetraoleate, Sorbitan Sesquioleate, Caprylic/Capric Triglyceride, Butyl Avocadate, Fragrance, Helianthus Annuus (Sunflower) Seed Oil, Macadamia Ternifolia Seed Oil, Olea Europaea (Olive) Fruit Oil, Simmondsia Chinensis (Jojoba) Seed Oil, Vitis Vinifera (Grape) Seed Oil, Caprylyl Glycol, Ethylhexylglycerin, Curcuma Longa (Turmeric) Root Extract, Melia Azadirachta Flower Extract, Tocopherol, Melia Azadirachta Leaf Extract, Houttuynia Cordata Extract, Corallina Officinalis Extract, Melia Azadirachta Bark Extract, Moringa Oleifera Seed Oil, Ocimum Sanctum Leaf Extract.', 'Bơm 2-3 giọt dầu ra tay khô, mát xa lên da mặt khô theo hình vòng tròn khoảng 1 phút. Nhũ hóa với một lượng nước ấm nhỏ cho đến khi chuyển sang màu trắng đục rồi rửa sạch lại với nước.', 'Hàn Quốc', '200ml', 1, 4.85, 36, 86, 12, 0, 0, '10,000ppm Heartleaf Extract, Jojoba Oil, Macadamia Seed Oil', NOW(), NOW()),
(157, 'Tinh Chất Diếp Cá Làm Dịu Da Mụn Anua Heartleaf 80% Moisture Soothing Ampoule 30ml', 'tinh-chat-diep-ca-lam-diu-da-mun-anua-heartleaf-80-moisture-soothing-ampoule-30ml', 'Ampoule đậm đặc chứa 80% chiết xuất diếp cá hữu cơ Hàn Quốc làm dịu cấp tốc nốt mụn viêm đỏ.', 'Anua Heartleaf 80% Moisture Soothing Ampoule là tinh chất cứu tinh cho làn da đang gặp khủng hoảng kích ứng hoặc bùng phát mụn. Với 80% hàm lượng chiết xuất diếp cá được nuôi trồng tại đỉnh núi Jirisan Hàn Quốc giàu Quercetin kháng viêm, kết hợp cùng Panthenol (B5), Betaine và Hyaluronic Acid, ampoule nhanh chóng xoa dịu các vết mẩn đỏ và cấp nước phục hồi da.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Houttuynia Cordata Extract (80%), Butylene Glycol, Glycerin, 1,2-Hexanediol, Betaine, Cassia Obtusifolia Seed Extract, Panthenol, Hydroxyethylcellulose, Sodium Hyaluronate, Arginine, Carbomer, Ethylhexylglycerin.', 'Sau toner, nhỏ 2-3 giọt ampoule lên mặt và thoa nhẹ nhàng. Vỗ đều bằng các đầu ngón tay để dưỡng chất thẩm thấu tối đa.', 'Hàn Quốc', '30ml', 1, 4.92, 37, 87, 12, 0, 0, '80% Houttuynia Cordata (Heartleaf) Extract, Panthenol, Betaine, Cassia Obtusifolia', NOW(), NOW()),
(158, 'Kem Dưỡng Diếp Cá Làm Dịu Kiềm Dầu Anua Heartleaf 70% Intense Calming Cream 50ml', 'kem-duong-diep-ca-lam-diu-kiem-dau-anua-heartleaf-70-intense-calming-cream-50ml', 'Kem dưỡng ẩm chứa 70% diếp cá và Ceramide NP củng cố hàng rào phòng thủ mà không gây bóng nhờn.', 'Anua Heartleaf 70% Intense Calming Cream được đặc chế nhằm phục hồi và nuôi dưỡng sâu cho làn da dầu mụn nhạy cảm. Công thức chứa 70% chiết xuất diếp cá Heartleaf kết hợp cùng Ceramide NP sinh học, Panthenol và Adenosine giúp khóa ẩm bền bỉ, làm dịu các vùng da tổn thương do mụn và tái thiết lập lớp màng bảo vệ tự nhiên mà hoàn toàn không gây bết rít bề mặt da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Houttuynia Cordata Extract (70%), Cetearyl Alcohol, Glycerin, Cyclohexasiloxane, Butylene Glycol, 1,2-Hexanediol, Dicaprylyl Ether, Caprylic/Capric Triglyceride, Hydrogenated Poly(C6-14 Olefin), Hydrogenated Polydecene, Glyceryl Stearate SE, Cetearyl Olivate, Sorbitan Olivate, Vegetable Oil, Panthenol, Hydrogenated Lecithin, Dipropylene Glycol, Behenyl Alcohol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Cetearyl Glucoside, Cholesterol, Xanthan Gum, Adenosine, Ceramide NP, Glucose, Water, Ethylhexylglycerin.', 'Lấy lượng kem vừa đủ thoa đều khắp mặt và cổ ở bước cuối cùng của chu trình dưỡng da ban đêm hoặc trước bước kem chống nắng vào ban ngày.', 'Hàn Quốc', '50ml', 1, 4.85, 38, 88, 12, 0, 0, '70% Heartleaf Extract, Ceramide NP, Panthenol, Adenosine', NOW(), NOW()),
(159, 'Miếng Bông Đắp Toner Diếp Cá Làm Dịu Da Anua Heartleaf 77% Clear Pad 70 miếng', 'mieng-bong-dap-toner-diep-ca-lam-diu-da-anua-heartleaf-77-clear-pad-70-mieng', 'Miếng bông 2 mặt tẩm sẵn toner diếp cá 77% và Anti-Sebum P kiềm dầu và thông thoáng chân lông.', 'Anua Heartleaf 77% Clear Pad là sản phẩm toner pad chăm sóc da mụn số 1 tại Olive Young. Mỗi miếng bông cotton dập nổi 2 mặt được ngâm đẫm trong dung dịch 77% chiết xuất diếp cá và phức hợp thảo mộc Anti-Sebum P (lá thông, hoa anh thảo, rễ cây du Nhật). Mặt dập nổi nhẹ nhàng lấy đi bã nhờn tế bào chết, mặt láng mịn dùng đắp lotion mask làm dịu các nốt mụn viêm sưng tức thì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Houttuynia Cordata Extract (77%), Water, Gluconolactone, Propanediol, Tromethamine, Butylene Glycol, 1,2-Hexanediol, Betaine, Ammonium Acryloyldimethyltaurate/VP Copolymer, Ulmus Davidiana Root Extract, Pueraria Lobata Root Extract, Pinus Palustris Leaf Extract, Oenothera Biennis (Evening Primrose) Flower Extract, Camellia Sinensis Leaf Extract, Ethylhexylglycerin.', 'Sau khi rửa mặt, dùng mặt dập nổi lau nhẹ khắp mặt theo chiều cấu trúc da. Sau đó đắp mặt mịn lên vùng da mụn hoặc kích ứng trong 5-10 phút để làm dịu da.', 'Hàn Quốc', '70 miếng', 1, 4.92, 39, 89, 12, 0, 0, '77% Heartleaf Extract, Anti-Sebum P Complex, PHA (Gluconolactone)', NOW(), NOW()),
(160, 'Sữa Rửa Mặt Tạo Bọt Chiết Xuất Diếp Cá Anua Heartleaf Quercetinol Pore Deep Cleansing Foam 150ml', 'sua-rua-mat-tao-bot-chiet-xuat-diep-ca-anua-heartleaf-quercetinol-pore-deep-cleansing-foam-150ml', 'Sữa rửa mặt bọt xốp mịn chứa bột diếp cá xay nhuyễn và Quercetinol làm sạch sâu mụn đầu đen.', 'Anua Heartleaf Quercetinol Pore Deep Cleansing Foam kết hợp bột lá diếp cá xay nhuyễn mịn với hoạt chất Quercetinol tinh chiết từ diếp cá tươi. Bọt sữa rửa mặt siêu dày giúp cuốn trôi bụi bẩn và 98.8% bã nhờn tận sâu bên trong lỗ chân lông mà không gây rát da. Bổ sung phức hợp 8 loại Hyaluronic Acid và Salicylic Acid nhẹ dịu, giữ bề mặt da luôn thông thoáng và mềm mại.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Houttuynia Cordata Extract (33.4%), Glycerin, Sodium Cocoyl Glycinate, Water, Sodium Lauroyl Glutamate, Coco-Glucoside, Sodium Cocoamphoacetate, Hectorite, 1,2-Hexanediol, Salicylic Acid, Houttuynia Cordata Powder, Potassium Benzoate, Sodium Chloride, Polyquaternium-67, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Gardenia Florida Fruit Extract, Dextrin, Phellodendron Amurense Bark Extract, Theobroma Cacao (Cocoa) Seed Extract, Quercetin, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid.', 'Lấy một lượng kem vừa đủ ra lòng bàn tay ướt, tạo bọt dày rồi mát xa nhẹ nhàng khắp mặt theo hình xoắn ốc trong 60 giây. Rửa sạch lại bằng nước ấm.', 'Hàn Quốc', '150ml', 1, 4.85, 40, 90, 12, 0, 0, 'Quercetinol, 3,000ppm Heartleaf Powder, 8 Types Hyaluronic Acid, Salicylic Acid', NOW(), NOW()),
(161, 'Gel Rửa Mặt Buổi Sáng Độ pH Thấp Dịu Nhẹ COSRX Low pH Good Morning Gel Cleanser 150ml', 'gel-rua-mat-buoi-sang-do-ph-thap-diu-nhe-cosrx-low-pH-good-morning-gel-cleanser-150ml', 'Gel rửa mặt pH 5.0 - 6.0 dịu nhẹ chứa tinh dầu tràm trà và 0.5% BHA tự nhiên thanh lọc da buổi sáng.', 'COSRX Low pH Good Morning Gel Cleanser là dòng sữa rửa mặt kinh điển toàn cầu của hãng COSRX. Công thức gel trong suốt với độ pH cân bằng 5.0 - 6.0 tương đương sinh lý làn da khỏe mạnh, kết hợp tinh dầu tràm trà (Tea Tree Leaf Oil) kháng khuẩn ngừa mụn và 0.5% Betaine Salicylate (BHA tự nhiên) làm sạch nhẹ nhàng dầu thừa tích tụ qua đêm mà không làm mất đi độ ẩm tự nhiên của da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Cocamidopropyl Betaine, Sodium Lauroyl Methyl Isethionate, Polysorbate 20, Styrax Japonica Branch/Fruit/Leaf Extract, Butylene Glycol, Saccharomyces Ferment, Cryptomeria Japonica Leaf Extract, Nelumbo Nucifera Leaf Extract, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Oenothera Biennis (Evening Primrose) Flower Extract, Pueraria Lobata Root Extract, Melaleuca Alternifolia (Tea Tree) Leaf Oil, Allantoin, Caprylyl Glycol, Ethylhexylglycerin, Betaine Salicylate, Citric Acid, Ethyl Hexanediol, 1,2-Hexanediol, Trisodium Ethylenediamine Disuccinate, Sodium Benzoate, Disodium EDTA.', 'Làm ướt mặt, lấy một lượng gel vừa đủ tạo bọt nhẹ nhàng trong lòng bàn tay rồi mát xa khắp khuôn mặt trong 1 phút, đặc biệt là vùng chữ T. Rửa sạch lại với nước mát.', 'Hàn Quốc', '150ml', 1, 4.92, 41, 91, 13, 0, 0, 'Tea Tree Leaf Oil, 0.5% Betaine Salicylate (BHA), Low pH Formula', NOW(), NOW()),
(162, 'Nước Cân Bằng Dịu Da Chiết Xuất Rau Má COSRX Centella Water Alcohol-Free Toner 150ml', 'nuoc-can-bang-diu-da-chiet-xuat-rau-ma-cosrx-centella-water-alcohol-free-toner-150ml', 'Nước hoa hồng dạng xịt không cồn chứa 82% nước khoáng đảo Jeju và 10% nước rau má Centella Asiatica.', 'COSRX Centella Water Alcohol-Free Toner là nước hoa hồng dạng xịt phun sương siêu tiện lợi dành riêng cho làn da dễ kích ứng và đang bị mụn viêm. Với 82% nước khoáng thiên nhiên đảo Jeju cùng 10% chiết xuất nước lá rau má Centella Asiatica giàu Madecassoside, toner làm dịu nhanh chóng cảm giác rát đỏ, hỗ trợ phục hồi tổn thương da và cân bằng độ pH tức thì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Water, Centella Asiatica Leaf Water, Butylene Glycol, 1,2-Hexanediol, Betaine, Panthenol, Allantoin, Ethyl Hexanediol, Sodium Hyaluronate.', 'Sau khi rửa mặt, xịt trực tiếp toner lên mặt cách khoảng 15-20cm hoặc xịt ra bông tẩy trang rồi lau nhẹ nhàng khắp mặt. Vỗ nhẹ cho dưỡng chất thẩm thấu sâu.', 'Hàn Quốc', '150ml', 1, 4.85, 42, 92, 13, 0, 0, '82% Jeju Mineral Water, 10% Centella Asiatica Leaf Water, Allantoin, Panthenol', NOW(), NOW()),
(163, 'Kem Dưỡng Mắt Peptide Dịch Nhầy Ốc Sên COSRX Advanced Snail Peptide Eye Cream 25ml', 'kem-duong-mat-peptide-dich-nhay-oc-sen-cosrx-advanced-snail-peptide-eye-cream-25ml', 'Kem mắt chứa 72% dịch lọc ốc sên và phức hợp 5 loại Peptide xóa mờ quầng thâm và nếp nhăn đuôi mắt.', 'COSRX Advanced Snail Peptide Eye Cream kết hợp sức mạnh phục hồi tái tạo của 72% dịch lọc ốc sên Snail Mucin nguyên chất cùng phức hợp 5 Peptide chống lão hóa và 2% Niacinamide dưỡng sáng. Kết cấu kem mỏng nhẹ thẩm thấu cực nhanh không gây vón cục, làm đầy rãnh nhăn mắt, cải thiện độ đàn hồi mí mắt và xóa tan quầng thâm mệt mỏi hiệu quả.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Snail Secretion Filtrate, Butylene Glycol, Glycerin, Helianthus Annuus (Sunflower) Seed Oil, 1,2-Hexanediol, Niacinamide, Water, Palmitic Acid, Arginine, Carbomer, Stearic Acid, Betaine, Cetearyl Olivate, Sorbitan Olivate, Sodium Polyacrylate, Allantoin, Tocopheryl Acetate, Panthenol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Sodium Hyaluronate, Adenosine, Copper Tripeptide-1, Acetyl Hexapeptide-8, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7.', 'Lấy một lượng kem nhỏ bằng hạt đậu thoa nhẹ nhàng quanh hốc mắt bằng ngón áp út, vỗ nhẹ theo chiều từ hốc mắt ra đuôi mắt vào mỗi buổi sáng và tối.', 'Hàn Quốc', '25ml', 1, 4.92, 43, 93, 13, 0, 0, '72% Snail Secretion Filtrate, 5 Peptide Complex, 2% Niacinamide', NOW(), NOW()),
(164, 'Tinh Chất Niacinamide 15% Thu Nhỏ Lỗ Chân Lông COSRX The Niacinamide 15 Serum 20ml', 'tinh-chat-niacinamide-15-thu-nho-lo-chan-long-cosrx-the-niacinamide-15-serum-20ml', 'Serum đặc trị chứa 15% Niacinamide tinh khiết, Zinc PCA và Allantoin kiểm soát dầu và se khít nang lông.', 'COSRX The Niacinamide 15 Serum thuộc dòng sản phẩm điều trị chuyên sâu The RX của COSRX. Nồng độ tối ưu 15% Niacinamide kết hợp cùng muối kẽm Zinc PCA 1% giúp điều tiết hoạt động của tuyến bã nhờn, làm thông thoáng lỗ chân lông bị bít tắc, cải thiện độ đàn hồi của nang lông và làm mờ các vết thâm sau mụn cứng đầu chỉ sau một chu kỳ tái tạo da.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Pentylene Glycol, Niacinamide (15%), Butylene Glycol, Acetyl Glucosamine, 1,2-Hexanediol, Zinc PCA, Trehalose, Hydrolyzed Sclerotium Gum, Pullulan, Allantoin, Ethylhexylglycerin, Sodium Phytate, Citric Acid, Tocopherol.', 'Sau khi làm sạch và dùng toner, nhỏ 2-3 giọt serum lên mặt và thoa đều. Sử dụng sáng và tối. Ban ngày luôn kết hợp với kem chống nắng có chỉ số bảo vệ cao.', 'Hàn Quốc', '20ml', 1, 4.85, 44, 94, 13, 0, 0, '15% Pure Niacinamide, 1% Zinc PCA, Trehalose, Allantoin', NOW(), NOW()),
(165, 'Miếng Dán Hút Mụn Kháng Viêm COSRX Acne Pimple Master Patch 24 miếng', 'mieng-dan-hut-mun-khang-viem-cosrx-acne-pimple-master-patch-24-mieng', 'Miếng dán mụn Hydrocolloid y tế giúp hút sạch mủ cồi mụn, ngăn sẹo thâm và bảo vệ nốt mụn khỏi vi khuẩn.', 'COSRX Acne Pimple Master Patch là miếng dán hút mụn nổi tiếng thế giới làm từ chất liệu y tế Hydrocolloid 100%. Miếng dán tạo môi trường ẩm vô trùng hút sạch toàn bộ dịch mủ và nhân cồi mụn mà không gây đau đớn, đồng thời ngăn ngừa thói quen sờ nặn mụn làm lây lan vi khuẩn, giúp vết thương mau lành và hạn chế tối đa nguy cơ để lại sẹo lõm hay vết thâm.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Cellulose Gum, Styrene Isoprene Styrene Block Copolymer, Polyisobutylene, Petroleum Resin, Polyurethane Film, Liquid Paraffin, Tetrakis Methane.', 'Rửa sạch vùng da mụn và để khô hoàn toàn. Chọn kích thước miếng dán phù hợp và dán trực tiếp lên nốt mụn. Thay miếng dán mới khi miếng cũ chuyển sang màu trắng đục do hút đầy dịch mủ.', 'Hàn Quốc', '24 miếng', 1, 4.92, 45, 95, 13, 0, 0, '100% Medical Grade Hydrocolloid Dressing', NOW(), NOW()),
(166, 'Nước Cân Bằng Giảm Mụn Phục Hồi Some By Mi AHA-BHA-PHA 30 Days Miracle Toner 150ml', 'nuoc-can-bang-giam-mun-phuc-hoi-some-by-mi-aha-bha-pha-30-days-miracle-toner-150ml', 'Nước hoa hồng chứa bộ 3 Acid (AHA-BHA-PHA) và 10.000ppm chiết xuất tràm trà làm sạch mụn trong 30 ngày.', 'Some By Mi AHA-BHA-PHA 30 Days Miracle Toner là giải pháp trị mụn toàn diện được yêu thích tại Châu Á. Sự phối hợp của AHA loại bỏ tế bào sừng bề mặt, BHA làm sạch sâu bã nhờn nang lông, và PHA cấp ẩm chống oxy hóa, kết hợp 10.000ppm tinh chất tràm trà tự nhiên Teatree và chiết xuất đu đủ, giúp gom cồi mụn, kháng viêm và tái tạo làn da sạch mụn mịn màng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Butylene Glycol, Dipropylene Glycol, Glycerin, Niacinamide, Melaleuca Alternifolia (Tea Tree) Leaf Water, Polyglyceryl-4 Caprate, Carica Papaya (Papaya) Fruit Extract, Lens Esculenta (Lentil) Seed Extract, Hamamelis Virginiana (Witch Hazel) Extract, Nelumbo Nucifera Flower Extract, Swiftlet Nest Extract, Sodium Hyaluronate, Fructan, Allantoin, Benzyl Glycol, Ethylhexylglycerin, Raspberry Ketone, Citric Acid (AHA), Salicylic Acid (BHA), Lactobionic Acid (PHA), Adenosine, Hydroxyethylcellulose, Mentha Piperita (Peppermint) Oil.', 'Sau khi rửa mặt sạch, thấm một lượng vừa đủ ra bông tẩy trang và lau nhẹ nhàng khắp mặt theo chiều cấu trúc da. Vỗ nhẹ cho dưỡng chất thấm sâu.', 'Hàn Quốc', '150ml', 1, 4.85, 46, 96, 14, 0, 0, '10,000ppm Teatree Water, AHA (Citric), BHA (Salicylic), PHA (Lactobionic), Niacinamide 2%', NOW(), NOW()),
(167, 'Kem Dưỡng Giảm Mụn Phục Hồi Hàng Rào Da Some By Mi AHA-BHA-PHA 30 Days Miracle Cream 60g', 'kem-duong-giam-mun-phuc-hoi-hang-rao-da-some-by-mi-aha-bha-pha-30-days-miracle-cream-60g', 'Kem dưỡng ẩm chứa 70.78% rau má Cica và 10.000ppm tràm trà làm dịu da và củng cố màng lipid.', 'Some By Mi AHA-BHA-PHA 30 Days Miracle Cream sở hữu công thức cô đặc với 70.78% chiết xuất rau má tươi Centella Asiatica cùng 4 hợp chất Cica tinh khiết (Madecassoside, Asiaticoside, Madecassic Acid, Asiatic Acid) và 10.000ppm tràm trà Teatree. Sản phẩm khóa ẩm sâu cho da dầu mụn mà không gây nhờn bóng, làm dịu các nốt mụn viêm sưng và bảo vệ da trước tác nhân bên ngoài.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Centella Asiatica (Gotu Kola) Extract (70.78%), Dipropylene Glycol, Glycerin, Water, Niacinamide, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Melaleuca Alternifolia (Tea Tree) Leaf Water (10,000ppm), Ricinus Communis (Castor) Seed Oil, Hydrogenated Castor Oil, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Coccinia Indica Fruit Extract, Solanum Melongena (Eggplant) Fruit Extract, Aloe Barbadensis Flower Extract, Ocimum Sanctum Leaf Extract, Curcuma Longa (Turmeric) Root Extract, Corallina Officinalis Extract, Calendula Officinalis (Pot Marigold) Flower Extract, Camellia Sinensis (Green Tea) Leaf Extract, Lavandula Angustifolia (Lavender) Extract, Rosmarinus Officinalis (Rosemary) Extract, Origanum Vulgare Flower/Leaf/Stem Extract, Thymus Vulgaris (Thyme) Extract, Fructan, Albizia Julibrissin Bark Extract, Salicylic Acid (BHA), Citric Acid (AHA), Lactobionic Acid (PHA), Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid.', 'Lấy một lượng kem vừa đủ thoa đều lên toàn bộ khuôn mặt, vỗ nhẹ bằng các đầu ngón tay để kem thẩm thấu hết vào da.', 'Hàn Quốc', '60g', 1, 4.92, 47, 97, 14, 0, 0, '70.78% Centella Asiatica, 10,000ppm Tea Tree, 4-Cica Care, AHA/BHA/PHA', NOW(), NOW()),
(168, 'Tinh Chất Phục Hồi Tái Tạo Ốc Sên Đen Some By Mi Snail Truecica Miracle Repair Serum 50ml', 'tinh-chat-phuc-hoi-tai-tao-oc-sen-den-some-by-mi-snail-truecica-miracle-repair-serum-50ml', 'Serum chứa 890.000ppm dịch nhầy ốc sên đen và hợp chất Truecica lấp đầy sẹo lõm và phục hồi da tổn thương.', 'Some By Mi Snail Truecica Miracle Repair Serum là tinh chất tái sinh làn da chuyên sâu dành cho da sau mụn nhiều vết thâm và sẹo rỗ. Chứa 88% dịch nhầy ốc sên đen Black Snail giàu Elastin và Collagen tự nhiên kết hợp cùng 10.000ppm hợp chất độc quyền Truecica (rau má, ngải cứu, tràm trà), serum thúc đẩy tái tạo tế bào biểu bì, làm đầy các vết sẹo rỗ nông và củng cố hàng rào phòng ngự của da.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Snail Secretion Filtrate (759,000ppm), Butylene Glycol, Water, Niacinamide, 1,2-Hexanediol, Glycerin, Centella Asiatica Extract (10,000ppm), Melaleuca Alternifolia (Tea Tree) Leaf Water, Artemisia Princeps Leaf Extract, Asiaticoside, Madecassic Acid, Asiatic Acid, Madecassoside, Allantoin, Glycolic Acid, Panthenol, Carbomer, Arginine, Adenosine, Ethylhexylglycerin, Citrus Aurantium Bergamia (Bergamot) Fruit Oil.', 'Sau bước toner, lấy 3-4 giọt serum chấm đều lên các vùng trán, má, cằm và thoa đều. Vỗ nhẹ cho dưỡng chất thẩm thấu sâu trước khi thoa kem dưỡng.', 'Hàn Quốc', '50ml', 1, 4.85, 48, 98, 14, 0, 0, '890,000ppm Black Snail Secretion, 10,000ppm Truecica, Niacinamide, Allantoin', NOW(), NOW()),
(169, 'Kem Dưỡng Mắt Retinol Trẻ Hóa Giảm Quầng Thâm Some By Mi Retinol Intense Advanced Eye Cream 30ml', 'kem-duong-mat-retinol-tre-hoa-giam-quang-tham-some-by-mi-retinol-intense-advanced-eye-cream-30ml', 'Kem mắt chứa 0.1% Retinol, Retinal và Niacinamide cải thiện 8 loại nếp nhăn và quầng thâm mắt.', 'Some By Mi Retinol Intense Advanced Triple Action Eye Cream ứng dụng công nghệ vi nhũ tương Micro-Liposome bọc Retinol nguyên chất 0.1% cùng Retinal và Bakuchiol thực vật, giúp đưa hoạt chất trẻ hóa thẩm thấu sâu vào tế bào da mà không gây bong tróc đỏ rát. Sản phẩm cải thiện rõ rệt 8 loại nếp nhăn vùng mắt, rãnh cười, vết chân chim và làm sáng quầng thâm mắt sau 4 tuần.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Glycerin, Sodium Hyaluronate, Butylene Glycol, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Niacinamide, Cetyl Alcohol, Retinol (0.1%), Retinal, Bakuchiol, Glyceryl Stearate, Macadamia Ternifolia Seed Oil, PEG-100 Stearate, Cetearyl Olivate, Sorbitan Olivate, Polysorbate 60, Polyacrylate-13, Polyisobutene, Polysorbate 20, Panthenol, Adenosine, Ethylhexylglycerin, Disodium EDTA, Soluble Collagen.', 'Dùng vào buổi tối. Lấy lượng kem nhỏ bằng hạt đậu thoa nhẹ nhàng quanh hốc mắt, đuôi mắt và khóe miệng. Thoa kem chống nắng kỹ vào ban ngày.', 'Hàn Quốc', '30ml', 1, 4.92, 49, 99, 14, 0, 0, '0.1% Retinol, Retinal, Bakuchiol, Niacinamide, Collagen', NOW(), NOW()),
(170, 'Mặt Nạ Giấy Dịu Da Kháng Viêm Tràm Trà Some By Mi Real Teatree Calming Care Mask 20g', 'mat-na-giay-diu-da-khang-viem-tram-tra-some-by-mi-real-teatree-calming-care-mask-20g', 'Mặt nạ giấy thuần chay 100% cellulose thực vật ngậm đẫm tinh chất tràm trà Teatree làm dịu mụn tức thì.', 'Some By Mi Real Teatree Calming Care Mask là mặt nạ giấy thuần chay làm từ 100% sợi cellulose nguồn gốc thực vật ôm khít từng đường nét khuôn mặt. Tinh chất tràm trà tự nhiên nguyên chất phối hợp cùng chiết xuất rau má làm giảm sưng tấy mụn đỏ, hạ nhiệt làn da bỏng rát và bổ sung độ ẩm thanh khiết cho da dầu mụn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Glycerin, Propanediol, Melaleuca Alternifolia (Tea Tree) Leaf Extract (10,000ppm), Dipropylene Glycol, Hydroxyacetophenone, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Allantoin, Xanthan Gum, Tromethamine, Butylene Glycol, 1,2-Hexanediol, Ethylhexylglycerin, Disodium EDTA, Centella Asiatica Extract, Melaleuca Alternifolia (Tea Tree) Leaf Oil.', 'Rửa mặt sạch và thoa toner. Đắp mặt nạ trải đều khắp mặt trong 15-20 phút. Tháo mặt nạ ra và vỗ nhẹ tinh chất còn đọng trên da cho hấp thụ hết.', 'Hàn Quốc', '20g', 1, 4.85, 50, 100, 14, 0, 0, 'Teatree Leaf Extract, Allantoin, Betaine, Centella Asiatica Extract', NOW(), NOW()),
(171, 'Mặt Nạ Ngủ Cấp Ẩm Thanh Lọc Da Đêm Laneige Water Sleeping Mask EX 70ml', 'mat-na-ngu-cap-am-thanh-loc-da-dem-laneige-water-sleeping-mask-ex-70ml', 'Mặt nạ ngủ thế hệ mới công nghệ Sleeping Micro-Biome và phức hợp Probiotics nuôi dưỡng làn da tươi mới.', 'Laneige Water Sleeping Mask EX là biểu tượng mặt nạ ngủ toàn cầu với công nghệ Sleeping Micro-Biome cân bằng hệ vi sinh vật trên da suốt giấc ngủ ban đêm. Chứa phức hợp 23.8 tỷ lợi khuẩn Probiotics lên men từ trà xanh đảo Jeju cùng Squalane cấp ẩm sâu, sản phẩm giúp làn da phục hồi độ căng bóng, tươi sáng và rạng rỡ ngay khi thức dậy vào sáng hôm sau.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Butylene Glycol, Glycerin, Trehalose, Methyl Trimethicone, 1,2-Hexanediol, Squalane, Phenyl Trimethicone, PCA Dimethicone, Caprylyl Methicone, Ammonium Acryloyldimethyltaurate/VP Copolymer, Lactobacillus Ferment Lysate, Carbomer, Propanediol, Tromethamine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Glyceryl Caprylate, Ethylhexylglycerin, Disodium EDTA, Raffinose, Stearyl Behenate, Malachite Extract, Fragrance/Parfum, Polyglyceryl-3 Methylglucose Distearate, Inulin Lauryl Carbamate, Tranexamic Acid, Tryptophan, Hydroxypropyl Bispalmitamide MEA, Beta-Glucan, Limonene, Acorus Gramineus Extract, Linalool, Tocopherol.', 'Sử dụng vào buổi tối, 2-3 lần mỗi tuần ở bước cuối cùng sau kem dưỡng. Lấy lượng kem cỡ đồng xu thoa đều lên mũi, má, trán và cằm, để nguyên qua đêm và rửa sạch lại vào sáng hôm sau.', 'Hàn Quốc', '70ml', 1, 4.92, 51, 101, 15, 1, 0, 'Sleeping Micro-Biome, Probiotics Complex, Squalane, Beta-Glucan', NOW(), NOW()),
(172, 'Tinh Chất Cấp Ẩm Phục Hồi Laneige Water Bank Blue Hyaluronic Serum 50ml', 'tinh-chat-cap-am-phuc-hoi-laneige-water-bank-blue-hyaluronic-serum-50ml', 'Serum chứa Blue Hyaluronic Acid siêu vi phân tử nhỏ gấp 2000 lần thẩm thấu sâu và phục hồi da 300%.', 'Laneige Water Bank Blue Hyaluronic Serum chứa phân tử Blue HA độc quyền trải qua 10 giai đoạn tinh chế kết hợp chiết xuất tảo biển nâu Fucoidan, thu nhỏ kích thước phân tử chỉ bằng 1/2000 so với HA thông thường. Serum thẩm thấu vào tầng da thứ 10, tăng khả năng tự phục hồi hàng rào ẩm lên đến 300% và cải thiện độ săn chắc làn da tức thì.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Butylene Glycol, Dipropylene Glycol, Glycerin, Squalane, 1,2-Hexanediol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Propanediol, Carbomer, Cetearyl Alcohol, Tromethamine, Polyglyceryl-3 Methylglucose Distearate, Dextrin, Hydrogenated Lecithin, Ethylhexylglycerin, Fragrance/Parfum, Glyceryl Stearate Citrate, Disodium EDTA, Betaine, Hydrolyzed Hyaluronic Acid (Blue HA), Beta-Glucan, Xylitylglucoside, Anhydroxylitol, Xylitol, Lactobacillus Ferment Lysate, Glucose, Tocopherol.', 'Xoay thân chai theo chiều kim đồng hồ để vòi bơm tự động đẩy lên. Nhấn lấy 2 lần bơm tinh chất thoa đều lên má và trán, vỗ nhẹ cho dưỡng chất thẩm thấu.', 'Hàn Quốc', '50ml', 1, 4.85, 52, 102, 15, 1, 0, 'Blue Hyaluronic Acid (1/2000 size), Peptide, Fucoidan Algae', NOW(), NOW()),
(173, 'Dưỡng Môi Ban Ngày Căng Mọng Laneige Lip Treatment Balm 10g', 'duong-moi-ban-ngay-cang-mong-laneige-lip-treatment-balm-10g', 'Son dưỡng môi dạng hũ hương Pina Colada bổ sung Peptide và dầu dừa cho bờ môi căng mọng đàn hồi.', 'Laneige Lip Treatment Balm là son dưỡng môi chuyên biệt ban ngày với thiết kế nắp gài thìa thoa thông minh. Chứa phức hợp Peptide kích thích tăng sinh collagen giúp môi đầy đặn căng mọng, tinh dầu dừa nuôi dưỡng bờ môi khô nứt và bột ngọc trai phản chiếu ánh sáng lấp lánh tự nhiên, đem lại đôi môi căng tràn sức sống hương dừa dứa nhiệt đới.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Diisostearyl Malate, Hydrogenated Polyisobutene, Phytosteryl/Isostearyl/Cetyl/Stearyl/Behenyl Dimer Dilinoleate, Polybutene, Hydrogenated Poly(C6-14 Olefin), Butyrospermum Parkii (Shea) Butter, Microcrystalline Wax/Cera Microcristallina, Synthetic Wax, Ethylene/Propylene/Styrene Copolymer, Sucrose Tetrastearate Triacetate, Mica, Titanium Dioxide (CI 77891), Euphorbia Cerifera (Candelilla) Wax, Candelilla Cera Hydrocarbons, Butylene/Ethylene/Styrene Copolymer, Fragrance/Parfum, Astrocaryum Murumuru Seed Butter, Cocos Nucifera (Coconut) Oil, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Dimethicone, Dehydroacetic Acid, Adenosine, BHT, Palmitoyl Tripeptide-1.', 'Mở nắp và lấy que thoa gắn sẵn trên nắp, lấy một lượng dưỡng môi vừa đủ thoa đều lên môi. Có thể thoa lại bất cứ lúc nào trong ngày.', 'Hàn Quốc', '10g', 1, 4.92, 53, 103, 15, 1, 0, 'Lip-plumping Peptides, Coconut Oil, Adenosine, Pearlescent Pigments', NOW(), NOW()),
(174, 'Phấn Nước Kiềm Dầu Mịn Lì Chống Trôi Laneige Neo Cushion Matte SPF46 PA++ 15g', 'phan-nuoc-kiem-dau-min-li-chong-troi-laneige-neo-cushion-matte-spf46-pa-plus-plus-15g', 'Cushion thiết kế bo tròn không dính khẩu trang, che phủ khuyết điểm hoàn hảo và kiềm dầu 24H.', 'Laneige Neo Cushion Matte sở hữu thiết kế hình hộp bo tròn hiện đại và công nghệ hạt phấn siêu vi điểm Ultralight Powder tạo nên lớp nền mỏng nhẹ tệp da tuyệt đối. Khả năng chống dính khẩu trang lên đến 99.9%, kiềm dầu và giữ tông màu sáng mịn suốt 24 giờ mà không bị xuống tông xỉn màu dưới thời tiết nắng nóng ẩm nhiệt đới.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Water/Aqua/Eau, Titanium Dioxide (CI 77891), Cyclopentasiloxane, Methyl Trimethicone, Ethylhexyl Methoxycinnamate, Caprylyl Methicone, PEG-10 Dimethicone, Polymethyl Methacrylate, Cyclohexasiloxane, Zinc Oxide (CI 77947), Silica, Titanium Dioxide, Nylon-12, Lauryl PEG-9 Polydimethylsiloxyethyl Dimethicone, Iron Oxides (CI 77492), Disteardimonium Hectorite, 1,2-Hexanediol, Aluminum Hydroxide, Sodium Chloride, Triethoxycaprylylsilane, Isopropyl Titanium Triisostearate, Iron Oxides (CI 77491), Caprylyl Glycol, Bis-PEG-15 Dimethicone/IPDI Copolymer, Fragrance/Parfum, PEG-2 Soyamine, Ethylhexylglycerin, Disodium EDTA, Iron Oxides (CI 77499), Adenosine, Panthenol, Tocopherol.', 'Dùng bông phấn ấn nhẹ vào lõi đệm để lấy lượng phấn vừa đủ. Dặm nhẹ nhàng và đều tay khắp mặt theo chiều cấu trúc da, dặm thêm một lớp ở những vùng cần che khuyết điểm.', 'Hàn Quốc', '15g', 1, 4.85, 54, 104, 15, 1, 0, 'Ultralight Powder, Blue Light Shield, SPF 46 PA++, Panthenol', NOW(), NOW()),
(175, 'Bộ Bông Phấn Nước Cushion Thay Thế Cao Cấp Laneige Neo Cushion Edge Puff Set 2 miếng', 'bo-bong-phan-nuoc-cushion-thay-the-cao-cap-laneige-neo-cushion-edge-puff-set-2-mieng', 'Bông phấn cushion thiết kế viền khía rãnh thoát khí thông minh giúp lớp nền bám chặt siêu mỏng mịn.', 'Laneige Neo Cushion Edge Puff Set gồm 2 bông phấn chuyên dụng thiết kế bề mặt với hàng trăm khe rãnh nhỏ li ti độc quyền giúp kiểm soát lượng phấn nước cushion, giải phóng và dàn trải đều lớp nền lên bề mặt da một cách tinh tế. Chất liệu mút Rubycell kháng khuẩn cao cấp đàn hồi êm ái, cho hiệu ứng nền mịn lì che phủ cao mà không bị mốc phấn.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Antibacterial Rubycell Polyurethane Foam, Satin Ribbon, Polyester.', 'Dùng bông phấn dặm nhẹ vào lõi phấn nước Neo Cushion và vỗ nhẹ đều khắp mặt. Các đường rãnh trên bông giúp phấn tệp chặt vào da.', 'Hàn Quốc', '2 miếng', 1, 4.92, 20, 105, 15, 0, 0, 'Antibacterial Rubycell Polyurethane, Slit Pocket Design', NOW(), NOW()),
(176, 'Tinh Chất Trà Xanh Cấp Ẩm Phục Hồi Innisfree Green Tea Seed Hyaluronic Serum 80ml', 'tinh-chat-tra-xanh-cap-am-phuc-hoi-innisfree-green-tea-seed-hyaluronic-serum-80ml', 'Serum trà xanh đảo Jeju cải tiến kết hợp Nano Hyaluronic Acid cấp ẩm sâu và làm dịu da tức thì.', 'Innisfree Green Tea Seed Hyaluronic Serum phiên bản cải tiến đột phá chứa chiết xuất trà xanh hữu cơ Beauty Green Tea độc quyền từ nông trường đảo Jeju giàu 16 loại Amino Acid thiết yếu. Kết hợp công nghệ Nano Hyaluronic Acid phân tử siêu nhỏ tăng tốc độ thẩm thấu gấp 5.7 lần, củng cố hàng rào bảo vệ da và giải quyết triệt để tình trạng da khô căng rát sau bước rửa mặt.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Propanediol, Glycerin, 1,2-Hexanediol, Niacinamide, Betaine, Saccharide Isomerate, Camellia Sinensis Seed Oil (2,600ppm), Xylitol, Cetearyl Olivate, Hydrogenated Lecithin, Sorbitan Olivate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Lactobacillus Ferment Lysate, Butylene Glycol, Squalane, Panthenol, Allantoin, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Tromethamine, Triethyl Citrate, Ethylhexylglycerin, Ceramide NP, Disodium EDTA, Sodium Hyaluronate, Camellia Sinensis Leaf Extract (170ppm), Dextrin, Theobroma Cacao (Cocoa) Extract, Hydrolyzed Hyaluronic Acid, Sodium Citrate, Citric Acid, Sorbitan Isostearate, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Sodium Acetylated Hyaluronate.', 'Bơm 2-3 lần nhấn serum ra tay thoa đều lên mặt ngay sau bước làm sạch khi da còn hơi ẩm, mát xa nhẹ nhàng cho dưỡng chất thấm sâu.', 'Hàn Quốc', '80ml', 1, 4.85, 21, 106, 16, 0, 0, 'Beauty Green Tea Extract, Nano Hyaluronic Acid, Ceramide, Panthenol', NOW(), NOW()),
(177, 'Chì Kẻ Mày Hai Đầu Định Hình Sợi Tự Nhiên Innisfree Auto Eyebrow Pencil 0.3g', 'chi-ke-may-hai-dau-dinh-hinh-soi-tu-nhien-innisfree-auto-eyebrow-pencil-0-3g', 'Chì kẻ mày dạng vặn 2 đầu đầu dẹp hình oval kèm đầu chải xoắn định hình chân mày tự nhiên lâu trôi.', 'Innisfree Auto Eyebrow Pencil là sản phẩm kẻ mày biểu tượng được hàng triệu tín đồ làm đẹp tin dùng mỗi ngày. Thiết kế đầu chì hình oval vát phẳng thông minh giúp dễ dàng kẻ từng sợi lông mày mảnh mai cũng như tạo khối bản dày tự nhiên cho khuôn mày, kết hợp sáp đậu nành và sắc tố khoáng tự nhiên bám màu bền bỉ, không lem trôi khi đổ mồ hôi.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrogenated Soybean Oil, Hydrogenated Coco-Glycerides, Hydrogenated Vegetable Oil, Zinc Stearate, Stearic Acid, Copernicia Cerifera (Carnauba) Wax, Polyglyceryl-2 Triisostearate, Tocopherol, Caprylyl Glycol, Phenoxyethanol. [+/- Iron Oxides (CI 77499, CI 77491, CI 77492), Mica].', 'Dùng đầu chì dẹp vẽ định hình dáng mày từ đầu đến đuôi mày. Sau đó dùng đầu cọ chải xoắn tán đều theo hướng lông mày mọc để màu sắc hài hòa tự nhiên.', 'Hàn Quốc', '0.3g', 1, 4.92, 22, 107, 16, 0, 0, 'Hydrogenated Soybean Oil, Natural Mineral Pigments, Vitamin E', NOW(), NOW()),
(178, 'Bông Tẩy Trang Cotton Tự Nhiên Cao Cấp Innisfree Premium Cotton Pads 80 miếng', 'bong-tay-trang-cotton-tu-nhien-cao-cap-innisfree-premium-cotton-pads-80-mieng', 'Bông tẩy trang 100% cotton hữu cơ không tẩy trắng bằng Clo, dập viền ép chắc chắn không xơ dính.', 'Bông tẩy trang Innisfree Premium Cotton Pads được làm từ 100% sợi bông cotton hữu cơ tự nhiên không qua xử lý tẩy trắng hóa học bằng Clo, an toàn tuyệt đối cho làn da nhạy cảm. Miếng bông cấu trúc 3 lớp với viền dập ép nhiệt chắc chắn, không bị rách, xơ xù hay để lại sợi bông dính trên da mặt khi tẩy trang hoặc thoa nước hoa hồng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', '100% Organic Cotton Fiber, Thermal Bonded Edges.', 'Thấm nước tẩy trang hoặc nước hoa hồng lên miếng bông tẩy trang, nhẹ nhàng lau khắp khuôn mặt theo hướng từ trong ra ngoài và từ dưới lên trên.', 'Hàn Quốc', '80 miếng', 1, 4.85, 23, 108, 16, 0, 0, '100% Organic Unbleached Cotton Fiber', NOW(), NOW()),
(179, 'Cọ Tán Kem Nền Cao Cấp Innisfree Beauty Tool Master Foundation Brush', 'co-tan-kem-nen-cao-cap-innisfree-beauty-tool-master-foundation-brush', 'Cọ trang điểm lông nhân tạo cao cấp cắt vát xéo giúp tán kem nền mịn màng, không để lại vệt cọ.', 'Cọ đánh nền Innisfree Master Foundation Brush được thiết kế với đầu lông cọ sợi tổng hợp cao cấp mềm mịn, mật độ lông dày đặc và được vát xéo ôm khít các góc cạnh của khuôn mặt (cánh mũi, khóe mắt). Cọ giúp tán đều kem nền, BB cream hoặc cushion một cách mỏng nhẹ tự nhiên, che phủ khuyết điểm tối đa mà không gây hao kem nền.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'High-grade Synthetic Hair (PBT), Aluminum Ferrule, Natural Wood Handle.', 'Lấy kem nền chấm lên mặt hoặc đầu cọ, dùng cọ quét nhẹ nhàng theo chiều cấu trúc da từ giữa mặt ra ngoài để tạo lớp nền mịn màng hoàn hảo.', 'Hàn Quốc', '1 cây', 1, 4.92, 24, 109, 16, 0, 0, 'Premium Synthetic Bristles, Ergonomic Wooden Handle', NOW(), NOW()),
(180, 'Kem Dưỡng Da Tay Hương Nước Hoa Đảo Jeju Innisfree Jeju Life Perfumed Hand Cream 30ml', 'kem-duong-da-tay-huong-nuoc-hoa-dao-jeju-innisfree-jeju-life-perfumed-hand-cream-30ml', 'Kem dưỡng tay chứa bơ hạt mỡ và hương thơm hoa trà Jeju lưu hương thơm ngát suốt nhiều giờ.', 'Innisfree Jeju Life Perfumed Hand Cream mang trọn hương thơm thanh khiết của hòn đảo ngọc Jeju vào bàn tay bạn. Chứa bơ hạt mỡ hữu cơ Shea Butter, chiết xuất rau má Centella và dầu olive tự nhiên, kem dưỡng ẩm sâu cho đôi bàn tay khô ráp, làm mềm mịn các khớp ngón tay và móng tay mà không gây cảm giác bết dính nhờn rít khó chịu.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Glycerin, Propanediol, Cetearyl Alcohol, Hydrogenated Coco-Glycerides, Glyceryl Stearate, Butylene Glycol Dicaprylate/Dicaprate, 1,2-Hexanediol, Cetearyl Glucoside, Stearic Acid, Palmitic Acid, Fragrance/Parfum, Caprylic/Capric Triglyceride, Carbomer, Tromethamine, Disodium EDTA, Ethylhexylglycerin, Sodium Stearoyl Glutamate, Butyrospermum Parkii (Shea) Butter, Olea Europaea (Olive) Fruit Oil, Camellia Japonica Flower Extract, Centella Asiatica Extract.', 'Sau khi rửa tay sạch và lau khô, lấy một lượng kem vừa đủ thoa đều khắp mu bàn tay, lòng bàn tay và các kẽ ngón tay. Mát xa nhẹ nhàng cho kem thẩm thấu.', 'Hàn Quốc', '30ml', 1, 4.85, 25, 110, 16, 1, 0, 'Shea Butter, Camellia Flower Extract, Olive Oil, Centella Asiatica', NOW(), NOW()),
(181, 'Mặt Nạ Tẩy Tế Bào Chết Đường Đen Skinfood Black Sugar Mask Wash Off 100g', 'mat-na-tay-te-bao-chet-duong-den-skinfood-black-sugar-mask-wash-off-100g', 'Mặt nạ tẩy da chết cơ học chứa hạt đường đen hữu cơ Brazil giàu khoáng chất tẩy sạch tế bào chết.', 'Skinfood Black Sugar Mask Wash Off là dòng mặt nạ tẩy da chết huyền thoại làm nên tên tuổi thương hiệu Skinfood. Chứa các hạt đường đen hữu cơ tự nhiên từ Brazil giàu khoáng chất (phốt pho, canxi, sắt, vitamin), mặt nạ nhẹ nhàng lấy đi các lớp tế bào chết sần sùi bít tắc lỗ chân lông, nuôi dưỡng làn da mềm mịn như lụa và sáng bóng khỏe mạnh sau mỗi lần sử dụng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Sucrose, PEG-7 Glyceryl Cocoate, Glycerin, Euphorbia Cerifera (Candelilla) Wax, Macadamia Ternifolia Seed Oil, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Lanolin, Stearalkonium Hectorite, Butyrospermum Parkii (Shea) Butter, Limnanthes Alba (Meadowfoam) Seed Oil, Caramel, Sorbitan Laurate, Tocopheryl Acetate, Ethylhexylglycerin, Water, Fragrance.', 'Sau khi rửa mặt, khi da còn ẩm, lấy một lượng vừa đủ thoa đều khắp mặt (tránh mắt và môi). Mát xa nhẹ nhàng theo hình tròn trong 1-2 phút rồi để yên 10-15 phút, sau đó rửa sạch với nước ấm.', 'Hàn Quốc', '100g', 1, 4.92, 26, 111, 17, 1, 0, 'Organic Black Sugar Granules, Macadamia Seed Oil, Shea Butter', NOW(), NOW()),
(182, 'Mặt Nạ Rửa Chiết Xuất Cám Gạo Sáng Da Mờ Thâm Skinfood Rice Mask Wash Off 100g', 'mat-na-rua-chiet-xuat-cam-gao-sang-da-mo-tham-skinfood-rice-mask-wash-off-100g', 'Mặt nạ rửa dạng kem chứa nước cám gạo Odae Hàn Quốc làm sáng da, mờ thâm và cấp ẩm mềm mịn.', 'Skinfood Rice Mask Wash Off chứa nước chiết xuất từ cám gạo thượng hạng Odae vùng Cheorwon Hàn Quốc, giàu Vitamin E, Gamma-Oryzanol và các chất chống oxy hóa tự nhiên. Kết cấu dạng kem trắng mịn màng với những hạt cám gạo li ti giúp nhẹ nhàng thanh lọc tế bào chết xỉn màu, bổ sung dưỡng chất nuôi dưỡng làn da trắng sáng hồng hào và căng mịn tự nhiên.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Cetyl Ethylhexanoate, Caprylic/Capric Triglyceride, Cyclopentasiloxane, Cetyl Alcohol, Propylene Glycol, Glycerin, Polysorbate 80, Jojoba Esters, PEG-100 Stearate, Glyceryl Stearate, Palmitic Acid, Hydrogenated Jojoba Oil, Stearic Acid, Sorbitan Stearate, Dimethicone, Carbomer, Potassium Hydroxide, Oryza Sativa (Rice) Bran Water (1,000ppm), Fragrance, Sucrose Cocoate, Tocopheryl Acetate, Disodium EDTA, Phenoxyethanol.', 'Sau khi làm sạch mặt, thoa đều mặt nạ lên khắp mặt, nhẹ nhàng mát xa trong 1 phút rồi thư giãn trong 10-15 phút. Rửa sạch lại với nước ấm.', 'Hàn Quốc', '100g', 1, 4.85, 27, 112, 17, 1, 0, 'Odae Rice Bran Water, Gamma-Oryzanol, Vitamin E', NOW(), NOW()),
(183, 'Miếng Bông Đắp Cà Rốt Cấp Nước Làm Dịu Da Skinfood Carrot Carotene Calming Water Pad 60 miếng', 'mieng-bong-dap-ca-rot-cap-nuoc-lam-diu-da-skinfood-carrot-carotene-calming-water-pad-60-mieng', 'Toner pad thuần chay độ dày gấp đôi ngâm tinh chất dầu hạt cà rốt giàu Beta-Carotene hạ nhiệt da đỏ rát.', 'Skinfood Carrot Carotene Calming Water Pad là sản phẩm toner pad đạt nhiều giải thưởng danh giá tại Hàn Quốc. Sử dụng dầu hạt cà rốt tự nhiên ép lạnh từ vùng đất hữu cơ Jeju giàu dưỡng chất Beta-Carotene giúp bảo vệ màng tế bào da và giảm sưng đỏ. Miếng bông cotton dệt bánh waffle siêu dày xốp giữ lượng tinh chất dồi dào, đem lại cảm giác ẩm mát xoa dịu làn da kích ứng tức thì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Water, Daucus Carota Sativa (Carrot) Root Extract, Glycerin, Beta-Glucan, Butylene Glycol, 1,2-Hexanediol, C12-14 Pareth-12, Ethylhexylglycerin, Carbomer, Tromethamine, Allantoin, Sodium Hyaluronate, Daucus Carota Sativa (Carrot) Seed Oil, Olea Europaea (Olive) Fruit Oil, Pogostemon Cablin Oil, Lavandula Hybrida Oil, Salvia Officinalis (Sage) Oil, Artemisia Vulgaris Oil, Citrus Aurantium Dulcis (Orange) Peel Oil.', 'Sau khi rửa mặt, tách đôi miếng bông cotton dày rồi đắp lên vùng hai má hoặc trán trong 5-10 phút. Gỡ miếng bông ra và lau nhẹ khắp mặt, vỗ nhẹ cho tinh chất thẩm thấu.', 'Hàn Quốc', '60 miếng', 1, 4.92, 28, 113, 17, 0, 0, 'Beta-Carotene (Carrot Seed Oil), Allantoin, Sodium Hyaluronate', NOW(), NOW()),
(184, 'Bông Tẩy Trang 100% Cotton Tự Nhiên Dịu Nhẹ Skinfood Pure Cotton Puff 80 miếng', 'bong-tay-trang-100-cotton-tu-nhien-diu-nhe-skinfood-pure-cotton-puff-80-mieng', 'Bông tẩy trang chất liệu cotton thiên nhiên mềm mại, thấm hút tốt và không gây rát da.', 'Bông tẩy trang Skinfood Pure Cotton Puff được sản xuất từ 100% sợi cotton thiên nhiên mềm mại tuyển chọn kỹ lưỡng. Thiết kế miếng bông vuông vức dập viền nhẹ nhàng lướt êm ái trên làn da nhạy cảm, thấm hút nhanh các dung dịch lỏng như toner, lotion hay nước tẩy trang mà không bị xơ xù rách hay để lại vụn bông li ti trên mặt.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', '100% Pure Natural Cotton Fibers.', 'Thấm một lượng vừa đủ toner hoặc nước tẩy trang lên miếng bông tẩy trang, nhẹ nhàng lau khắp khuôn mặt theo chiều từ dưới lên trên.', 'Hàn Quốc', '80 miếng', 1, 4.85, 29, 114, 17, 0, 0, '100% Pure Natural Cotton, Soft Textured Puff', NOW(), NOW()),
(185, 'Sữa Rửa Mặt Lòng Trắng Trứng Se Khít Lỗ Chân Lông Skinfood Egg White Pore Foam 150ml', 'sua-rua-mat-long-trang-trung-se-khit-lo-chan-long-skinfood-egg-white-pore-foam-150ml', 'Bọt rửa mặt chiết xuất lòng trắng trứng Albumin làm sạch bã nhờn sâu và thu nhỏ lỗ chân lông to.', 'Skinfood Egg White Pore Foam là dòng sữa rửa mặt chuyên biệt cho làn da dầu có lỗ chân lông to. Chứa hàm lượng cao protein Albumin chiết xuất từ lòng trắng trứng gà tươi giúp làm sạch sâu tận đáy nang lông, hòa tan các sợi bã nhờn cứng đầu và dầu thừa bít tắc, đồng thời tăng cường độ đàn hồi, hỗ trợ se khít lỗ chân lông và mang lại làn da trắng sáng mịn màng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Myristic Acid, Glycerin, Potassium Hydroxide, Palmitic Acid, Stearic Acid, Lauric Acid, Sucrose, Cocamidopropyl Betaine, Olea Europaea (Olive) Fruit Oil, Egg Yolk Extract, Albumen Extract, Glyceryl Stearate, PEG-100 Stearate, Fragrance, Sodium Chloride, Disodium EDTA, Dipotassium Glycyrrhizate, Hydroxyethylcellulose, Butylene Glycol.', 'Lấy một lượng vừa đủ ra lòng bàn tay ướt, tạo bọt dày mịn màng rồi mát xa khắp mặt theo chiều xoắn ốc trong 1 phút, sau đó rửa sạch lại thật kỹ bằng nước ấm.', 'Hàn Quốc', '150ml', 1, 4.92, 30, 115, 17, 1, 0, 'Egg White Extract (Albumin), Amino Acids, Hot Spring Water', NOW(), NOW()),
(186, 'Chì Kẻ Mày Hai Đầu Dạng Dẹp Tự Nhiên The Face Shop Designing Eyebrow Pencil 0.3g', 'chi-ke-may-hai-dau-dang-dep-tu-nhien-the-face-shop-designing-eyebrow-pencil-0-3g', 'Chì kẻ mày đầu dẹp vát xéo kèm chổi chải định hình sợi mày tự nhiên lâu trôi không vón cục.', 'The Face Shop Designing Eyebrow Pencil là sản phẩm kẻ chân mày quốc dân được yêu chuộng suốt nhiều năm tại Hàn Quốc. Thiết kế 2 đầu tiện dụng gồm đầu chì dẹp hình tam giác vát xéo dễ dàng phẩy sợi mày hoặc tạo khuôn chân mày sắc nét, cùng đầu cọ xoắn chải mày giúp tán đều màu chì cho hàng chân mày thanh tú, tự nhiên và bám màu bền bỉ suốt cả ngày.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrogenated Soybean Oil, Hydrogenated Coco-Glycerides, Hydrogenated Vegetable Oil, Zinc Stearate, Stearic Acid, Copernicia Cerifera (Carnauba) Wax, Polyglyceryl-2 Triisostearate, Tocopherol, Caprylyl Glycol, Phenoxyethanol, Ascorbyl Palmitate, Hexylene Glycol. [+/- May Contain: CI 77499, CI 77491, CI 77492/Iron Oxides, Mica, CI 77891/Titanium Dioxide].', 'Dùng đầu chì định hình khuôn chân mày rồi phẩy nhẹ theo chiều mọc của sợi lông mày. Dùng đầu cọ chải xoắn chải nhẹ từ đầu đến đuôi mày để màu chì lan tỏa đều và tự nhiên.', 'Hàn Quốc', '0.3g', 1, 4.85, 31, 116, 18, 0, 0, 'Natural Plant Waxes, Long-lasting Mineral Pigments', NOW(), NOW()),
(187, 'Cọ Phủ Phấn Và Má Hồng Lông Mềm Tự Nhiên The Face Shop Daily Beauty Tools Powder & Blush Brush', 'co-phu-phan-va-ma-hong-long-mem-tu-nhien-the-face-shop-daily-beauty-tools-powder-blush-brush', 'Cọ trang điểm lông tròn xòe mềm mại đa năng dùng phủ phấn bột, phấn nén và đánh phấn má hồng.', 'The Face Shop Daily Beauty Tools Powder & Blush Brush là cây cọ trang điểm thiết yếu đa chức năng dành cho mọi bàn trang điểm. Đầu cọ được bó tròn xòe tự nhiên với hàng nghìn sợi lông nhân tạo cao cấp mềm mượt như nhung, lướt êm dịu trên da nhạy cảm mà không châm chích, giúp các hạt phấn phủ và phấn má bám đều, tạo lớp phủ mỏng nhẹ không cộm dày.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Synthetic PBT Bristles, Aluminum Ferrule, Matte Black Wood Handle.', 'Dùng cọ xoay tròn nhẹ trên bề mặt phấn phủ hoặc phấn má, vỗ nhẹ thân cọ để rũ bớt phấn thừa rồi quét nhẹ nhàng khắp khuôn mặt hoặc gò má.', 'Hàn Quốc', '1 cây', 1, 4.92, 32, 117, 18, 0, 0, 'High-grade Soft PBT Synthetic Bristles, Aluminum Ferrule', NOW(), NOW()),
(188, 'Kem Dưỡng Gót Chân Chống Nứt Nẻ The Face Shop Smile Foot Cream 100ml', 'kem-duong-got-chan-chong-nut-ne-the-face-shop-smile-foot-cream-100ml', 'Kem dưỡng làm mềm gót chân nứt nẻ chứa bơ hạt mỡ và tinh dầu thông giúp thư giãn và giảm chai sần da chân.', 'The Face Shop Smile Foot Cream là liệu pháp cứu cánh cho đôi bàn chân thô ráp, nứt nẻ và mệt mỏi. Chứa hàm lượng dồi dào bơ hạt mỡ Shea Butter, Urea làm mềm tế bào sừng dày và tinh dầu lá thông Pine Leaf Oil kháng khuẩn, kem làm dịu nhanh chóng các vết nứt nẻ gót chân đau rát, khử mùi hôi chân và trả lại đôi bàn chân mềm mại hồng hào.', 'https://images.unsplash.com/photo-1556228852-80b6e5eeff06?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Water/Eau, Glycerin, Urea, Cetearyl Alcohol, Caprylic/Capric Triglyceride, Butyrospermum Parkii (Shea) Butter, Glyceryl Stearate, Pinus Sylvestris Leaf Extract, Mentha Piperita (Peppermint) Leaf Extract, Dimethicone, PEG-100 Stearate, Carbomer, Triethanolamine, Disodium EDTA, Phenoxyethanol, Ethylhexylglycerin, Fragrance/Parfum.', 'Rửa sạch chân và lau khô hoàn toàn. Lấy một lượng kem vừa đủ thoa đều khắp bàn chân, gót chân và mắt cá chân, mát xa nhẹ nhàng cho kem thẩm thấu hết trước khi đi ngủ.', 'Hàn Quốc', '100ml', 1, 4.85, 33, 118, 18, 1, 0, 'Shea Butter, Urea, Pine Needle Oil, Peppermint Extract', NOW(), NOW()),
(189, 'Kem Dưỡng Da Tay Hương Hoa Anh Đào The Face Shop Daily Perfumed Hand Cream 30ml', 'kem-duong-da-tay-huong-hoa-anh-dao-the-face-shop-daily-perfumed-hand-cream-30ml', 'Kem dưỡng tay chứa bơ hạt mỡ và chiết xuất hoa anh đào dưỡng da tay mềm mịn lưu hương hoa dịu ngọt.', 'The Face Shop Daily Perfumed Hand Cream hương hoa anh đào Cherry Blossom mang đến cảm giác dưỡng ẩm dịu dàng và thư giãn cho đôi tay. Công thức kết hợp bơ hạt mỡ giàu dưỡng chất cùng chiết xuất hoa anh đào tươi giúp cấp ẩm sâu, làm mềm các vết chai ráp trên ngón tay mà không gây cảm giác nhờn dính khi cầm nắm hay làm việc trên máy tính.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Eau, Glycerin, Dipropylene Glycol, Mineral Oil/Huile Minerale, Cetearyl Alcohol, Butyrospermum Parkii (Shea) Butter, Glyceryl Stearate, PEG-100 Stearate, Prunus Serrulata Flower Extract, Dimethicone, Polysorbate 60, Carbomer, Potassium Hydroxide, Disodium EDTA, Phenoxyethanol, Ethylhexylglycerin, Parfum/Fragrance.', 'Lấy một lượng nhỏ thoa đều lên bàn tay và cổ tay bất cứ khi nào cảm thấy da tay bị khô ráp sau khi rửa tay hoặc tiếp xúc với xà phòng.', 'Hàn Quốc', '30ml', 1, 4.92, 34, 119, 18, 1, 0, 'Cherry Blossom Extract, Shea Butter, Glycerin', NOW(), NOW()),
(190, 'Bông Mút Trang Điểm Hình Giọt Nước The Face Shop Daily Beauty Tools Blending Sponge', 'bong-mut-trang-diem-hinh-giot-nuoc-the-face-shop-daily-beauty-tools-blending-sponge', 'Mút trang điểm đa năng chất liệu bọt xốp ngậm nước giúp tán đều kem nền và che khuyết điểm không tì vết.', 'The Face Shop Daily Beauty Tools Blending Sponge sở hữu thiết kế hình giọt nước thông minh: phần đáy bầu tròn tán đều kem nền trên vùng má và trán diện rộng, phần đầu nhọn dễ dàng len lỏi vào hốc mắt, khóe mũi và che khuyết điểm các nốt mụn. Chất liệu bọt xốp hydrophilic không chứa cao su tự nhiên (Latex-Free), nở to gấp 1.5 lần khi ngậm nước mang lại lớp nền căng bóng mướt mịn.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Non-Latex Polyurethane Hydrophilic Foam.', 'Làm ướt mút dưới vòi nước rồi bóp ráo nước để mút nở to và đạt độ ẩm lý tưởng. Chấm kem nền lên mặt rồi dùng mút dặm nhẹ nhàng (không miết) khắp mặt để lớp nền bám chặt và tự nhiên.', 'Hàn Quốc', '1 miếng', 1, 4.85, 35, 120, 18, 0, 0, '100% Non-Latex Hydrophilic Polyurethane Foam', NOW(), NOW()),
(191, 'Kem Dưỡng Cấp Ẩm Chuyên Sâu 100H Clinique Moisture Surge 100H Auto-Replenishing Hydrator 50ml', 'kem-duong-cap-am-chuyen-sau-100h-clinique-moisture-surge-100h-auto-replenishing-hydrator-50ml', 'Kem dưỡng dạng gel không dầu chứa men vi sinh lô hội độc quyền và HA cấp ẩm tự kích hoạt suốt 100 giờ.', 'Clinique Moisture Surge 100H Auto-Replenishing Hydrator là biểu tượng cấp ẩm cao cấp từ thương hiệu dược mỹ phẩm Clinique Mỹ. Công thức dạng gel mỏng nhẹ không chứa dầu (Oil-Free) chứa dịch lên men lô hội độc quyền Aloe Bio-Ferment và Hyaluronic Acid đa phân tử giúp kích hoạt nguồn nước nội sinh của làn da, giữ cho làn da ẩm mượt căng mọng suốt 100 giờ ngay cả sau khi đã rửa mặt.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Dimethicone, Butylene Glycol, Glycerin, Trisiloxane, Trehalose, Sucrose, Ammonium Acryloyldimethyltaurate/VP Copolymer, Hydroxyethyl Urea, Camellia Sinensis (Green Tea) Leaf Extract, Silybum Marianum (Lady''s Thistle) Extract, Betula Alba (Birch) Bark Extract, Saccharomyces Lysate Extract, Aloe Barbadensis Leaf Water, Aloe Barbadensis Leaf Extract, Thermus Thermophillus Ferment, Caffeine, Sorbitol, Palmitoyl Hexapeptide-12, Sodium Hyaluronate, Caprylyl Glycol, Oleth-10, Sodium Polyaspartate, Aloe Barbadensis Leaf Polysaccharides, Lactobacillus Ferment Lysate, Saccharide Isomerate, Hydrogenated Lecithin, Tocopheryl Acetate, Hexylene Glycol, Disodium EDTA, Sodium Citrate, Citric Acid, Phenoxyethanol.', 'Thoa lên mặt và cổ vào mỗi sáng và tối sau bước serum. Có thể dùng như mặt nạ cấp ẩm 5 phút hoặc thoa lên lớp trang điểm để làm tươi mới làn da tức thì.', 'Mỹ', '50ml', 1, 4.92, 36, 121, 19, 0, 0, 'Aloe Bio-Ferment, Hyaluronic Acid, Activated Aloe Water, Caffeine', NOW(), NOW()),
(192, 'Kem Dưỡng Vùng Mắt Giảm Quầng Thâm Bọng Mắt Clinique All About Eyes 15ml', 'kem-duong-vung-mat-giam-quang-tham-bong-mat-clinique-all-about-eyes-15ml', 'Kem mắt dạng gel cream mỏng nhẹ chứa Caffeine và chiết xuất rễ dâu tằm làm sáng quầng thâm và giảm bọng.', 'Clinique All About Eyes là dòng kem dưỡng mắt bán chạy số 1 của Clinique giúp xóa tan vẻ mệt mỏi của vùng da quanh mắt. Kết cấu dạng kem gel tươi mát kết hợp Caffeine đánh thức tuần hoàn vi mạch giảm bọng sưng, rễ dâu tằm và trà xanh làm sáng quầng thâm thâm quầng, đồng thời tạo lớp lót mịn màng giữ cho lớp che khuyết điểm mắt không bị đọng rãnh nhăn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Cyclopentasiloxane, Water/Aqua/Eau, Isostearyl Palmitate, Polyethylene, Butylene Glycol, Polysilicone-11, Ethylene/Acrylic Acid Copolymer, Morus Bombycis (Mulberry) Root Extract, Scutellaria Baicalensis Root Extract, Olea Europaea (Olive) Fruit Extract, Camellia Sinensis (Green Tea) Leaf Extract, Whey Protein/Lactis Protein, Phytosphingosine, Caffeine, Sodium Hyaluronate, Tocopheryl Acetate, Linoleic Acid, Dimethicone, BHT, Disodium EDTA, Phenoxyethanol.', 'Dùng ngón áp út lấy lượng kem nhỏ bằng hạt gạo thoa nhẹ nhàng quanh toàn bộ vùng mắt theo hướng từ khóe mắt trong ra đuôi mắt vào mỗi sáng và tối.', 'Mỹ', '15ml', 1, 4.85, 37, 122, 19, 0, 0, 'Caffeine, Mulberry Root Extract, Green Tea, Whey Protein', NOW(), NOW()),
(193, 'Sáp Tẩy Trang Làm Sạch Sâu Dịu Nhẹ Clinique Take The Day Off Cleansing Balm 125ml', 'sap-tay-trang-lam-sach-sau-diu-nhe-clinique-take-the-day-off-cleansing-balm-125ml', 'Sáp tẩy trang chuyển hóa từ sáp đặc thành dầu lỏng tan chảy cuốn trôi hoàn toàn lớp trang điểm không nhờn rít.', 'Clinique Take The Day Off Cleansing Balm là dòng sáp tẩy trang cao cấp số 1 thế giới với công thức không chứa hương liệu, không cồn, đã qua kiểm nghiệm nhãn khoa an toàn cho mắt nhạy cảm và người đeo kính áp tròng. Khi tiếp xúc với da, chất sáp cô đặc lập tức tan chảy thành lớp dầu mượt mà cuốn bay mascara chống nước, son lì và bụi bẩn mà không gây khô căng rát hay cay mắt.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Ethylhexyl Palmitate, Carthamus Tinctorius (Safflower) Seed Oil, Caprylic/Capric Triglyceride, Sorbeth-30 Tetraoleate, Polyethylene, PEG-5 Glyceryl Triisostearate, Water/Aqua/Eau, Tocopherol, Phenoxyethanol.', 'Dùng đầu ngón tay khô lấy lượng sáp vừa đủ mát xa lên da mặt và mắt khô để lớp sáp tan chảy thành dầu hòa tan lớp trang điểm. Thêm nước ấm để nhũ hóa rồi rửa sạch lại với nước.', 'Mỹ', '125ml', 1, 4.92, 38, 123, 19, 0, 0, 'Safflower Seed Oil, Ethylhexyl Palmitate, Caprylic/Capric Triglyceride', NOW(), NOW()),
(194, 'Bút Kẻ Mắt Lâu Trôi Tự Động Chống Lem Clinique Quickliner For Eyes Intense 0.28g', 'but-ke-mat-lau-troi-tu-dong-chong-lem-clinique-quickliner-for-eyes-intense-0-28g', 'Chì kẻ mắt dạng sáp xoay tự động sắc tố đậm nét kháng nước và mồ hôi kèm đầu mút tán khói.', 'Clinique Quickliner For Eyes Intense là dòng chì kẻ mắt kinh điển đã qua kiểm nghiệm nhãn khoa an toàn cho mắt nhạy cảm và người dùng kính áp tròng. Công thức dạng sáp kem lướt êm ái trên mí mắt mà không gây co kéo, màu sắc lên đậm nét chuẩn xác tức thì. Đầu bút tích hợp mút tán chuyên dụng giúp tán loang phong cách mắt khói quyến rũ trước khi lớp chì cố định kháng nước suốt 12 giờ.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Isododecane, Synthetic Wax, Hydrogenated Polydicyclopentadiene, PEG/PPG-18/18 Dimethicone, Polybutene, Glyceryl Tribehenate/Isostearate/Eicosandioate, Nylon-12, Polyethylene, Perfluorononyl Dimethicone, Polyglyceryl-4 Diisostearate/Polyhydroxystearate/Sebacate, Synthetic Beeswax, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Copernicia Cerifera (Carnauba) Wax. [+/- Iron Oxides (CI 77499, CI 77491, CI 77492), Mica, Titanium Dioxide (CI 77891)].', 'Xoay nhẹ đầu chì nhô lên khoảng 1-2mm (không xoay quá cao vì cơ chế tự động không vặn ngược lại). Kẻ sát theo đường viền mí mắt. Dùng đầu mút cao su ở đuôi bút tán nhẹ nếu muốn hiệu ứng mắt khói mềm mại.', 'Mỹ', '0.28g', 1, 4.85, 39, 124, 19, 0, 0, 'Water-resistant Cream Gel Formula, Ophthalmologist Tested, Smudge Sponge Tip', NOW(), NOW()),
(195, 'Mascara Làm Dày Tơi Và Cong Mi Tự Nhiên Clinique High Impact Mascara 7ml', 'mascara-lam-day-toi-va-cong-mi-tu-nhien-clinique-high-impact-mascara-7ml', 'Mascara thuần khiết được kiểm nghiệm nhãn khoa an toàn cho mắt siêu nhạy cảm làm dày và dài mi sắc nét.', 'Clinique High Impact Mascara là sản phẩm chuốt mi hoàn hảo cho những đôi mắt nhạy cảm dễ chảy nước mắt hoặc đeo kính áp tròng. Công thức chứa sắc tố khoáng đen tuyền đậm đặc cùng đầu cọ sợi tơ dày giúp chuốt từng sợi mi cong vút và dày dặn ngay tức thì mà không hề vón cục hay lem nhòe, mang lại ánh nhìn sâu thẳm quyến rũ.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Copernicia Cerifera (Carnauba) Wax, Stearic Acid, Glyceryl Stearate, Polyisobutene, Silica, Acrylates Copolymer, Aminomethyl Propanediol, VP/Eicosene Copolymer, Sodium Hyaluronate, Lauroyl Lysine, Pantethine, Melanin, Panthenol, Ethylhexylglycerin, Hydroxyethylcellulose, Calcium Aluminum Borosilicate, PVP, Acacia Senegal Gum, Isostearic Acid, Simethicone, Dimethicone PEG-8 Polyacrylate, Urea, Glycerin, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Sodium Dehydroacetate, Phenoxyethanol. [+/- Iron Oxides (CI 77491, CI 77492, CI 77499), Mica, Titanium Dioxide (CI 77891)].', 'Bắt đầu từ chân mi, lắc nhẹ đầu cọ theo chuyển động ziczac lên ngọn mi. Lặp lại để tăng cường độ dày mi mong muốn. Dễ dàng tẩy sạch bằng nước ấm hoặc nước tẩy trang chuyên dụng.', 'Mỹ', '7ml', 1, 4.92, 40, 125, 19, 0, 0, 'Ophthalmologist Tested Formula, Pure Mineral Pigments, Beeswax', NOW(), NOW()),
(196, 'Tinh Chất Chống Lão Hóa Ban Đêm Estée Lauder Advanced Night Repair Synchronized Multi-Recovery Complex 50ml', 'tinh-chat-chong-lao-hoa-ban-dem-estee-lauder-advanced-night-repair-50ml', 'Huyết thanh số 1 thế giới công nghệ Chronolux Power Signal phục hồi DNA tế bào và giảm nếp nhăn vượt trội.', 'Estée Lauder Advanced Night Repair (ANR) là tuyệt phẩm serum chống lão hóa ban đêm huyền thoại với hơn 40 năm dẫn đầu ngành thẩm mỹ. Công nghệ độc quyền Chronolux Power Signal kích hoạt cơ chế tự phục hồi tự nhiên của tế bào da vào ban đêm và thúc đẩy tăng sinh collagen mới. Serum cấp ẩm sâu 72 giờ, chống oxy hóa 8 giờ và làm mờ rõ rệt các dấu hiệu lão hóa sớm chỉ sau 3 tuần.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Bifida Ferment Lysate, PEG-8, Propanediol, Bis-PEG-18 Methyl Ether Dimethyl Silane, Methyl Gluceth-20, Glycereth-26, PEG-75, Butylene Glycol, Adansonia Digitata Seed Extract, Tripeptide-32, Sodium Hyaluronate, Yeast Extract/Faex/Extrait De Levure, Lactobacillus Ferment, Cola Acuminata (Kola) Seed Extract, Anthemis Nobilis (Chamomile) Flower Extract, Hydrolyzed Algin, Pantethine, Caffeine, Lecithin, Sodium RNA, Bisabolol, Squalane, Glycerin, Oleth-3 Phosphate, Caprylyl Glycol, Oleth-3, Oleth-5, Choleth-24, Hydrogenated Lecithin, Jojoba Wax PEG-120 Esters, Ceteth-24, Tocopheryl Acetate, Carbomer, Tetrasodium EDTA, BHT, Potassium Sorbate, Phenoxyethanol.', 'Dùng đều đặn vào mỗi buổi tối sau khi rửa mặt và thoa nước hoa hồng. Nhỏ một giọt đầy lên lòng bàn tay, xoa nhẹ hai bàn tay rồi áp đều lên trán, má, cằm và cổ, mát xa theo hình trái tim từ trung tâm mặt ra ngoài.', 'Mỹ', '50ml', 1, 4.85, 41, 126, 20, 0, 0, 'Chronolux Power Signal Technology, Bifida Ferment Lysate, Sodium Hyaluronate, Tripeptide-32', NOW(), NOW()),
(197, 'Kem Dưỡng Mắt Siêu Cường Phục Hồi Estée Lauder Advanced Night Repair Eye Supercharged Gel-Creme 15ml', 'kem-duong-mat-sieu-cuong-phuc-hoi-estee-lauder-advanced-night-repair-eye-supercharged-15ml', 'Kem mắt làm sáng quầng thâm trong 2 tuần và chống tác hại của ánh sáng xanh từ màn hình điện tử.', 'Estée Lauder Advanced Night Repair Eye Supercharged Gel-Creme được nghiên cứu chuyên biệt nhằm bảo vệ vùng mắt trước tác hại của ánh sáng xanh phát ra từ điện thoại và máy tính. Công thức phục hồi tế bào kép kết hợp Vitamin E chống oxy hóa tự nhiên và Axit Hyaluronic giúp làm mờ quầng thâm mắt chỉ sau 2 tuần, làm mịn các nếp nhăn vết chân chim và duy trì độ ẩm suốt 100 giờ.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Dimethicone, Methyl Trimethicone, Bifida Ferment Lysate, Dimethicone/Vinyl Dimethicone Crosspolymer, Propanediol, Petrolatum, Sucrose, Glycerin, Butylene Glycol, Acrylamide/Sodium Acryloyldimethyltaurate Copolymer, Trehalose, Tripeptide-32, Adansonia Digitata Seed Extract, Lavandula Angustifolia (Lavender) Flower Extract, Sodium Hyaluronate, Lactobacillus Ferment, Tocopheryl Acetate, Yeast Extract/Faex/Extrait De Levure, Morus Bombycis (Mulberry) Root Extract, Poria Cocos Sclerotium Extract, Scutellaria Baicalensis Root Extract, Anthemis Nobilis (Chamomile) Flower Extract, Betula Alba (Birch) Extract, Caffeine, Isohexadecane, Polysorbate 80, Phytosphingosine, Potassium Sorbate, Disodium EDTA, Phenoxyethanol, Iron Oxides (CI 77491).', 'Thoa một lượng nhỏ bằng hạt vừng quanh vùng bầu mắt và bọng mắt vào buổi sáng và tối. Vỗ nhẹ nhàng bằng ngón tay đeo nhẫn cho đến khi kem thẩm thấu hết.', 'Mỹ', '15ml', 1, 4.92, 42, 127, 20, 0, 0, 'Chronolux Power Signal, Blue Light Defense, Hyaluronic Acid, Vitamin E', NOW(), NOW()),
(198, 'Kem Nền Lâu Trôi Khóa Nền 24 Giờ Estée Lauder Double Wear Stay-in-Place Makeup SPF10 30ml', 'kem-nen-lau-troi-khoa-nen-24-gio-estee-lauder-double-wear-stay-in-place-makeup-spf10-30ml', 'Kem nền che phủ hoàn hảo bền màu suốt 24 giờ thách thức nắng nóng, mồ hôi và độ ẩm nhiệt đới.', 'Estée Lauder Double Wear Stay-in-Place Makeup là huyền thoại kem nền kiềm dầu che phủ đỉnh cao được hàng triệu tín đồ làm đẹp và chuyên gia trang điểm thế giới ca ngợi. Khả năng khóa nền bền màu suốt 24 giờ không đổi tông, không lem dính vào khẩu trang hay quần áo, kiểm soát lượng dầu bóng nhờn hoàn hảo mà vẫn giữ được lớp nền tự nhiên như làn da thứ hai.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Water/Aqua/Eau, Cyclopentasiloxane, Trimethylsiloxysilicate, Butylene Glycol, PEG/PPG-18/18 Dimethicone, Polyglyceryl-3 Diisostearate, Magnesium Sulfate, Tribehenin, Titanium Dioxide, Tocopheryl Acetate, Methicone, Polymethylsilsesquioxane, Laureth-7, Disteardimonium Hectorite, Cellulose Gum, Propylene Carbonate, Xanthan Gum, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Alumina, Phenoxyethanol, Sodium Dehydroacetate. [+/- Titanium Dioxide (CI 77891), Mica, Iron Oxides (CI 77491, CI 77492, CI 77499)].', 'Lắc đều chai trước khi dùng. Lấy lượng kem nền vừa phải ra mu bàn tay. Dùng cọ nền hoặc mút trang điểm ẩm dặm nhanh và đều khắp mặt từ trung tâm ra rìa ngoài khuôn mặt.', 'Mỹ', '30ml', 1, 4.85, 43, 128, 20, 0, 0, '24H Wear Polymers, Oil-Controlling Micro-pigments, SPF 10', NOW(), NOW()),
(199, 'Nước Hoa Nữ Quý Phái Quyến Rũ Estée Lauder Beautiful Magnolia Eau De Parfum 50ml', 'nuoc-hoa-nu-quy-phai-quyen-ru-estee-lauder-beautiful-magnolia-eau-de-parfum-50ml', 'Hương nước hoa cao cấp mở đầu bằng hoa mộc lan thanh khiết hòa quyện cùng hoa sen và gỗ tuyết tùng ấm áp.', 'Estée Lauder Beautiful Magnolia Eau De Parfum khắc họa câu chuyện tình yêu say đắm qua từng nốt hương hoa cỏ gỗ quyến rũ. Tầng hương đầu bừng sáng với cánh hoa mộc lan tinh khôi, hoa sen thanh khiết và tinh dầu lá trà xanh; tầng hương giữa say đắm của hoa dành dành và hoa hồng Thổ Nhĩ Kỳ; khép lại bằng nốt hương sâu lắng của gỗ tuyết tùng, hổ phách và xạ hương lôi cuốn.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Alcohol Denat., Fragrance (Parfum), Water/Aqua/Eau, Linalool, Benzyl Salicylate, Hexyl Cinnamal, Citronellol, Alpha-Isomethyl Ionone, Limonene, Hydroxycitronellal, Geraniol, Citral, Benzyl Alcohol, Farnesol, Isoeugenol, BHT, Ethylhexyl Methoxycinnamate, Butyl Methoxydibenzoylmethane, Ethylhexyl Salicylate.', 'Xịt nước hoa lên các điểm có mạch đập trên cơ thể như cổ tay, sau gáy, sau tai và hõm ngực từ khoảng cách 15cm. Không chà xát cổ tay để giữ nguyên cấu trúc các tầng hương.', 'Mỹ', '50ml', 1, 4.92, 44, 129, 20, 1, 1, 'Magnolia Petals, Lotus Flower, Turkish Rose, Cedarwood, Musk', NOW(), NOW()),
(200, 'Nước Thần Kích Hoạt Phục Hồi Da Estée Lauder Micro Essence Treatment Lotion 200ml', 'nuoc-than-kich-hoat-phuc-hoi-da-estee-lauder-micro-essence-treatment-lotion-200ml', 'Nước dưỡng tinh chất lên men sinh học Postbiotic củng cố màng phòng thủ và làm da căng mọng rạng rỡ.', 'Estée Lauder Micro Essence Treatment Lotion ứng dụng công nghệ lên men vi sinh độc quyền Postbiotic 12+ nuôi cấy từ men sinh học tự nhiên. Tinh chất thẩm thấu tức thì qua các tầng biểu bì, kích thích các chuỗi liên kết tế bào da tự sản sinh hàng rào bảo vệ vững chắc, làm dịu các kích ứng ẩn sâu dưới da và đem lại làn da sáng mịn căng bóng ngậm nước như sương mai.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Bifida Ferment Lysate, PEG-75, Propanediol, Butylene Glycol, Betaine, Pentylene Glycol, Lactobacillus Ferment, Acetyl Hexapeptide-8, Acetyl Glucosamine, Trehalose, Caffeine, Sodium Hyaluronate, Anthemis Nobilis (Chamomile) Flower Extract, Carbomer, Sodium Hydroxide, Disodium EDTA, Potassium Sorbate, Phenoxyethanol.', 'Sau khi làm sạch mặt, đổ 5-6 giọt nước thần ra lòng bàn tay ấm, áp nhẹ lên má, trán và cằm rồi vỗ đều trong 30 giây cho dưỡng chất thẩm thấu sâu trước bước tinh chất ANR.', 'Mỹ', '200ml', 1, 4.85, 45, 130, 20, 0, 0, 'Postbiotic 12+, Bifida Ferment Lysate, Lactobacillus Ferment, Sodium Hyaluronate', NOW(), NOW()),
(201, 'Nước Hoa Nam Đẳng Cấp Sang Trọng Dior Sauvage Eau De Parfum 100ml', 'nuoc-hoa-nam-dang-cap-sang-trong-dior-sauvage-eau-de-parfum-100ml', 'Tuyệt tác nước hoa nam biểu tượng với cam Bergamot vùng Calabria và hương khói Vanilla Papua New Guinea quyến rũ.', 'Dior Sauvage Eau De Parfum là kiệt tác nước hoa phương Đông sang trọng bậc nhất dành cho phái mạnh sáng tạo bởi nhà điều hương lừng danh François Demachy. Mở đầu bằng sự bùng nổ tươi mát của cam Bergamot mọng nước xứ Calabria nước Ý, tiếp nối bằng nốt hương tiêu Tứ Xuyên và hoa oải hương nồng nàn, lắng đọng trong nốt hương nền khói ấm áp ma mị của hổ phách Ambroxan và Vanilla nguyên chất từ Papua New Guinea.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'MALE', 'ALL', 'Alcohol, Parfum (Fragrance), Aqua (Water), Limonene, Linalool, Ethylhexyl Methoxycinnamate, Triethyl Citrate, Coumarin, Citronellol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Butyl Methoxydibenzoylmethane, Ethylhexyl Salicylate, Citral, BHT, Geraniol, Tocopherol, CI 60730 (Ext. Violet 2), CI 14700 (Red 4), CI 19140 (Yellow 5), CI 42090 (Blue 1).', 'Xịt trực tiếp lên các điểm mạch ấm trên cơ thể như cổ tay, hai bên mang tai, gáy và ngực từ khoảng cách 15-20cm để hương thơm khuếch tán tự nhiên và lưu hương suốt 12 giờ.', 'Pháp', '100ml', 1, 4.92, 46, 131, 21, 1, 1, 'Calabrian Bergamot, Sichuan Pepper, Ambroxan, Papua New Guinean Vanilla', NOW(), NOW()),
(202, 'Son Dưỡng Ẩm Có Màu Tự Nhiên Dior Addict Lip Glow 3.2g', 'son-duong-am-co-mau-tu-nhien-dior-addict-lip-glow-3-2g', 'Son dưỡng môi công nghệ Color Reviver tự biến đổi màu theo độ pH bờ môi với 97% thành phần nguồn gốc tự nhiên.', 'Dior Addict Lip Glow là thỏi son dưỡng có màu đẳng cấp thế giới được mệnh danh là ''công chúa son dưỡng''. Công nghệ phục hồi màu sắc Color Reviver thông minh tự động thích ứng với độ pH và nhiệt độ môi riêng biệt của mỗi người để tạo nên sắc hồng tự nhiên rạng rỡ. Công thức giàu dầu hoa anh đào Cherry Oil, bơ hạt mỡ và sáp thực vật dưỡng ẩm sâu 24 giờ cho bờ môi luôn căng mọng.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Polyglyceryl-2 Triisostearate, Helianthus Annuus (Sunflower) Seed Oil, Hydrogenated Castor Oil Dimer Dilinoleate, Phytosteryl/Octyldodecyl Lauroyl Glutamate, Jojoba Esters, Polyethylene, Candelilla Cera (Euphorbia Cerifera Wax), Behenyl Behenate, Helianthus Annuus Seed Cera, Butyrospermum Parkii (Shea) Butter, Oryza Sativa (Rice) Bran Wax, Caprylic/Capric Triglyceride, Parfum (Fragrance), Prunus Cerasus (Bitter Cherry) Seed Oil, Diisostearyl Malate, Tocopherol, Ascorbyl Palmitate. [+/- CI 77891, CI 45410, CI 15850, CI 77491].', 'Thoa trực tiếp lên môi một mình để có sắc hồng bóng nhẹ tự nhiên, hoặc thoa lót trước khi đánh son màu để bảo vệ môi và tăng cường độ căng mọng cho lớp son chính.', 'Pháp', '3.2g', 1, 4.85, 47, 132, 21, 1, 0, 'Color Reviver Technology, Cherry Oil, Shea Butter, Sunflower Wax', NOW(), NOW()),
(203, 'Son Kem Lì Bền Màu Không Lem Khẩu Trang Dior Rouge Dior Forever Liquid 6ml', 'son-kem-li-ben-mau-khong-lem-khau-trang-dior-rouge-dior-forever-liquid-6ml', 'Son kem lì đầu tiên của Dior kháng lem tuyệt đối (Transfer-proof) bám màu 12H với cảm giác nhẹ tênh bờ môi.', 'Dior Rouge Dior Forever Liquid đánh dấu bước tiến công nghệ trang điểm môi vượt bậc với chất son kem siêu mịn bám chặt vào viền môi mà không hề đọng rãnh hay xê dịch suốt 12 giờ. Ngay sau khi thoa, lớp son chuyển hóa thành màng màu lì mượt hoàn hảo, không để lại bất kỳ vệt son nào trên khẩu trang, thành ly hay trang phục nhưng vẫn giữ đôi môi mềm mại không khô ráp.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Trimethylsiloxysilicate, Isododecane, Mica, Cera Alba (Beeswax), Hydrogenated Polyisobutene, Candelilla Cera, Disteardimonium Hectorite, Propylene Carbonate, Paeonia Officinalis Flower Extract, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Simmondsia Chinensis (Jojoba) Seed Oil, Parfum (Fragrance), Silica Silylate, Tocopheryl Acetate. [+/- CI 15850, CI 77491, CI 77492, CI 77499, CI 77891].', 'Dùng đầu cọ hình cánh hoa lấy son thoa đều từ lòng môi ra khóe môi. Để son khô cố định hoàn toàn trong 5 phút mà không bặm môi để đạt hiệu ứng không lem tuyệt đối.', 'Pháp', '6ml', 1, 4.92, 48, 133, 21, 1, 0, 'Transfer-proof Ultra-pigmented Complex, Red Peony Extract', NOW(), NOW()),
(204, 'Kem Nền Căng Bóng Tự Nhiên Dior Forever Skin Glow Foundation SPF20 30ml', 'kem-nen-cang-bong-tu-nhien-dior-forever-skin-glow-foundation-spf20-30ml', 'Kem nền thế hệ mới 86% nền tảng dưỡng ẩm từ hoa diên vĩ và pansy mang lại hiệu ứng sáng bóng rạng rỡ 24H.', 'Dior Forever Skin Glow Foundation nâng tầm chuẩn mực trang điểm cao cấp với công thức chứa đến 86% thành phần dưỡng da gốc hoa cỏ thiên nhiên (hoa diên vĩ, hoa pansy dại, hoa dâm bụt). Sản phẩm mang lại lớp nền căng bóng rạng ngời từ sâu bên trong, ngậm nước suốt 24 giờ và bảo vệ làn da trước tia tử ngoại với chỉ số SPF 20 PA+++ mà không gây bít tắc sinh mụn.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua (Water), Alcohol, Methyl Trimethicone, Isododecane, Phenyl Trimethicone, Glycerin, Ethylhexyl Salicylate, Titanium Dioxide, PEG-9 Polydimethylsiloxyethyl Dimethicone, Trimethylsiloxysilicate, Acrylates/Dimethicone Copolymer, Dimethicone, Disteardimonium Hectorite, Iris Florentina Root Extract, Viola Tricolor Extract, Hibiscus Sabdariffa Flower Extract, Aluminum Hydroxide, Stearic Acid, Parfum (Fragrance), Tocopherol. [+/- CI 77891, CI 77491, CI 77492, CI 77499].', 'Chấm kem nền lên các vùng trán, má, mũi và cằm. Dùng cọ nền hoặc mút trang điểm dặm nhẹ nhàng từ trong ra ngoài để tạo độ căng bóng tự nhiên.', 'Pháp', '30ml', 1, 4.85, 49, 134, 21, 1, 0, '86% Floral Skincare Base (Iris, Wild Pansy, Hibiscus), SPF 20', NOW(), NOW()),
(205, 'Lăn Sáp Khử Mùi Nam Cao Cấp Dior Sauvage Deodorant Stick 75g', 'lan-sap-khu-mui-nam-cao-cap-dior-sauvage-deodorant-stick-75g', 'Sáp khử mùi không chứa cồn mang làn hương nam tính mạnh mẽ của dòng nước hoa huyền thoại Sauvage.', 'Dior Sauvage Deodorant Stick là sản phẩm sáp khử mùi cao cấp dành riêng cho phái mạnh, mang hương thơm sang trọng, phóng khoáng của dòng nước hoa Sauvage trứ danh. Công thức sáp dịu nhẹ không chứa cồn giúp bảo vệ vùng da dưới cánh tay khô thoáng, ngăn chặn vi khuẩn gây mùi suốt ngày dài mà không gây ố vàng áo sơ mi hay rát ngứa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'MALE', 'ALL', 'Propylene Glycol, Aqua (Water), Sodium Stearate, Nylon-12, Parfum (Fragrance), Laureth-23, Ethylhexylglycerin, Linalool, Coumarin, Citronellol, Limonene, Geraniol, Citral, Tocopherol.', 'Vặn đẩy sáp lên nhẹ nhàng và lăn trực tiếp lên vùng da nách khô sạch sau khi tắm. Để khô tự nhiên vài giây trước khi mặc trang phục.', 'Pháp', '75g', 1, 4.92, 50, 135, 21, 1, 0, 'Alcohol-free Stick Formula, Sauvage Fragrance Notes', NOW(), NOW()),
(206, 'Nước Hoa Nữ Quý Phái Quyến Rũ Chanel Coco Mademoiselle Eau De Parfum 100ml', 'nuoc-hoa-nu-quy-phai-quyen-ru-chanel-coco-mademoiselle-eau-de-parfum-100ml', 'Mùi hương phương Đông kinh điển tôn vinh sự thanh lịch, tự do và gợi cảm bất tận của người phụ nữ.', 'Chanel Coco Mademoiselle Eau De Parfum là biểu tượng mùi hương phương Đông tươi mát của nhà mốt danh giá Chanel. Khởi đầu với sự rực rỡ tươi mới của cam Bergamot và quýt Sicily; bừng nở ngọt ngào với nốt hương trung tâm của hoa hồng Thổ Nhĩ Kỳ và hoa nhài Grasse xứ Provence; khép lại đầy ma lực cuốn hút bằng hoắc hương Indonesia tinh tế, cỏ hương bài Haiti và xạ hương trắng.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Alcohol, Parfum (Fragrance), Aqua (Water), Linalool, Limonene, Benzyl Salicylate, Geraniol, Citronellol, Hexyl Cinnamal, Coumarin, Citral, Benzyl Alcohol, Ethylhexyl Methoxycinnamate, Butyl Methoxydibenzoylmethane, Ethylhexyl Salicylate, CI 14700 (Red 4), CI 19140 (Yellow 5), CI 42090 (Blue 1).', 'Xịt trực tiếp lên cổ áo, cổ tay, sau gáy và trước ngực từ khoảng cách 15-20cm để hương thơm lan tỏa quý phái suốt cả ngày dài.', 'Pháp', '100ml', 1, 4.85, 51, 136, 22, 1, 1, 'Sicilian Orange, Turkish Rose, Grasse Jasmine, Indonesian Patchouli', NOW(), NOW()),
(207, 'Kem Dưỡng Da Tay Trắng Mịn Cao Cấp Chanel La Crème Main Texture Riche 50ml', 'kem-duong-da-tay-trang-min-cao-cap-chanel-la-creme-main-texture-riche-50ml', 'Kem dưỡng tay thiết kế quả trứng độc bản chứa sáp hoa hồng tháng 5 và chiết xuất hoa diên vĩ quý giá.', 'Chanel La Crème Main Texture Riche là kiệt tác kem dưỡng da tay với thiết kế hình viên sỏi quả trứng sang trọng công thái học độc quyền không bị móp méo khi bóp. Công thức giàu dưỡng chất từ sáp hoa hồng tháng Năm May Rose làm mềm mượt da, chiết xuất rễ hoa diên vĩ Pallida dưỡng sáng mờ đốm nâu và bơ hạt mỡ dưỡng ẩm chuyên sâu cho đôi bàn tay và đầu móng tay bóng khỏe.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua (Water), Glycerin, Glycol Stearate SE, Butyrospermum Parkii (Shea) Butter, Cetyl Alcohol, Dimethicone, Jojoba Esters, Rosa Centifolia Flower Wax, Iris Pallida Root Extract, Glyceryl Stearate, PEG-100 Stearate, Sodium Carbomer, Caprylyl Glycol, Parfum (Fragrance), Chlorphenesin, Tocopheryl Acetate, Sodium Hyaluronate, Phytic Acid, Sodium Citrate, Sodium Benzoate.', 'Bóp nhẹ thân quả trứng để lấy lượng kem vừa đủ ra mu bàn tay. Xoa đều hai mu bàn tay và mát xa nhẹ nhàng từng ngón tay và khóe móng bất cứ khi nào thấy khô.', 'Pháp', '50ml', 1, 4.92, 52, 137, 22, 1, 0, 'May Rose Wax, Iris Pallida Extract, Shea Butter, Jojoba Esters', NOW(), NOW()),
(208, 'Phấn Phủ Bột Siêu Mịn Kiềm Dầu Chanel Poudre Universelle Libre 30g', 'phan-phu-bot-sieu-min-kiem-dau-chanel-poudre-universelle-libre-30g', 'Phấn phủ dạng bột khoáng vi hạt silica siêu nhẹ làm mờ lỗ chân lông và cố định lớp nền mịn lì tự nhiên.', 'Chanel Poudre Universelle Libre là dòng phấn phủ dạng bột huyền thoại tạo nên làn da trong suốt không tì vết. Các vi hạt silica khoáng chất siêu nhỏ nhẹ nhàng khuếch tán ánh sáng, làm mờ lỗ chân lông và các khuyết điểm nhỏ, đồng thời kiểm soát dầu thừa tiết ra mà không gây cảm giác bí bách hay khô mốc lớp nền trang điểm suốt cả ngày.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Talc, Silica, Synthetic Fluorphlogopite, Boron Nitride, Lauroyl Lysine, Dimethicone, Magnesium Myristate, Aluminum Hydroxide, Potassium Sorbate, Chlorphenesin, Parfum (Fragrance), Tocopheryl Acetate. [+/- CI 77491, CI 77492, CI 77499 (Iron Oxides), CI 77891 (Titanium Dioxide)].', 'Dùng bông phấn nhung sang trọng đi kèm chấm phấn trong hũ, vỗ nhẹ rũ bớt phấn thừa rồi dặm nhẹ nhàng lên toàn bộ khuôn mặt theo chiều từ trên xuống dưới.', 'Pháp', '30g', 1, 4.85, 53, 138, 22, 1, 0, 'Silica Microspheres, Photo-Reflective Pigments, Talc', NOW(), NOW()),
(209, 'Son Thỏi Lì Cao Cấp Chanel Rouge Allure Velvet 3.5g', 'son-thoi-li-cao-cap-chanel-rouge-allure-velvet-3-5g', 'Son thỏi lì vỏ đen bấm lò xo trứ danh với kết cấu mềm mượt như nhung và chiết xuất dầu jojoba dưỡng môi.', 'Chanel Rouge Allure Velvet tái định nghĩa chuẩn mực của son lì cao cấp: vừa lì ráo mịn màng như vải nhung quý tộc, vừa êm ái dưỡng ẩm không làm khô môi. Thiết kế vỏ đen tuyền nắp bấm lò xo click vàng kim sang trọng độc bản, chứa vi hạt sắc tố siêu mịn kết hợp tinh dầu jojoba và bơ hạt mỡ cho khả năng lên màu chuẩn xác và bám màu rạng ngời suốt 8 giờ.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Octyldodecanol, Dimethicone, Isononyl Isononanoate, Synthetic Wax, Cera Microcristallina, Silica, Dipentaerythrityl Hexahydroxystearate/Hexastearate/Hexarosinate, Butyrospermum Parkii (Shea) Butter, Simmondsia Chinensis (Jojoba) Seed Oil, Hydrogenated Castor Oil, Dimethicone Crosspolymer, Tocopherol, Parfum (Fragrance). [+/- CI 77891, CI 77491, CI 15850, CI 45410, CI 19140].', 'Ấn nhẹ đáy vỏ son để lõi son bật ra. Thoa trực tiếp lên môi từ tâm môi ra hai khóe môi để có bờ môi mịn lì sắc sảo chuẩn thượng lưu.', 'Pháp', '3.5g', 1, 4.92, 54, 139, 22, 1, 0, 'Jojoba Oil Derivatives, Shea Butter, Ultra-fine Pure Pigments', NOW(), NOW()),
(210, 'Lăn Sáp Khử Mùi Nam Đẳng Cấp Chanel Bleu de Chanel Deodorant Stick 75ml', 'lan-sap-khu-mui-nam-dang-cap-chanel-bleu-de-chanel-deodorant-stick-75ml', 'Sáp lăn nách cao cấp thơm mát nốt hương gỗ thơm nồng nàn của dòng nước hoa danh tiếng Bleu de Chanel.', 'Chanel Bleu de Chanel Deodorant Stick đem lại cảm giác tươi mát khô thoáng tức thì với làn hương gỗ thơm aromatic woody đầy nam tính và phóng khoáng. Công thức sáp không chứa cồn lướt êm ái trên vùng da dưới cánh tay, bảo vệ cơ thể khỏi mùi mồ hôi khó chịu và lưu giữ phong thái tự tin lịch lãm của quý ông suốt cả ngày dài.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'MALE', 'ALL', 'Propylene Glycol, Aqua (Water), Sodium Stearate, Laureth-23, Parfum (Fragrance), Limonene, Linalool, Citronellol, Coumarin, Geraniol, Citral, Farnesol, Ethylhexylglycerin, Sodium Hydroxide.', 'Vặn đáy thỏi sáp và thoa trực tiếp lên vùng da nách khô sạch sau khi tắm. Kết hợp cùng nước hoa Bleu de Chanel để tăng hiệu quả lưu hương đẳng cấp.', 'Pháp', '75ml', 1, 4.85, 20, 140, 22, 1, 0, 'Bleu de Chanel Aromatic Woody Notes, Alcohol-free Stick', NOW(), NOW()),
(211, 'Nước Hoa Nữ Quyến Rũ Tự Do Yves Saint Laurent YSL Libre Eau De Parfum 90ml', 'nuoc-hoa-nu-quyen-ru-tu-do-yves-saint-laurent-ysl-libre-eau-de-parfum-90ml', 'Mùi hương tuyên ngôn cho sự tự do kết hợp tinh tế giữa hoa oải hương Pháp và hoa cam Morocco rực rỡ.', 'Yves Saint Laurent YSL Libre Eau De Parfum là tuyệt tác nước hoa đương đại biểu trưng cho sự gợi cảm, mạnh mẽ và tự do của người phụ nữ hiện đại. Tinh túy từ hoa oải hương Diva Lavender tươi mát từ miền Nam nước Pháp giao thoa cùng hoa cam Morocco nồng nàn quyến rũ, được thăng hoa trong vị ngọt ngào của vani Madagascar và hổ phách sang trọng, thiết kế chai viền logo kim loại YSL Cassandre đắt giá.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Alcohol, Parfum/Fragrance, Aqua/Water, Limonene, Linalool, Benzyl Salicylate, Hydroxycitronellal, Benzyl Alcohol, Ethylhexyl Salicylate, Butyl Methoxydibenzoylmethane, Coumarin, Geraniol, Methyl Anthranilate, Citronellol, Citral, Isoeugenol, Alpha-Isomethyl Ionone, Farnesol, CI 15985/Yellow 6, CI 19140/Yellow 5, CI 60730/Ext. Violet 2.', 'Xịt trực tiếp lên cổ, cổ tay và sau gáy từ khoảng cách 15-20cm để hương thơm tỏa ngát tự tin suốt 12 giờ.', 'Pháp', '90ml', 1, 4.92, 21, 141, 23, 1, 1, 'French Lavender, Moroccan Orange Blossom, Madagascar Vanilla, Ambergris', NOW(), NOW()),
(212, 'Son Thỏi Lì Thiết Kế Vuông Sang Trọng YSL Rouge Pur Couture The Slim 2.2g', 'son-thoi-li-thiet-ke-vuong-sang-trong-ysl-rouge-pur-couture-the-slim-2-2g', 'Thỏi son vuông thanh mảnh cao cấp mạ vàng với kết cấu lì da thuộc mịn mượt lên màu sắc nét.', 'YSL Rouge Pur Couture The Slim được mệnh danh là nữ hoàng của những thỏi son lì với thiết kế thân son hình trụ vuông mạ vàng sang trọng thanh mảnh. Đầu son vát vuông góc cạnh độc đáo cho phép viền khóe môi và nhân trung chuẩn xác như cọ chuyên nghiệp. Chất son da thuộc Leather-Matte siêu lì mịn che phủ rãnh môi hoàn hảo, bền màu suốt cả ngày.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Bis-Diglyceryl Polyacyladipate-2, Hydrogenated Polyisobutene, Phenyl Trimethicone, Tridecyl Trimellitate, Ozokerite, Hydrogenated Jojoba Oil, Dimethicone Crosspolymer, Isostearyl Isostearate, Kaolin, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Nylon-12, Alumina, Polyethylene, Synthetic Fluorphlogopite, BHT, Parfum/Fragrance. [+/- CI 77891, CI 15850, CI 77491, CI 77499, CI 45410].', 'Dùng góc nhọn của đầu son viền đường đỉnh môi và góc khóe môi, sau đó dùng cạnh phẳng tô kín lòng môi để tạo bờ môi lì quyến rũ.', 'Pháp', '2.2g', 1, 4.85, 22, 142, 23, 1, 0, 'Leather-Matte High-Density Pigments, Jojoba Oil', NOW(), NOW()),
(213, 'Mascara Làm Dài Cong Mi Cao Cấp YSL Lash Clash Extreme Volume Mascara 9ml', 'mascara-lam-dai-cong-mi-cao-cap-ysl-lash-clash-extreme-volume-mascara-9ml', 'Mascara cao cấp tăng độ dày mi tức thì lên đến 200% với chiết xuất hoa diên vĩ vùng Ourika.', 'Yves Saint Laurent Lash Clash Extreme Volume Mascara là kiệt tác chuốt mi phá vỡ mọi giới hạn về độ dày và độ sắc sảo cho làn mi. Đầu cọ hình nón cỡ lớn độc quyền Double-conical Brush ôm trọn từng sợi mi ngắn nhất, phủ đều sắc tố siêu đen tuyền Overnoir và chiết xuất hoa diên vĩ Iris Florentina nuôi dưỡng nang mi, tạo hiệu ứng mi dày cong kịch tính suốt 24 giờ không lem nhòe.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua/Water, CI 77499/Iron Oxides, Behenyl Behenate, Ethylenediamine/Stearyl Dimer Dilinoleate Copolymer, Styrene/Acrylates/Ammonium Methacrylate Copolymer, Cetearyl Alcohol, Stearic Acid, Palmitic Acid, PVP, VP/Eicosene Copolymer, Aminomethyl Propanediol, Phenoxyethanol, Caprylyl Glycol, Butylene Glycol, Myristic Acid, Sodium Laureth Sulfate, Tetrasodium EDTA, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Potassium Sorbate, Iris Florentina Root Extract.', 'Bắt đầu chuốt từ gốc mi, lắc nhẹ đầu cọ theo hình ziczac hướng lên ngọn mi. Chuốt nhiều lớp từ gốc đến ngọn mi để đạt độ dày và cong mi tối đa như ý muốn.', 'Pháp', '9ml', 1, 4.92, 23, 143, 23, 1, 0, 'Iris Florentina Extract, Overnoir Deep Black Pigments, Double-conical Brush', NOW(), NOW()),
(214, 'Phấn Nước Vỏ Da Cao Cấp YSL Le Cushion Encre De Peau Luminous Matte SPF50+ 14g', 'phan-nuoc-vo-da-cao-cap-ysl-le-cushion-encre-de-peau-luminous-matte-spf50-14g', 'Cushion vỏ bọc da chần Chevron kinh điển kiềm dầu tự nhiên và bắt sáng rạng rỡ với tinh chất hoa nhài.', 'YSL Le Cushion Encre De Peau là biểu tượng thời trang và làm đẹp xa xỉ với thiết kế vỏ hộp bọc da chần họa tiết Chevron kinh điển cùng logo mạ vàng YSL huyền thoại. Công thức chứa chiết xuất hoa nhài từ khu vườn cộng đồng Ourika của YSL giúp chống oxy hóa và giữ ẩm cho da, kết hợp hạt vi phấn khoáng kiểm soát dầu thừa mang lại lớp nền lì sáng Luminous Matte rạng ngời suốt 24 giờ.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua/Water, Methyl Trimethicone, Dimethicone, Ethylhexyl Methoxycinnamate, Titanium Dioxide, Ethylhexyl Salicylate, Glycerin, Butylene Glycol Dicaprylate/Dicaprate, Lauryl PEG-9 Polydimethylsiloxyethyl Dimethicone, Diphenylsiloxy Phenyl Trimethicone, Pentylene Glycol, Butylene Glycol, Jasminum Officinale (Jasmine) Flower Extract, Tocopherol, Parfum/Fragrance. [+/- CI 77891, CI 77491, CI 77492, CI 77499].', 'Dùng bông phấn ấn nhẹ lấy lượng kem vừa đủ rồi dặm đều khắp khuôn mặt từ trong ra ngoài. Dặm thêm ở vùng chữ T để cố định nền.', 'Pháp', '14g', 1, 4.85, 24, 144, 23, 1, 0, 'Jasmine Petal Extract, Neo Skin Powder, SPF 50+ PA+++', NOW(), NOW()),
(215, 'Nước Hoa Nam Phóng Khoáng Nam Tính YSL Y Eau De Parfum 100ml', 'nuoc-hoa-nam-phong-khoang-nam-tinh-ysl-y-eau-de-parfum-100ml', 'Nước hoa nam hương dương xỉ phương Đông kết hợp táo xanh giòn tan, cây xô thơm và gỗ tuyết tùng mãnh liệt.', 'Yves Saint Laurent Y Eau De Parfum là mùi hương của người đàn ông dám nghĩ, dám làm và tự tin theo đuổi đam mê. Nốt hương đầu bùng nổ tươi mới với hương táo xanh giòn giã và gừng cay nồng; nốt hương giữa thanh lịch với hoa phong lữ và xô thơm nồng ấm; nốt hương cuối đọng lại bằng gỗ tuyết tùng sâu thẳm, đậu Tonka và trầm hương olibanum mê hoặc đầy bản lĩnh.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'MALE', 'ALL', 'Alcohol, Parfum/Fragrance, Aqua/Water, Limonene, Linalool, Butyl Methoxydibenzoylmethane, Citral, Citronellol, Alpha-Isomethyl Ionone, Geraniol, Coumarin, CI 60730/Ext. Violet 2, CI 15985/Yellow 6, CI 42090/Blue 1.', 'Xịt 2-3 lần lên cổ, cổ tay và gáy từ khoảng cách 15cm sau khi tắm để hương thơm khuếch tán mạnh mẽ và lưu hương bền bỉ suốt 12 tiếng.', 'Pháp', '100ml', 1, 4.92, 25, 145, 23, 1, 1, 'Crisp Green Apple, Sage, Geranium, Cedarwood, Tonka Bean', NOW(), NOW()),
(216, 'Son Thỏi Lì Cổ Điển Đỏ Ruby MAC Matte Lipstick 707 Ruby Woo 3g', 'son-thoi-li-co-dien-do-ruby-mac-matte-lipstick-707-ruby-woo-3g', 'Thỏi son đỏ Retro Matte huyền thoại của MAC với tông đỏ ánh xanh tôn da làm trắng răng bất hủ.', 'MAC Matte Lipstick tông 707 Ruby Woo là thỏi son đỏ huyền thoại bán chạy nhất lịch sử làm đẹp toàn cầu. Thuộc dòng son Retro Matte siêu lì kinh điển của MAC, Ruby Woo sở hữu sắc đỏ thuần ánh xanh kiêu kỳ, có khả năng tôn sáng mọi tông da và tạo hiệu ứng răng trắng sáng vượt trội. Chất son lên màu chuẩn sắc ngay từ lần chạm đầu tiên và bền màu bền bỉ suốt 10 giờ.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Isoeicosane, Kaolin, Ceresin, Paraffin, Isononyl Isononanoate, Microcrystalline Wax/Cera Microcristallina, Silica, Caprylic/Capric Triglyceride, Copernicia Cerifera (Carnauba) Wax, Hydrogenated Polyisobutene, Vanillin, Tocopherol, Glyceryl Linoleate, Glyceryl Linolenate, PVP/Hexadecene Copolymer. [+/- Mica, Titanium Dioxide (CI 77891), Iron Oxides (CI 77491, CI 77492, CI 77499), Red 7 Lake (CI 15850)].', 'Thoa son dưỡng môi trước khi dùng. Thoa trực tiếp thỏi son lên môi từ viền môi vào trong hoặc dùng cọ môi để tạo đường viền môi sắc sảo hoàn hảo.', 'Mỹ', '3g', 1, 4.85, 26, 146, 24, 1, 0, 'Retro Matte Formula, Castor Oil, Carnauba Wax, Intense Red Pigments', NOW(), NOW()),
(217, 'Kem Nền Kiềm Dầu Chuẩn Studio Lâu Trôi MAC Studio Fix Fluid SPF 15 30ml', 'kem-nen-kiem-dau-chuan-studio-lau-troi-mac-studio-fix-fluid-spf-15-30ml', 'Kem nền chuyên nghiệp kiểm soát dầu thừa 24 giờ, che phủ từ trung bình đến cao không gây mụn.', 'MAC Studio Fix Fluid SPF 15 là sản phẩm kem nền chuyên nghiệp xuất hiện trong mọi hậu trường sàn diễn thời trang thế giới. Công thức hiện đại kết hợp lớp nền lì tự nhiên cùng khả năng kiểm soát bã nhờn và độ bóng dầu suốt 24 giờ mà không gây khô da hay vỡ nền. Khả năng che phủ hoàn hảo các vết thâm, lỗ chân lông to và mẩn đỏ với bảng màu phong phú chuẩn xác.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Water/Aqua/Eau, Cyclopentasiloxane, PEG-10 Dimethicone, Butylene Glycol, Trimethylsiloxysilicate, Ethylhexyl Methoxycinnamate, Dimethicone, Magnesium Sulfate, Titanium Dioxide, Laminaria Saccharina Extract, Algae Extract, Tocopheryl Acetate, Sodium Hyaluronate, Tocopherol, Lecithin, Hydrogenated Lecithin, Xanthan Gum, Sorbitan Sesquioleate, Methoxy Amodimethicone/Silsesquioxane Copolymer, Laureth-7, Dipropylene Glycol, Dimethicone/PEG-10/15 Crosspolymer, Dimethicone/Vinyl Dimethicone Crosspolymer, PEG/PPG-18/18 Dimethicone, Disteardimonium Hectorite, Silica, Triethoxycaprylylsilane, Propylene Carbonate, BHT, Disodium EDTA, Phenoxyethanol. [+/- Titanium Dioxide (CI 77891), Iron Oxides (CI 77491, CI 77492, CI 77499)].', 'Cho một lượng kem nền vừa phải ra mu bàn tay. Sử dụng cọ nền MAC 170 hoặc mút trang điểm dặm đều từ trung tâm mặt ra xung quanh để lớp nền tệp da mượt mà.', 'Mỹ', '30ml', 1, 4.92, 27, 147, 24, 0, 0, 'Silica Oil-Control Powders, Vitamin E, SPF 15 Protection', NOW(), NOW()),
(218, 'Phấn Phủ Khoáng Nén Định Hình Nền MAC Mineralize Skinfinish Natural 10g', 'phan-phu-khoang-nen-dinh-hinh-nen-mac-mineralize-skinfinish-natural-10g', 'Phấn phủ khoáng nướng nén thủ công chứa 77 khoáng chất nuôi dưỡng làn da căng mịn tự nhiên.', 'MAC Mineralize Skinfinish Natural là dòng phấn phủ nén khoáng chất nướng chậm (slow-baked) độc đáo của MAC. Chứa phức hợp 77 khoáng chất tự nhiên và Vitamin E giúp định hình lớp trang điểm bền bỉ, làm mờ lỗ chân lông và mang lại hiệu ứng làn da mịn màng đa chiều mà không làm mất đi độ căng bóng tự nhiên của khuôn mặt.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Mica, Talc, Dimethicone, Isopropyl Palmitate, Polysorbate 20, Magnesium Aluminum Silicate, Tocopheryl Acetate, Simmondsia Chinensis (Jojoba) Seed Oil, Yeast Extract/Faex/Extrait De Levure, Lauroyl Lysine, Ethylhexyl Methoxycinnamate, Sodium Dehydroacetate, Phenoxyethanol. [+/- Titanium Dioxide (CI 77891), Iron Oxides (CI 77491, CI 77492, CI 77499)].', 'Dùng cọ phấn phủ quét một lớp nhẹ nhàng lên toàn bộ khuôn mặt sau khi thoa kem nền để khóa chặt lớp nền, hoặc dùng dặm lại trong ngày khi da tiết dầu.', 'Mỹ', '10g', 1, 4.85, 28, 148, 24, 0, 0, '77-Mineral Complex, Vitamin E, Pearlized Pigments, Jojoba Oil', NOW(), NOW()),
(219, 'Phấn Má Hồng Khoáng Nướng Tự Nhiên MAC Mineralize Blush 3.2g', 'phan-ma-hong-khoang-nuong-tu-nhien-mac-mineralize-blush-3-2g', 'Phấn má nướng khoáng chất siêu mịn tạo hiệu ứng gò má ửng hồng tỏa sáng tự nhiên.', 'MAC Mineralize Blush được nướng chậm thủ công trên các đĩa đất nung truyền thống để tạo nên kết cấu hạt phấn khoáng siêu mịn nhẹ như không khí. Các hạt nhũ ngọc trai siêu nhỏ phản chiếu ánh sáng tự nhiên, lướt êm ái trên da mang lại đôi gò má ửng hồng tươi tắn, rạng rỡ và bắt sáng tự nhiên mà không làm lộ các khuyết điểm hay lỗ chân lông.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Mica, Talc, Dimethicone, Isopropyl Palmitate, Tocopheryl Acetate, Lauroyl Lysine, Simmondsia Chinensis (Jojoba) Seed Oil, Yeast Extract/Faex/Extrait De Levure, Polysorbate 20, Magnesium Aluminum Silicate, Ethylhexyl Methoxycinnamate, Sodium Dehydroacetate, Phenoxyethanol. [+/- Titanium Dioxide (CI 77891), Iron Oxides (CI 77491, CI 77492, CI 77499), Red 7 Lake (CI 15850)].', 'Dùng cọ má hồng lấy phấn, vỗ nhẹ rũ bớt phấn thừa rồi tán nhẹ nhàng lên đỉnh gò má theo hướng chéo lên thái dương để tạo hiệu ứng gò má nâng cao thon gọn.', 'Mỹ', '3.2g', 1, 4.92, 29, 149, 24, 0, 0, '77-Mineral Baked Formula, Pearl Micro-pigments, Jojoba Seed Oil', NOW(), NOW()),
(220, 'Cọ Trang Điểm Đánh Nền Bo Tròn Chuyên Nghiệp MAC 170 Synthetic Rounded Slant Brush', 'co-trang-diem-danh-nen-bo-tron-chuyen-nghiep-mac-170-synthetic-rounded-slant-brush', 'Cọ tán nền vát tròn sợi lông nhân tạo mật độ dày đặc tạo lớp nền mịn lì hoàn hảo không tì vết.', 'Cọ MAC 170 Synthetic Rounded Slant Brush là cây cọ nền huyền thoại được các chuyên gia trang điểm hàng đầu thế giới tôn vinh. Sở hữu đầu cọ vát xéo bo tròn độc đáo cùng hàng ngàn sợi lông nhân tạo siêu mềm được ép chặt chẽ, cọ lướt êm ái trên da, giúp tán kem nền, phấn đặc hay serum nền một cách nhanh chóng, che phủ tối đa mà hoàn toàn không để lại bất kỳ vệt cọ nào.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', '100% High-grade Synthetic Fibers, Nickel-plated Brass Ferrule, Lacquered Birch Wood Handle.', 'Chấm kem nền lên mặt hoặc đầu cọ, tán đều bằng các chuyển động tròn nhỏ hoặc dặm nhẹ từ trung tâm khuôn mặt ra ngoài viền khuôn mặt.', 'Mỹ', '1 cây', 1, 4.85, 30, 150, 24, 0, 0, '100% Synthetic Fibers, Nickel-Plated Brass Ferrule, Wooden Handle', NOW(), NOW()),
(221, 'Phấn Má Hồng Ánh Nhũ Vàng Huyền Thoại NARS Blush 4.8g Tông Orgasm', 'phan-ma-hong-anh-nhu-vang-huyen-thoai-nars-blush-4-8g-tong-orgasm', 'Màu má hồng bán chạy số 1 hành tinh tông hồng đào pha ánh nhũ vàng gold tôn vinh mọi sắc tộc da.', 'NARS Blush tông Orgasm là biểu tượng má hồng kinh điển của nhà sáng lập François NARS, được ca ngợi là màu má đẹp nhất lịch sử ngành mỹ phẩm. Sự kết hợp hoàn mỹ giữa sắc hồng đào ấm áp và hạt nhũ vàng gold siêu mịn đem lại đôi gò má ửng sáng tự nhiên, căng tràn sức sống và phù hợp với mọi tông màu da từ sáng đến ngăm đen.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Talc, Octyldodecyl Stearate, Octyldodecyl Stearoyl Stearate, Zinc Stearate, Tin Oxide, Caprylyl Glycol, Phenoxyethanol. [+/- Mica, Titanium Dioxide (CI 77891), Iron Oxides (CI 77491), Carmine (CI 75470), Yellow 5 Lake (CI 19140), Red 30 Lake (CI 73360)].', 'Dùng cọ phấn má lấy một lượng phấn nhẹ, cười nhẹ để xác định đỉnh gò má rồi tán phấn nhẹ nhàng theo chiều hướng lên phía thái dương.', 'Mỹ', '4.8g', 1, 4.92, 31, 151, 25, 0, 0, 'Micronized Powder Pigments, Golden Shimmer Minerals', NOW(), NOW()),
(222, 'Kem Che Khuyết Điểm Căng Mịn Bền Màu NARS Radiant Creamy Concealer 6ml', 'kem-che-khuyet-diem-cang-min-ben-mau-nars-radiant-creamy-concealer-6ml', 'Che khuyết điểm số 1 nước Mỹ che phủ hoàn hảo quầng thâm và mụn với độ ẩm mượt suốt 16 giờ.', 'NARS Radiant Creamy Concealer là thỏi kem che khuyết điểm được yêu thích nhất toàn cầu nhờ kết cấu kem mịn mượt giàu dưỡng chất từ hạt nho, dầu jojoba và Vitamin E. Công nghệ khuếch tán ánh sáng Light-Diffusing làm mờ quầng thâm mắt, các vết thâm mụn và đốm đỏ ngay tức thì mà không hề bị đọng rãnh nhăn hay khô mốc suốt 16 giờ.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua (Water), Dimethicone, Hydrogenated Polydecene, Propanediol, Butylene Glycol, PEG-9 Polydimethylsiloxyethyl Dimethicone, Glycerin, Disteardimonium Hectorite, PEG-10 Dimethicone, Polymethyl Methacrylate, Bis-Butyldimethicone Polyglyceryl-3, Sorbitan Sesquiisostearate, Dimethicone/Vinyl Dimethicone Crosspolymer, Phenoxyethanol, Isostearic Acid, Aluminum Hydroxide, Polysilicone-2, Maltodextrin, Trisodium EDTA, Lecithin, Silica, Tin Oxide, Tocopheryl Acetate. [+/- Mica, CI 77891, CI 77491, CI 77492, CI 77499].', 'Dùng đầu cọ chấm trực tiếp lên các nốt thâm mụn, quầng thâm mắt hoặc vùng da đỏ rát. Dùng ngón tay hoặc mút trang điểm ẩm dặm nhẹ nhàng cho kem tệp vào da.', 'Mỹ', '6ml', 1, 4.85, 32, 152, 25, 0, 0, 'Mineral Tone-Balancing Powder, Grape Seed Extract, Vitamin E', NOW(), NOW()),
(223, 'Phấn Phủ Bột Trong Suốt Bắt Sáng NARS Light Reflecting Setting Powder Loose 11g', 'phan-phu-bot-trong-suot-bat-sang-nars-light-reflecting-setting-powder-loose-11g', 'Phấn phủ không màu trong suốt ứng dụng công nghệ phản chiếu ánh sáng giúp khóa chặt lớp nền suốt 16H.', 'NARS Light Reflecting Setting Powder Loose chứa công nghệ phản xạ ánh sáng độc quyền Photochromic Technology giúp điều chỉnh độ sáng tối theo từng môi trường ánh sáng khác nhau, tránh hiện tượng mặt trắng bệch khi chụp ảnh flash. Các hạt phấn khoáng vô hình khóa chặt lớp trang điểm cả ngày, làm mờ lỗ chân lông và kiểm soát bóng dầu tối ưu.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Silica, Polymethylsilsesquioxane, Dimethicone, Lauroyl Lysine, Trimethylsiloxysilicate, Glycerin, Magnesium Silicate, Ethylhexylglycerin, Tocopheryl Acetate, Cetearyl Dimethicone/Vinyl Dimethicone Crosspolymer, Phenoxyethanol, Potassium Sorbate.', 'Dùng cọ phủ lấy lượng phấn nhỏ, xoay tròn cọ vào nắp hộp để phấn phân bố đều rồi phủ nhẹ nhàng khắp khuôn mặt từ trung tâm ra ngoài.', 'Mỹ', '11g', 1, 4.92, 33, 153, 25, 0, 0, 'Photochromic Technology, Glycerin, Vitamin E', NOW(), NOW()),
(224, 'Son Thỏi Lì Siêu Nhẹ Môi Bền Màu 10 Giờ NARS Powermatte Lipstick 1.5g', 'son-thoi-li-sieu-nhe-moi-ben-mau-10-gio-nars-powermatte-lipstick-1-5g', 'Son thỏi lì chuyển hóa từ dạng kem mượt thành lớp màng mịn như nhung bám chặt bờ môi suốt 10 tiếng.', 'NARS Powermatte Lipstick là kiệt tác son lì với phức hợp màu Power Pigment Complex đậm đặc thuần chất. Chất son lướt trên môi trơn tru như kem rồi chuyển hóa thành lớp màng son lì mượt vô trọng lượng, không lem dính, không khô môi và giữ màu chuẩn nét suốt 10 giờ.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Isododecane, Synthetic Wax, Polyglyceryl-2 Triisostearate, Caprylyl Methicone, Dicalcium Phosphate, Disteardimonium Hectorite, Propylene Carbonate, Tocopherol, Lecithin, Ascorbyl Palmitate, Citric Acid. [+/- CI 77891, CI 77491, CI 77492, CI 15850, CI 42090].', 'Vặn son lên khoảng 1-2mm và thoa trực tiếp lên môi. Để son khô tự nhiên trong vài giây để lớp màu cố định hoàn toàn.', 'Mỹ', '1.5g', 1, 4.85, 34, 154, 25, 0, 0, 'Power Pigment Complex, Pure Color Locking Polymers', NOW(), NOW()),
(225, 'Bút Chì Kẻ Mắt Dạng Gel Bền Màu NARS High-Pigment Longwear Eyeliner 1.1g', 'but-chi-ke-mat-dang-gel-ben-mau-nars-high-pigment-longwear-eyeliner-1-1g', 'Chì kẻ mắt gel chống lem trôi suốt 12 giờ nét chì trơn tru không kéo giật mí mắt.', 'NARS High-Pigment Longwear Eyeliner mang lại đường kẻ mắt đậm nét và sắc sảo chỉ trong một lần quẹt nhẹ nhàng. Kết cấu gel siêu mềm mại lướt êm ái trên mí mắt mà không gây đau rát hay kéo giật mi, nhanh chóng khô lại thành lớp màng chống nước, mồ hôi và độ ẩm tuyệt đối suốt 12 giờ.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Synthetic Wax, Trimethylsiloxysilicate, C30-50 Alcohols, Hydrogenated Jojoba Oil, Polybutene, Bis-Hydroxyethoxypropyl Dimethicone, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate. [+/- CI 77499 (Iron Oxides), CI 77510 (Ferric Ferrocyanide), Mica].', 'Kẻ sát chân mi trên từ góc trong ra ngoài đuôi mắt. Có thể kẻ thêm đường mi dưới để tạo ánh nhìn sâu cuốn hút.', 'Mỹ', '1.1g', 1, 4.92, 35, 155, 25, 0, 0, 'High-Density Pigment Gel, Waterproof Film Polymers', NOW(), NOW()),
(226, 'Phấn Má Hồng Mịn Nhỏ Tự Nhiên 3CE Mood Recipe Face Blush 5.5g', 'phan-ma-hong-min-nho-tu-nhien-3ce-mood-recipe-face-blush-5-5g', 'Phấn má hồng bột siêu mịn kiềm dầu lên màu trong trẻo tự nhiên bám chặt trên da.', '3CE Mood Recipe Face Blush là dòng phấn má hồng trứ danh mang phong cách trang điểm Hàn Quốc tự nhiên trong trẻo. Các hạt phấn vi khoáng siêu mịn nhẹ nhàng tan vào da, hấp thụ lượng bã nhờn dư thừa trên gò má, mang lại đôi má ửng hồng tươi tắn mềm mịn như cánh hoa đào suốt cả ngày mà không bị bết phấn hay vón cục.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Talc, Mica (CI 77019), Titanium Dioxide (CI 77891), Octyldodecyl Stearoyl Stearate, Phenyl Trimethicone, Silica, Magnesium Myristate, Iron Oxides (CI 77491), Diisostearyl Malate, Dipentaerythrityl Hexahydroxystearate/Hexastearate/Hexarosinate, Caprylyl Glycol, Ethylhexylglycerin, Glyceryl Caprylate, Red 30 (CI 73360), Yellow 5 Lake (CI 19140), Triethoxycaprylylsilane, Water.', 'Dùng cọ má hồng lấy một lượng phấn vừa đủ, gõ nhẹ cán cọ để rơi bớt phấn thừa rồi xoay tròn nhẹ nhàng trên gò má.', 'Hàn Quốc', '5.5g', 1, 4.85, 36, 156, 26, 0, 0, 'Sebum-Controlling Micro Powders, Pure Pastel Pigments', NOW(), NOW()),
(227, 'Bút Kẻ Mắt Nước Nét Mảnh Không Trôi 3CE Easy Pen Eyeliner 1g', 'but-ke-mat-nuoc-net-manh-khong-troi-3ce-easy-pen-eyeliner-1g', 'Kẻ mắt nước đầu dạ nhọn mềm mại mực ra đều kháng nước và chống lem dầu mí mắt.', '3CE Easy Pen Eyeliner sở hữu đầu bút dạ sợi lông mềm mượt dễ điều khiển, thích hợp cho cả người mới tập kẻ mắt. Mực đen carbon đậm nét ra đều không bị đứt đoạn, khô nhanh sau vài giây tạo màng film kháng nước và dầu thừa trên mí mắt, giúp đường kẻ mắt sắc sảo bền đẹp suốt ngày dài.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Acrylates Copolymer, Carbon Black (CI 77266), Butylene Glycol, Alcohol, 1,2-Hexanediol, Laureth-21, PEG-40 Hydrogenated Castor Oil, Phenoxyethanol, Sodium Dehydroacetate, Disodium EDTA.', 'Lắc nhẹ bút trước khi dùng. Đặt bút sát mí mắt và vẽ từ đầu mắt ra đuôi mắt, kéo nhẹ phần đuôi mắt để tạo điểm nhấn.', 'Hàn Quốc', '1g', 1, 4.92, 37, 157, 26, 0, 0, 'Carbon Black Pigment, Waterproof Quick-dry Film', NOW(), NOW()),
(228, 'Bông Mút Trang Điểm Hai Đầu Đa Năng 3CE Dual Sponge', 'bong-mut-trang-diem-hai-dau-da-nang-3ce-dual-sponge', 'Mút trang điểm thiết kế vát góc 2 đầu giúp tán nền và phấn phủ mịn lì không vệt hằn.', '3CE Dual Sponge là bông mút trang điểm được yêu thích với chất liệu bọt xốp polyurethane mềm mại đàn hồi cao không chứa cao su tự nhiên. Mặt vát phẳng giúp dàn trải kem nền và cushion nhanh chóng trên diện tích rộng, phần đầu nhọn dễ dàng dặm kem che khuyết điểm vào góc mắt và hốc mũi, mang lại lớp nền căng mịn không tì vết.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrophilic Non-Latex Polyurethane Foam.', 'Làm ẩm mút trước khi dùng để tạo lớp nền căng bóng, hoặc dùng khô để có lớp nền lì che phủ cao. Dặm nhẹ nhàng khắp mặt.', 'Hàn Quốc', '1 miếng', 1, 4.85, 38, 158, 26, 0, 0, 'Latex-free Polyurethane Soft Foam', NOW(), NOW()),
(229, 'Cọ Phủ Phấn Lông Mềm Đa Năng 3CE Pink Kabuki Brush', 'co-phu-phan-long-mem-da-nang-3ce-pink-kabuki-brush', 'Cọ Kabuki nén tròn màu hồng lông sợi nhân tạo siêu mềm mịn phủ phấn và má hồng đều màu.', '3CE Pink Kabuki Brush sở hữu thiết kế tròn xoe nhỏ gọn màu hồng thời thượng. Các sợi lông cọ tổng hợp cao cấp mềm mại được bó tròn dày dặn, có khả năng lấy và nhả hạt phấn đồng đều, giúp phủ phấn nén, phấn bột hoặc tạo khối một cách nhẹ nhàng tự nhiên mà không gây rát da.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Synthetic Fiber Bristles, Aluminum Ferrule, Resin Handle.', 'Dùng cọ xoay tròn trong hũ phấn hoặc hộp má hồng, gõ nhẹ để rơi bớt phấn thừa rồi quét đều lên mặt theo hình xoắn ốc.', 'Hàn Quốc', '1 cây', 1, 4.92, 39, 159, 26, 0, 0, 'Premium Synthetic Bristles, Aluminum Ferrule', NOW(), NOW()),
(230, 'Chì Kẻ Mày Hai Đầu Định Hình Sợi Mày 3CE Easy Brow Designing Pencil 0.13g', 'chi-ke-may-hai-dau-dinh-hinh-soi-may-3ce-easy-brow-designing-pencil-0-13g', 'Chì kẻ mày đầu hình tam giác siêu mảnh định hình khung mày chuẩn nét và lâu trôi.', '3CE Easy Brow Designing Pencil được thiết kế đầu chì hình tam giác siêu mảnh giúp phẩy từng sợi lông mày tự nhiên như thật. Công thức chứa bột khoáng bám chặt vào da, chống thấm mồ hôi và bã nhờn, kèm theo đầu chải xoắn ốc mềm mại giúp tán đều màu chì cho hàng chân mày thanh tú hài hòa.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrogenated Soybean Oil, Hydrogenated Coco-Glycerides, Hydrogenated Vegetable Oil, Zinc Stearate, Stearic Acid, Copernicia Cerifera (Carnauba) Wax, Polyglyceryl-2 Triisostearate, Tocopherol, Caprylyl Glycol. [+/- CI 77499, CI 77491, CI 77492, Mica].', 'Dùng đầu cạnh chì phẩy sợi theo chiều lông mày mọc, sau đó dùng đầu chải chải xuôi theo dáng mày để màu chì tự nhiên.', 'Hàn Quốc', '0.13g', 1, 4.85, 40, 160, 26, 0, 0, 'Hard Formula Wax, Natural Pigments', NOW(), NOW()),
(231, 'Son Tint Bóng Căng Mọng Môi Rom&nd Juicy Lasting Tint 5.5g', 'son-tint-bong-cang-mong-moi-rom-nd-juicy-lasting-tint-5-5g', 'Son tint bóng chiết xuất trái cây tạo hiệu ứng môi kẹo hồ lô ngọt ngào giữ màu bền bỉ.', 'Rom&nd Juicy Lasting Tint là dòng son tint bóng biểu tượng làm nên cơn sốt bờ môi căng mọng như kẹo ngọt khắp Châu Á. Lớp bóng trong trẻo như gương phủ lên môi kết hợp lớp tint màu bám chặt vào môi, không gây cảm giác dính dớp, nuôi dưỡng bờ môi luôn mềm mại đầy đặn suốt cả ngày dài năng động.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Octyldodecanol, Dimethicone, Alcohol Denat., Acrylates Copolymer, Sorbitan Stearate, Ethylcellulose, Behenyl Alcohol, Pentylene Glycol, Actinidia Chinensis (Kiwi) Fruit Extract, Carica Papaya (Papaya) Fruit Extract, Citrus Paradisi (Grapefruit) Fruit Extract, Cocos Nucifera (Coconut) Fruit Extract, Mangifera Indica (Mango) Fruit Extract, Psidium Guajava Fruit Extract, Polysorbate 60, Silica, Polyglyceryl-2 Triisostearate, Fragrance(Parfum). [+/- CI 77891, CI 77491, CI 15850, CI 15985, CI 17200].', 'Thoa một lớp son vào lòng môi rồi tán nhẹ ra khóe môi. Để yên trong 30 giây để lớp bóng tự động nổi lên căng mọng mà không bặm môi.', 'Hàn Quốc', '5.5g', 1, 4.92, 41, 161, 27, 1, 0, 'Fruit Extracts (Kiwi, Papaya, Grapefruit, Coconut), Glossy Polymers', NOW(), NOW()),
(232, 'Chì Kẻ Mày Hai Đầu Dạng Dẹp Rom&nd Han All Flat Brow 0.17g', 'chi-ke-may-hai-dau-dang-dep-rom-nd-han-all-flat-brow-0-17g', 'Chì kẻ mày đầu dẹp phẳng chống vón cục giúp định hình sợi mày tự nhiên bám chặt suốt cả ngày.', 'Rom&nd Han All Flat Brow sở hữu đầu chì dạng dẹp mỏng phẳng cho phép bạn vẽ từng sợi lông mày tinh tế hoặc tô khuôn mày sắc nét mà không lo bị lem hay bết dính vón cục ngay cả khi kẻ chồng nhiều lớp. Lớp phủ bột khoáng kiềm dầu mồ hôi giúp giữ màu chân mày bền đẹp không phai suốt cả ngày dài năng động.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrogenated Soybean Oil, Hydrogenated Coco-Glycerides, Iron Oxides (CI 77499), Hydrogenated Vegetable Oil, Zinc Stearate, Stearic Acid, Copernicia Cerifera (Carnauba) Wax, Iron Oxides (CI 77492), Polyglyceryl-2 Triisostearate, Iron Oxides (CI 77491), Tocopherol, Caprylyl Glycol, Phenoxyethanol, Ascorbyl Palmitate.', 'Dùng góc cạnh mỏng của đầu chì để kẻ sợi mày ở phần đầu chân mày. Dùng mặt phẳng để tán màu ở phần thân và đuôi mày. Dùng đầu cọ chải xoắn chải nhẹ cho màu sắc hài hòa.', 'Hàn Quốc', '0.17g', 1, 4.85, 42, 162, 27, 0, 0, 'Coated Mineral Pigments, Long-lasting Wax Matrix, Flat Blade Shape', NOW(), NOW()),
(233, 'Phấn Má Hồng Tông Trái Cây Tự Nhiên Rom&nd Better Than Cheek 4g', 'phan-ma-hong-tong-trai-cay-tu-nhien-rom-nd-better-than-cheek-4g', 'Phấn má hồng công nghệ làm mờ lỗ chân lông Blur Effect cho đôi gò má trong trẻo tự nhiên.', 'Rom&nd Better Than Cheek lấy cảm hứng từ màu sắc tinh khiết của các loại trái cây sấy khô tự nhiên. Hạt phấn siêu mịn kết hợp hiệu ứng Blur làm mờ các khuyết điểm lỗ chân lông to trên gò má, mang lại lớp phấn má mịn màng tự nhiên như làn da mộc mà không bị bột hay bay màu nhanh.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Talc, Mica (CI 77019), Silica, Octyldodecyl Stearoyl Stearate, Phenyl Trimethicone, Dimethicone, Magnesium Myristate, Magnesium Stearate, Methylpropanediol, Propanediol, Triethoxycaprylylsilane, Water. [+/- CI 77891, CI 77491, CI 77492, CI 77499, CI 73360].', 'Dùng cọ má quét nhẹ lấy phấn, dặm nhẹ lên gò má từ trong ra ngoài thái dương để khuôn mặt thêm rạng rỡ.', 'Hàn Quốc', '4g', 1, 4.92, 43, 163, 27, 0, 0, 'Silicone-coated Powders, Dried Fruit Pigments', NOW(), NOW()),
(234, 'Bộ Bông Phấn Nước Cushion Thay Thế Rom&nd Zero Cushion Puff Set 2 miếng', 'bo-bong-phan-nuoc-cushion-thay-the-rom-nd-zero-cushion-puff-set-2-mieng', 'Bông phấn cushion chuyên dụng chất liệu Rubycell đàn hồi cao giúp lớp nền tệp da mỏng nhẹ.', 'Rom&nd Zero Cushion Puff Set gồm 2 bông phấn nước thay thế chất liệu mút Rubycell cao cấp với các lỗ khí siêu vi mô. Bông phấn giúp lấy một lượng kem nền cushion vừa đủ, dàn trải đều lên da mà không hút hao kem, mang lại lớp nền căng mịn tự nhiên không tì vết.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Polyurethane Rubycell Foam, Ribbon Band.', 'Dùng bông phấn ấn nhẹ vào lõi cushion và dặm đều khắp khuôn mặt. Nên giặt sạch bông phấn định kỳ hàng tuần.', 'Hàn Quốc', '2 miếng', 1, 4.85, 44, 164, 27, 0, 0, 'Premium Rubycell Micro-cell Material', NOW(), NOW()),
(235, 'Cọ Tán Phấn Mắt Chuyên Nghiệp Hai Đầu Rom&nd Easy Eye Brush', 'co-tan-phan-mat-chuyen-nghiep-hai-dau-rom-nd-easy-eye-brush', 'Cọ trang điểm mắt hai đầu lông mềm mại giúp tán màu mắt và kẻ đường viền mí dễ dàng.', 'Rom&nd Easy Eye Brush là cọ tán mắt 2 đầu tiện lợi gồm một đầu cọ dẹp để phủ phấn nền bầu mắt và một đầu cọ vát xéo bo tròn để tán hốc mắt và nhấn mí. Đầu lông sợi tổng hợp mềm mại không gây ngứa hay châm chích mí mắt, giúp phấn mắt lên màu chuẩn sắc và chuyển màu tự nhiên.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'High-grade Synthetic Bristles, Aluminum Ferrule, Resin Body.', 'Dùng đầu cọ dẹp tán màu mắt nhạt lên toàn bộ bầu mắt, dùng đầu cọ vát để nhấn màu đậm vào đuôi mắt và viền mí.', 'Hàn Quốc', '1 cây', 1, 4.92, 45, 165, 27, 0, 0, 'Ultra-soft Synthetic Bristles, Double-ended Design', NOW(), NOW()),
(236, 'Son Kem Lì Lâu Trôi Peripera Ink The Velvet Lip Tint 4g', 'son-kem-li-lau-troi-peripera-ink-the-velvet-lip-tint-4g', 'Son kem lì hình bình mực quốc dân chất kem xốp mịn giữ màu bền bỉ suốt 8 giờ không khô môi.', 'Peripera Ink The Velvet là dòng son kem lì hình bình mực nổi tiếng của thương hiệu Peripera Hàn Quốc. Kết cấu chất son dạng whipped kem xốp mượt mà lướt êm ái trên bờ môi, làm mờ các nếp nhăn môi và lưu giữ lớp màu tint rực rỡ suốt cả ngày ngay cả sau khi ăn uống nhờ công nghệ khóa màu Ink Long-lasting.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Dimethicone, Dimethicone/Vinyl Dimethicone Crosspolymer, Water, Polyglyceryl-2 Triisostearate, Cetyl PEG/PPG-10/1 Dimethicone, Isododecane, Butylene Glycol, Titanium Dioxide (CI 77891), Iron Oxides (CI 77491), Red 7 Lake (CI 15850), Yellow 6 Lake (CI 15985), 1,2-Hexanediol, Fragrance, Phenoxyethanol, Silica Dimethyl Silylate, Diisostearyl Malate, Ethylhexylglycerin.', 'Thoa một lớp son mỏng vào lòng môi và bặm nhẹ để tạo hiệu ứng lòng môi tươi tắn, hoặc thoa đều khắp môi để có bờ môi đậm màu quyến rũ.', 'Hàn Quốc', '4g', 1, 4.85, 46, 166, 28, 1, 0, 'Ink Long-lasting Formula, Jojoba Oil, Hyaluronic Acid, Marine Collagen', NOW(), NOW()),
(237, 'Phấn Má Hồng Nắng Trong Trẻo Peripera Pure Blushed Sunshine Cheek 4.2g', 'phan-ma-hong-nang-trong-treo-peripera-pure-blushed-sunshine-cheek-4-2g', 'Phấn má hồng ánh nắng pastel mịn màng kiểm soát bã nhờn cho đôi má tươi tắn cả ngày.', 'Peripera Pure Blushed Sunshine Cheek mang lại sắc màu má hồng trong trẻo ấm áp như ánh nắng sớm mai. Hạt phấn nhỏ li ti hấp thu bã nhờn bề mặt da, giúp màu phấn bám dai dẳng trên gò má mà không bị bay màu hay vón cục, tạo nên diện mạo đáng yêu trẻ trung chuẩn học đường Hàn Quốc.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Talc, Mica, Methyl Methacrylate Crosspolymer, Diisostearyl Malate, Octyldodecyl Stearoyl Stearate, Caprylic/Capric Triglyceride, Dimethicone, Magnesium Myristate, Titanium Dioxide (CI 77891), 1,2-Hexanediol, Silica, Triethoxycaprylylsilane, Glyceryl Caprylate, Iron Oxides (CI 77491), Red 30 (CI 73360), Yellow 5 Lake (CI 19140).', 'Dùng cọ má lấy một lượng phấn vừa đủ và tán nhẹ nhàng lên đỉnh gò má theo hình tròn hoặc xéo nhẹ lên thái dương.', 'Hàn Quốc', '4.2g', 1, 4.92, 47, 167, 28, 0, 0, 'Sebum Clear Powder, Pastel Pigments', NOW(), NOW()),
(238, 'Chì Kẻ Mày Siêu Mảnh Phẩy Sợi Peripera Speedy Skinny Brow 0.05g', 'chi-ke-may-sieu-manh-phay-soi-peripera-speedy-skinny-brow-0-05g', 'Chì kẻ mày đầu tròn siêu vi 1.5mm phẩy từng sợi chân mày tự nhiên lâu trôi không thấm nước.', 'Peripera Speedy Skinny Brow sở hữu đầu chì kẻ mày siêu vi điểm chỉ 1.5mm giúp vẽ từng sợi lông mày mảnh mai tự nhiên như xăm điêu khắc. Chất chì cứng vừa phải không bị gãy vụn, lên màu chuẩn và kháng nước, kháng mồ hôi tối ưu, đem lại hàng lông mày sắc nét thanh tú.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrogenated Soybean Oil, Hydrogenated Coco-Glycerides, Zinc Stearate, Hydrogenated Vegetable Oil, Copernicia Cerifera (Carnauba) Wax, Mica, Tocopherol. [+/- CI 77499, CI 77491, CI 77492].', 'Vặn đầu chì lên khoảng 1mm, phẩy nhẹ từng sợi lông mày vào các khoảng trống của chân mày rồi dùng đầu chải chải đều.', 'Hàn Quốc', '0.05g', 1, 4.85, 48, 168, 28, 0, 0, '1.5mm Ultra-slim Tip, Waterproof Hard Formula', NOW(), NOW()),
(239, 'Bút Kẻ Mắt Nước Nét Siêu Mảnh Peripera Speedy Skinny Eyeliner 0.06g', 'but-ke-mat-nuoc-net-sieu-manh-peripera-speedy-skinny-eyeliner-0-06g', 'Bút kẻ mắt nước đầu cọ vi điểm siêu mảnh chống trôi kháng dầu cho đường viền mí sắc sảo.', 'Peripera Speedy Skinny Eyeliner có đầu cọ kẻ mắt siêu mảnh giúp thao tác kẻ viền mí trong và đuôi mắt mảnh mai trở nên cực kỳ dễ dàng. Công thức gel chống thấm nước cải tiến bám chặt vào mí mắt, không lem trôi khi da đổ mồ hôi hoặc tiết dầu suốt cả ngày dài.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Acrylates Copolymer, Iron Oxides (CI 77499), Butylene Glycol, Alcohol, 1,2-Hexanediol, Phenoxyethanol, Sodium Polyacrylate, Steareth-20, Disodium EDTA.', 'Vẽ đường kẻ mắt mảnh sát chân mí từ đầu mắt đến đuôi mắt, hơi hất nhẹ ở đuôi mắt để tạo độ mở cho mắt.', 'Hàn Quốc', '0.06g', 1, 4.92, 49, 169, 28, 0, 0, 'Ultra-slim Pen Tip, Waterproof Polymer', NOW(), NOW()),
(240, 'Mascara Làm Cong Và Dày Mi Chống Thấm Nước Peripera Ink Black Cara 8g', 'mascara-lam-cong-va-day-mi-chong-tham-nuoc-peripera-ink-black-cara-8g', 'Mascara giữ nếp mi cong suốt cả ngày không sụp mi chống trôi nước và mồ hôi tuyệt đối.', 'Peripera Ink Black Cara là sản phẩm chuốt mi giữ nếp cong số 1 Hàn Quốc nhờ công nghệ khóa nếp mi Strong-curl Fixer. Công thức kháng nước tuyệt đối không lem nhòe ngay cả khi đi bơi hay khóc, đầu cọ uốn lượn ôm trọn bờ mi giúp làm dày mi tơi từng sợi mà không gây nặng mí.', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Isododecane, Trimethylsiloxysilicate, Talc, Ceresin, Dextrin Palmitate, Microcrystalline Wax, Disteardimonium Hectorite, Iron Oxides (CI 77499), Polypropylsilsesquioxane, Propylene Carbonate, Silica, Dextrin Palmitate/Ethylhexanoate, Hydrogenated Polyisobutene, Triethoxycaprylylsilane, Glyceryl Caprylate.', 'Bấm mi kỹ trước khi chuốt. Đặt đầu cọ ở gốc mi và chuốt nhẹ ziczac lên ngọn mi. Chuốt lại lớp thứ hai để mi dày tối đa.', 'Hàn Quốc', '8g', 1, 4.85, 50, 50, 28, 0, 0, 'Strong-curl Fixer, Waterproof Ink Formula, Cellulose Fibers', NOW(), NOW()),
(241, 'Sáp Tẩy Trang Làm Sạch Sâu Dưỡng Ẩm Banila Co Clean It Zero Cleansing Balm Original 100ml', 'sap-tay-trang-lam-sach-sau-duong-am-banila-co-clean-it-zero-cleansing-balm-original-100ml', 'Sáp tẩy trang số 1 Hàn Quốc công nghệ Zero Balance tan chảy nhẹ nhàng cuốn sạch cặn trang điểm chống nước.', 'Banila Co Clean It Zero Cleansing Balm Original cứ mỗi 3.1 giây lại có một hũ được bán ra trên thế giới. Công nghệ độc quyền Zero Balance Technology kết hợp chiết xuất quả sơ ri Acerola giàu Vitamin C và nước suối nóng Onsen làm tan chảy mọi lớp trang điểm dày, son lì và mascara kháng nước trong tích tắc mà không làm cay mắt hay nhờn rít da sau khi rửa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Ethylhexyl Palmitate, Cetyl Ethylhexanoate, PEG-20 Glyceryl Triisostearate, PEG-10 Isostearate, Synthetic Wax, Onsen-Sui, Phenoxyethanol, Butylene Glycol, Lithospermum Erythrorhizon Root Extract, Tocopheryl Acetate, Fragrance, Ethylhexylglycerin, Water, 1,2-Hexanediol, Bambusa Vulgaris Leaf/Stem Extract, Aspalathus Linearis Extract, Angelica Archangelica Root Extract, Malpighia Glabra (Acerola) Fruit Extract.', 'Dùng thìa gạt lấy lượng sáp vừa đủ chấm lên trán, má, cằm và mắt khô. Massage nhẹ nhàng cho sáp tan chảy thành dầu hòa tan trang điểm. Thêm một chút nước ấm để nhũ hóa rồi rửa sạch lại với nước.', 'Hàn Quốc', '100ml', 1, 4.92, 51, 51, 29, 1, 0, 'Zero Balance Technology, Acerola Fruit Extract, Rooibos Extract, Vitamin C', NOW(), NOW()),
(242, 'Bông Mút Trang Điểm Đa Năng Mềm Mịn Banila Co Covericious Ultimate Blending Sponge', 'bong-mut-trang-diem-da-nang-mem-min-banila-co-covericious-ultimate-blending-sponge', 'Bông mút trang điểm hình giọt nước vát phẳng chất liệu bọt biển siêu mềm tăng độ che phủ nền hoàn hảo.', 'Banila Co Covericious Ultimate Blending Sponge được thiết kế công thái học với 3 mặt tiện dụng: mặt vát phẳng để dặm phấn nền vùng má và trán, đầu nhọn để len lỏi vùng khóe mắt và cánh mũi, đáy tròn để tán đều toàn bộ khuôn mặt. Khi thấm nước, mút nở to gấp 1.5 lần, trở nên mềm mại như kẹo dẻo mallow, giúp lớp kem nền bám chặt vào da, không hút hao kem và tạo hiệu ứng căng mướt phủ sương chuẩn Hàn.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Hydrophilic Non-Latex Polyurethane Sponge.', 'Làm ẩm bông mút bằng nước sạch rồi vắt ráo hoàn toàn bằng khăn sạch. Lấy kem nền hoặc cushion chấm lên mặt, dùng mặt vát bông mút dặm đều từ trong ra ngoài.', 'Hàn Quốc', '1 cái', 1, 4.85, 52, 52, 29, 0, 0, 'Latex-free Polyurethane Foam, Hydrophilic Water-expandable Texture', NOW(), NOW()),
(243, 'Kem Lót Kiềm Dầu Che Khuyết Lỗ Chân Lông Banila Co Prime Primer Classic 30ml', 'kem-lot-kiem-dau-che-khuyet-lo-chan-long-banila-co-prime-primer-classic-30ml', 'Kem lót che phủ lỗ chân lông số 1 Hàn Quốc kiểm soát bã nhờn cho lớp trang điểm mịn lì suốt ngày.', 'Banila Co Prime Primer Classic là bí quyết đằng sau lớp nền mịn màng không tì vết của các chuyên gia trang điểm Hàn Quốc. Kết cấu dạng gel trong suốt lấp đầy các lỗ chân lông to và rãnh nhăn nông, kiềm dầu và chống oxy hóa giúp lớp kem nền bám chắc bền màu suốt cả ngày mà không bị đổ dầu xỉn màu.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Cyclopentasiloxane, Dimethicone, Dimethicone/Vinyl Dimethicone Crosspolymer, Water, Silica, Isododecane, Dimethicone Crosspolymer, Polymethylsilsesquioxane, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Butylene Glycol, PEG-10 Dimethicone, Titanium Dioxide, Disteardimonium Hectorite, Phenoxyethanol, Ethylhexylglycerin.', 'Sau bước dưỡng ẩm và kem chống nắng, lấy lượng kem lót nhỏ bằng hạt đậu thoa tập trung vào vùng chữ T, hai bên cánh mũi và vùng có lỗ chân lông to trước khi đánh kem nền.', 'Hàn Quốc', '30ml', 1, 4.92, 53, 53, 29, 0, 0, 'Pore-minimizing Polymer, Sebum-control Complex', NOW(), NOW()),
(244, 'Phấn Phủ Bột Kiềm Dầu Siêu Mịn Banila Co Prime Primer Finish Powder 12g', 'phan-phu-bot-kiem-dau-sieu-min-banila-co-prime-primer-finish-powder-12g', 'Phấn phủ bột khoáng trong suốt kiềm dầu mạnh mẽ làm mờ lỗ chân lông và khóa nền lâu trôi.', 'Banila Co Prime Primer Finish Powder chứa các hạt vi bột khoáng tinh thể siêu nhỏ có khả năng hấp thụ bã nhờn dư thừa tức thì, mang lại hiệu ứng làn da mịn lì như phủ sương nhung. Không làm đổi màu lớp nền, không gây bốc mốc và giữ cho khuôn mặt khô thoáng rạng rỡ suốt 12 giờ.', 'https://images.unsplash.com/photo-1512290900672-1f55a1d798a7?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'OILY', 'Silica, Dimethicone, Macadamia Ternifolia Seed Oil, Dimethicone/Vinyl Dimethicone Crosspolymer, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Caprylyl Glycol, Ethylhexylglycerin, Water, Tocopherol.', 'Dùng bông phấn đi kèm dặm nhẹ bột phấn lên toàn bộ khuôn mặt, đặc biệt là vùng chữ T và hai bên cánh mũi sau khi hoàn tất lớp nền.', 'Hàn Quốc', '12g', 1, 4.85, 54, 54, 29, 0, 0, 'Micro-fine Mineral Powder, Sebum Clear Complex', NOW(), NOW()),
(245, 'Mặt Nạ Đất Sét Thanh Lọc Lỗ Chân Lông Banila Co Clean It Zero Pore Clarifying Clay Mask 100ml', 'mat-na-dat-set-thanh-loc-lo-chan-long-banila-co-clean-it-zero-pore-clarifying-clay-mask-100ml', 'Mặt nạ đất sét Pháp và dầu tràm trà thanh lọc bã nhờn se khít lỗ chân lông không gây khô căng.', 'Banila Co Clean It Zero Pore Clarifying Clay Mask kết hợp đất sét cao lanh Kaolin và đất sét Montmorillonite từ Pháp giàu khoáng chất hút sạch dầu thừa, bụi bẩn sâu trong nang lông. Bổ sung tinh dầu tràm trà và Acid Salicylic giúp kháng viêm mụn, giảm sợi bã nhờn mà vẫn duy trì độ mềm mại không làm căng rát da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Kaolin, Butylene Glycol, Bentonite, Glycerin, Titanium Dioxide, Melaleuca Alternifolia (Tea Tree) Leaf Water, Salicylic Acid, 1,2-Hexanediol, Hydroxyacetophenone, Xanthan Gum, Ethylhexylglycerin, Disodium EDTA, Melaleuca Alternifolia (Tea Tree) Leaf Oil.', 'Sau khi làm sạch mặt, thoa một lớp đều khắp mặt (tránh vùng mắt môi). Thư giãn trong 10-15 phút rồi rửa sạch lại bằng nước ấm. Dùng 1-2 lần mỗi tuần.', 'Hàn Quốc', '100ml', 1, 4.92, 20, 55, 29, 1, 0, 'French Clay, Tea Tree Leaf Oil, Kaolin, Salicylic Acid', NOW(), NOW()),
(246, 'Kem Dưỡng Làm Dịu Da Dầu Mụn Nhạy Cảm Dr.G R.E.D Blemish Clear Soothing Cream 70ml', 'kem-duong-lam-diu-da-dau-mun-nhay-cam-dr-g-r-e-d-blemish-clear-soothing-cream-70ml', 'Kem dưỡng dạng gel chứa phức hợp 10-Cica rau má làm dịu tức thì mẩn đỏ và phục hồi hàng rào ẩm 100H.', 'Dr.G R.E.D Blemish Clear Soothing Cream là dòng kem dưỡng bán chạy số 1 tại chuỗi Olive Young Hàn Quốc được các bác sĩ da liễu khuyên dùng. Công thức nâng cấp chứa phức hợp 10-Cica chiết xuất từ rau má tươi kết hợp men vi sinh sinh học Ectoin và Panthenol giúp hạ nhiệt làn da đỏ rát sau 2 phút, cấp nước sâu 100 giờ không gây nhờn dính hay bí da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'COMBINATION', 'Water, Glycerin, Butylene Glycol, C13-16 Isoparaffin, Niacinamide, C12-14 Pareth-12, Dimethicone, 1,2-Hexanediol, Hydrogenated Polydecene, Pentylene Glycol, Vinyl Dimethicone, Caprylyl Methicone, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Panthenol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Dimethiconol, Polymethylsilsesquioxane, Chlorella Vulgaris Extract, Glucose, Tromethamine, Fructooligosaccharides, Fructose, Glyceryl Acrylate/Acrylic Acid Copolymer, Xanthan Gum, Ethylhexylglycerin, Dipotassium Glycyrrhizate, Sodium Phytate, Centella Asiatica Extract, Madecassoside, Asiaticoside, Madecassic Acid, Asiatic Acid, Ectoin, Tocopherol.', 'Thoa một lượng kem vừa đủ lên toàn bộ khuôn mặt vào mỗi buổi sáng và tối sau bước serum, mát xa nhẹ nhàng cho kem thẩm thấu hết.', 'Hàn Quốc', '70ml', 1, 4.85, 21, 56, 30, 0, 0, '10-Cica Complex, Ectoin, Panthenol, Niacinamide, Beta-Glucan', NOW(), NOW()),
(247, 'Sữa Rửa Mặt Dịu Nhẹ pH Chuẩn Dr.G R.E.D Blemish Clear Soothing Foam 150ml', 'sua-rua-mat-diu-nhe-ph-chuan-dr-g-r-e-d-blemish-clear-soothing-foam-150ml', 'Bọt rửa mặt chứa 5-Cica và Salicylic Acid làm sạch mụn dịu nhẹ không phá hủy màng ẩm tự nhiên.', 'Dr.G R.E.D Blemish Clear Soothing Foam là sữa rửa mặt dịu nhẹ chuẩn da liễu với độ pH sinh lý 5.5. Bổ sung phức hợp 5 loại chiết xuất rau má Cica và BHA tự nhiên từ vỏ cây liễu, sản phẩm làm sạch sâu bã nhờn và vi khuẩn gây mụn mà không gây cảm giác căng rát khó chịu sau khi rửa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Sodium Cocoyl Isethionate, Glycerin, Sodium Methyl Cocoyl Taurate, Potassium Cocoyl Glycinate, 1,2-Hexanediol, Potassium Cocoate, Centella Asiatica Extract, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid, Salicylic Acid, Panthenol, Betaine, Butylene Glycol, Dipropylene Glycol, Hydroxypropyl Starch Phosphate, Polyquaternium-67, Ethylhexylglycerin, Disodium EDTA.', 'Lấy một lượng nhỏ ra lòng bàn tay ướt, tạo bọt dày rồi mát xa nhẹ nhàng khắp mặt trong 60 giây. Rửa sạch lại bằng nước mát.', 'Hàn Quốc', '150ml', 1, 4.92, 22, 57, 30, 0, 0, '5-Cica Complex, Salicylic Acid (BHA), Panthenol, pH 5.5', NOW(), NOW()),
(248, 'Kem Chống Nắng Vật Lý Dịu Nhẹ Cho Da Nhạy Cảm Dr.G Green Mild Up Sun+ SPF50+ 50ml', 'kem-chong-nang-vat-ly-diu-nhe-cho-da-nhay-cam-dr-g-green-mild-up-sun-spf50-50ml', 'Kem chống nắng vật lý 100% Zinc Oxide bảo vệ da trước tia UV, ánh sáng xanh và bụi mịn PM2.5.', 'Dr.G Green Mild Up Sun+ SPF50+ PA++++ là kem chống nắng thuần vật lý với màng lọc 100% Zinc Oxide an toàn tuyệt đối cho làn da nhạy cảm nhất. Công thức bổ sung chiết xuất mầm non hạt cải Pháp và hoa hòe giúp bảo vệ da 5 lớp trước tia UVA, UVB, ánh sáng xanh, tia hồng ngoại và bụi mịn ô nhiễm mà không gây vệt trắng bết dính.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Water, Zinc Oxide, Propanediol, Butyloctyl Salicylate, Propylheptyl Caprylate, Coco-Caprylate/Caprate, Cyclohexasiloxane, Caprylyl Methicone, Isododecane, Polyglyceryl-3 Polydimethylsiloxyethyl Dimethicone, Methyl Trimethicone, Methyl Methacrylate Crosspolymer, Disteardimonium Hectorite, Magnesium Sulfate, Triethoxycaprylylsilane, 1,2-Hexanediol, Polyglyceryl-2 Dipolyhydroxystearate, Polymethylsilsesquioxane, Lauryl Polyglyceryl-3 Polydimethylsiloxyethyl Dimethicone, Glyceryl Caprylate, Caprylyl Glycol, Ethylhexylglycerin, Sodium Hyaluronate, Butylene Glycol, Tocopherol, Pinus Pinaster Bark Extract (Pycnogenol).', 'Thoa đều khắp mặt và cổ ở bước cuối cùng của chu trình dưỡng da buổi sáng trước khi ra ngoài 20 phút. Thoa lại sau 2-3 giờ khi vận động nhiều.', 'Hàn Quốc', '50ml', 1, 4.85, 23, 58, 30, 0, 0, '100% Zinc Oxide Mineral Filter, Pycnogenol, Ectoin, Houttuynia Cordata', NOW(), NOW()),
(249, 'Tẩy Tế Bào Chết Dạng Kỳ Dịu Nhẹ Làm Sáng Da Dr.G Brightening Peeling Gel 120g', 'tay-te-bao-chet-dang-ky-diu-nhe-lam-sang-da-dr-g-brightening-peeling-gel-120g', 'Gel tẩy da chết dạng gommage chứa cellulose tự nhiên và Vitamin C làm sáng da không gây tổn thương.', 'Dr.G Brightening Peeling Gel là sản phẩm tẩy tế bào chết dạng kỳ được bán chạy số 1 tại Hàn Quốc. Sợi cellulose tự nhiên kết hợp cùng chiết xuất ngọc trai và Vitamin C nhẹ nhàng vón cục cuốn trôi tế bào chết xỉn màu và bụi bẩn khi mát xa trên da ẩm, mang lại làn da trắng mịn màng rạng rỡ mà không gây trầy xước biểu bì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Cellulose, Dipropylene Glycol, Glyceryl Caprylate, Propanediol, Caprylyl Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Allantoin, Disodium EDTA, Butylene Glycol, Ascorbyl Glucoside, Salix Nigra (Willow) Bark Extract, Tremella Fuciformis (Mushroom) Extract, Diospyros Kaki Leaf Extract, Vitis Vinifera (Grape) Fruit Extract, Carthamus Tinctorius (Safflower) Flower Extract, Coffea Arabica (Coffee) Seed Extract, Polygonum Cuspidatum Root Extract, Camellia Sinensis Leaf Extract, Castanea Crenata (Chestnut) Shell Extract, Zanthoxylum Piperitum Fruit Extract.', 'Sau khi rửa mặt, khi da còn hơi ẩm, lấy một lượng gel vừa đủ thoa đều khắp mặt (tránh mắt và môi). Mát xa nhẹ nhàng theo chuyển động tròn trong 1-2 phút cho đến khi các vụn gôm xuất hiện, sau đó rửa sạch lại với nước ấm. Dùng 1-2 lần/tuần.', 'Hàn Quốc', '120g', 1, 4.92, 24, 59, 30, 0, 0, 'Natural Cellulose, Vitamin C (Ascorbyl Glucoside), Black Willow Bark', NOW(), NOW()),
(250, 'Nước Xịt Khoáng Làm Dịu Da Mụn Kích Ứng Dr.G R.E.D Blemish Soothing Mist 100ml', 'nuoc-xit-khoang-lam-diu-da-mun-kich-ung-dr-g-r-e-d-blemish-soothing-mist-100ml', 'Xịt khoáng làm dịu da chứa phức hợp 5-Cica và phân tử cấp ẩm siêu nhỏ hạ nhiệt da mẩn đỏ tức thì.', 'Dr.G R.E.D Blemish Soothing Mist là cứu tinh hạ nhiệt cấp tốc cho làn da dầu mụn dễ kích ứng. Tia xịt phun sương siêu mịn bao bọc lấy làn da, đưa phức hợp 5-Cica rau má tươi và chiết xuất rau sam thẩm thấu sâu, làm dịu tức thì các vết đỏ rát do cháy nắng, ô nhiễm hay kích ứng mỹ phẩm, mang lại cảm giác tươi mát sảng khoái suốt ngày dài.', 'https://images.unsplash.com/photo-1617897903246-719242758050?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Butylene Glycol, Dipropylene Glycol, 1,2-Hexanediol, Glycerin, Centella Asiatica Extract, Portulaca Oleracea Extract, Madecassoside, Asiaticoside, Madecassic Acid, Asiatic Acid, Panthenol, Betaine, Disodium EDTA, Sodium Citrate, Citric Acid, Ethylhexylglycerin.', 'Để bình xịt cách mặt khoảng 20cm, nhắm mắt và xịt đều khắp mặt bất cứ khi nào da có cảm giác khô căng hoặc nóng rát. Vỗ nhẹ cho dưỡng chất thẩm thấu.', 'Hàn Quốc', '100ml', 1, 4.85, 25, 60, 30, 0, 0, '5-Cica Complex, Portulaca Oleracea Extract, Panthenol', NOW(), NOW()),
(251, 'Tinh Chất Tái Sinh Năng Lượng Đỉnh Cao OHUI The First Geniture Genummune Ampoule 40ml', 'tinh-chat-tai-sinh-nang-luong-dinh-cao-ohui-the-first-geniture-genummune-ampoule-40ml', 'Ampoule chống oxy hóa mạnh mẽ chứa 8.0% phức hợp Vitamin và công nghệ Signature 29 Cell tái sinh tế bào.', 'OHUI The First Geniture Genummune Ampoule là tuyệt phẩm dưỡng da hoàng gia cao cấp nhất từ tập đoàn LG Household & Health Care. Ứng dụng công nghệ nuôi cấy tế bào mầm Signature 29 Cell độc quyền kết hợp 8.0% phức hợp chống oxy hóa thế hệ mới (Vitamin C, Vitamin B5, Vitamin E), tinh chất giúp củng cố hàng rào miễn dịch sinh học của làn da, đẩy lùi các dấu hiệu lão hóa và đánh thức sức sống thanh xuân rạng rỡ.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Dipropylene Glycol, Ascorbic Acid (Vitamin C), Propanediol, Glycerin, Panthenol (Vitamin B5), Tromethamine, Tocopherol (Vitamin E), Ferulic Acid, 1,2-Hexanediol, Paeonol, Sodium Hyaluronate, Carnosine, Oligopeptide-1, Oligopeptide-2, Oligopeptide-3, Oligopeptide-6, Hydrogenated Lecithin, Butylene Glycol, Caprylyl Glycol, Glyceryl Acrylate/Acrylic Acid Copolymer, Adenosine, Disodium EDTA, Parfum/Fragrance.', 'Sau bước nước cân bằng, lấy 2-3 giọt ampoule thoa đều khắp mặt và cổ. Nhẹ nhàng áp lòng bàn tay ấm lên mặt để kích hoạt dưỡng chất thẩm thấu sâu.', 'Hàn Quốc', '40ml', 1, 4.92, 26, 61, 31, 1, 0, 'Signature 29 Cell, 8% Vitamin Complex, Ferulic Acid, Paeonol', NOW(), NOW()),
(252, 'Kem Dưỡng Tái Sinh Tế Bào Da Trẻ Hóa OHUI The First Geniture Cream Intensive 55ml', 'kem-duong-tai-sinh-te-bao-da-tre-hoa-ohui-the-first-geniture-cream-intensive-55ml', 'Kem dưỡng cao cấp cô đặc dưỡng chất tế bào mầm nuôi dưỡng làn da căng tràn sức sống và săn chắc.', 'OHUI The First Geniture Cream Intensive được ví như nguồn năng lượng tái sinh kỳ diệu cho làn da lão hóa chùng nhão. Kết cấu kem sánh mịn giàu dưỡng chất thẩm thấu sâu như tan chảy vào từng tế bào da, cung cấp nguồn dinh dưỡng dồi dào từ tinh chất hoa mẫu đơn trắng Paeonol quý hiếm và công nghệ tế bào gốc, giúp phục hồi độ đàn hồi, làm mờ các nếp nhăn sâu và nuôi dưỡng da săn chắc.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'DRY', 'Water, Glycerin, Dipropylene Glycol, Caprylic/Capric Triglyceride, Hydrogenated Polyisobutene, Hydrogenated Polydecene, Butylene Glycol, Cyclopentasiloxane, Cetearyl Alcohol, Butyrospermum Parkii (Shea) Butter, 1,2-Hexanediol, Macadamia Ternifolia Seed Oil, Glyceryl Stearate, Paeonol, Oligopeptide-1, Oligopeptide-2, Oligopeptide-3, Dimethicone, Squalane, PEG-100 Stearate, Cera Alba, Carbomer, Tromethamine, Adenosine, Disodium EDTA, Parfum/Fragrance.', 'Lấy lượng kem cỡ hạt ngọc trai thoa đều lên toàn bộ khuôn mặt và cổ ở bước cuối cùng của chu trình dưỡng da ban đêm. Mát xa nhẹ nhàng theo chiều nâng cơ.', 'Hàn Quốc', '55ml', 1, 4.85, 27, 62, 31, 1, 0, 'Signature 29 Cell, Paeonol Peony Extract, Squalane, Peptides', NOW(), NOW()),
(253, 'Nước Hoa Hồng Dưỡng Ẩm Cấp Nước Chuyên Sâu OHUI Miracle Moisture Skin Softener 150ml', 'nuoc-hoa-hong-duong-am-cap-nuoc-chuyen-sau-ohui-miracle-moisture-skin-softener-150ml', 'Nước cân bằng làm mềm da chứa phức hợp độc quyền Chiffon Ceramide phục hồi màng ẩm trong suốt.', 'OHUI Miracle Moisture Skin Softener Moist là bước chuẩn bị hoàn hảo cho làn da thiếu ẩm và thô ráp. Công nghệ Chiffon Ceramide độc quyền của OHUI tạo nên lớp màng dưỡng ẩm mỏng nhẹ tựa như vải voan chiffon, nhẹ nhàng khép lại các liên kết tế bào biểu bì, làm mềm mịn bề mặt da ngay tức thì và mở đường cho các bước tinh chất dưỡng ẩm thẩm thấu trọn vẹn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Glycerin, Dipropylene Glycol, Methyl Gluceth-20, 1,2-Hexanediol, Panthenol, Ceramide NP, Ceramide AP, Ceramide EOP, Paeonia Albiflora Root Extract, Sodium Hyaluronate, Phytosphingosine, Cholesterol, Tromethamine, Carbomer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium EDTA, Parfum/Fragrance.', 'Sau khi rửa mặt sạch, đổ một lượng vừa đủ ra lòng bàn tay hoặc bông cotton, thoa đều và vỗ nhẹ khắp mặt và cổ theo hướng từ dưới lên trên.', 'Hàn Quốc', '150ml', 1, 4.92, 28, 63, 31, 1, 0, 'Chiffon Ceramide Complex (Ceramide 1, 3, 6), Peony Root Extract', NOW(), NOW()),
(254, 'Kem Dưỡng Vùng Mắt Tái Sinh Trẻ Hóa OHUI The First Geniture Eye Cream 25ml', 'kem-duong-vung-mat-tai-sinh-tre-hoa-ohui-the-first-geniture-eye-cream-25ml', 'Kem mắt hoàng gia nuôi dưỡng vùng da mắt chảy xệ và xóa mờ nếp nhăn vết chân chim.', 'OHUI The First Geniture Eye Cream chăm sóc vùng da quanh mắt chuyên biệt với nồng độ cô đặc dưỡng chất tế bào mầm và tinh dầu hạt macadamia. Kem thẩm thấu êm ái, tạo màng nâng đỡ vùng mi mắt mỏng yếu, kích thích sản sinh collagen làm săn chắc mi dưới, giảm thiểu bọng mỡ mắt và vết chân chim đuôi mắt do tuổi tác.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Glycerin, Hydrogenated Polydecene, Butylene Glycol, Dipropylene Glycol, Caprylic/Capric Triglyceride, Macadamia Ternifolia Seed Oil, Cetearyl Alcohol, C14-22 Alcohols, 1,2-Hexanediol, Paeonol, Oligopeptide-1, Oligopeptide-2, Oligopeptide-3, Ceramide NP, Squalane, Stearic Acid, Glyceryl Stearate, Tromethamine, Carbomer, Adenosine, Disodium EDTA, Parfum/Fragrance.', 'Lấy lượng kem nhỏ bằng hạt đậu thoa nhẹ nhàng quanh hốc mắt bằng ngón áp út, vỗ nhẹ theo hướng từ trong hốc mắt ra ngoài đuôi mắt vào mỗi sáng và tối.', 'Hàn Quốc', '25ml', 1, 4.85, 29, 64, 31, 1, 0, 'Signature 29 Cell, Peptides, Paeonol, Ceramide NP', NOW(), NOW()),
(255, 'Sữa Rửa Mặt Cấp Ẩm Dịu Nhẹ OHUI Miracle Moisture Cleansing Foam 160ml', 'sua-rua-mat-cap-am-diu-nhe-ohui-miracle-moisture-cleansing-foam-160ml', 'Bọt rửa mặt chứa Chiffon Ceramide làm sạch bụi mịn sâu mà vẫn duy trì làn da mướt mát.', 'OHUI Miracle Moisture Cleansing Foam là sữa rửa mặt tạo bọt cao cấp với kết cấu kem đặc mịn nhanh chóng tạo nên lớp bọt dày đàn hồi. Lớp bọt mềm mại cuốn sạch bụi mịn, cặn trang điểm và dầu thừa mà không làm tổn thương màng lipid da, giữ cho làn da ẩm mượt căng tràn sức sống nhờ phức hợp Chiffon Ceramide độc quyền.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Myristic Acid, Glycerin, Potassium Hydroxide, Stearic Acid, Lauric Acid, Glycol Distearate, Butylene Glycol, PEG-8, Cocamidopropyl Betaine, Glyceryl Stearate, PEG-100 Stearate, Ceramide NP, Ceramide AP, Ceramide EOP, Paeonia Albiflora Root Extract, Olea Europaea (Olive) Fruit Oil, Disodium EDTA, Parfum/Fragrance.', 'Lấy một lượng kem vừa đủ ra lòng bàn tay ướt, tạo bọt dày rồi mát xa nhẹ nhàng khắp mặt trong 60 giây. Rửa sạch lại bằng nước ấm.', 'Hàn Quốc', '160ml', 1, 4.92, 30, 65, 31, 1, 0, 'Chiffon Ceramide, Olive Oil, Paeonia Extract', NOW(), NOW()),
(256, 'Tinh Chất Trẻ Hóa Giảm Nếp Nhăn IOPE Retinol Expert 0.1% 30ml', 'tinh-chat-tre-hoa-giam-nep-nhan-iope-retinol-expert-0-1-30ml', 'Huyết thanh Retinol tinh khiết 0.1% công nghệ chống oxy hóa 3 lớp Cube Cell làm mờ nếp nhăn sau 2 tuần.', 'IOPE Retinol Expert 0.1% là đỉnh cao công nghệ chống lão hóa da liễu từ tập đoàn Amorepacific. Trải qua 27 năm nghiên cứu Retinol, IOPE sở hữu công nghệ bọc vi nang Cube Cell bảo toàn 100% hoạt tính của Retinol nguyên chất trước ánh sáng và không khí. Sản phẩm được kiểm nghiệm lâm sàng làm mờ rõ rệt nếp nhăn trán, rãnh mũi má và nếp nhăn đuôi mắt chỉ sau 2 tuần sử dụng.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water/Aqua/Eau, Caprylic/Capric Triglyceride, Propanediol, Glycerin, Dimethicone, Glyceryl Stearate, PEG-100 Stearate, Butylene Glycol, Cetearyl Alcohol, Retinol (0.1%), Panthenol, Sodium Hyaluronate, Madecassoside, Glycine Soja (Soybean) Oil, Hydrogenated Lecithin, Carbomer, Tromethamine, Ethylhexylglycerin, Adenosine, Disodium EDTA, BHT, Tocopherol.', 'Sử dụng vào buổi tối sau bước làm sạch và toner. Lấy lượng kem nhỏ bằng hạt đậu thoa tập trung vào các vùng có nếp nhăn (đuôi mắt, rãnh cười, trán). Ban ngày bắt buộc thoa kem chống nắng SPF50+.', 'Hàn Quốc', '30ml', 1, 4.85, 31, 66, 32, 0, 0, '0.1% Pure Stabilized Retinol, Hyaluronic Acid, Panthenol, Madecassoside', NOW(), NOW()),
(257, 'Nước Thần Men Vi Sinh Tái Tạo Làn Da IOPE Bio Conditioning Essence 168ml', 'nuoc-than-men-vi-sinh-tai-tao-lan-da-iope-bio-conditioning-essence-168ml', 'Nước thần chứa 92.5% hợp chất men vi sinh Bio-redox A tái tạo độ trong suốt và đàn hồi của da.', 'IOPE Bio Conditioning Essence là nước dưỡng tinh chất lên men sinh học nổi tiếng của IOPE chứa 92.5% phức hợp Bio-redox A mô phỏng hoạt chất chống oxy hóa tự nhiên trong cơ thể. Nước thần nhanh chóng thẩm thấu vào tầng sâu của da, thúc đẩy chu trình thanh lọc độc tố tế bào, cải thiện độ đều màu, độ mịn và trả lại làn da trong suốt căng mọng tràn đầy năng lượng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Saccharomyces Ferment Filtrate (92.5%), Butylene Glycol, Glycerin, Niacinamide, 1,2-Hexanediol, Adenosine, Sodium Hyaluronate, Theobroma Cacao (Cocoa) Extract, Dextrin, Water, Ethylhexylglycerin, Disodium EDTA.', 'Sau khi rửa mặt, kẹp miếng bông cotton vào ngón tay giữa, thấm 3ml nước thần theo vạch chia trên thân chai rồi vỗ nhẹ đều khắp mặt từ giữa mặt ra ngoài.', 'Hàn Quốc', '168ml', 1, 4.92, 32, 67, 32, 0, 0, '92.5% Bio-Redox A (Saccharomyces Ferment), Niacinamide, Adenosine', NOW(), NOW()),
(258, 'Kem Dưỡng Tế Bào Gốc Phục Hồi Chuyên Sâu IOPE Stem III Ampoule Cream 50ml', 'kem-duong-te-bao-goc-phuc-hoi-chuyen-sau-iope-stem-iii-ampoule-cream-50ml', 'Kem dưỡng phục hồi da lão hóa chứa hoạt chất Allanto-Liposome giải quyết các dấu hiệu mệt mỏi.', 'IOPE Stem III Ampoule Cream được đặc chế nhằm cứu vãn làn da bị tổn thương và lão hóa do thiếu ngủ, căng thẳng kéo dài. Hoạt chất độc quyền Allanto-Liposome với kích thước siêu nhỏ chỉ bằng 1/400 sợi tóc giúp đưa dưỡng chất tái sinh tế bào Allantoin thẩm thấu sâu, củng cố độ đàn hồi, làm đầy các nếp nhăn và phục hồi hàng rào ẩm vững chắc.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Butylene Glycol, Glycerin, Hydrogenated Poly(C6-14 Olefin), Squalane, Pentaerythrityl Tetraethylhexanoate, Dimethicone, Cetearyl Alcohol, 1,2-Hexanediol, Allantoin, Panthenol, Ceramide NP, Stearic Acid, Glyceryl Stearate, Tromethamine, Carbomer, Adenosine, Disodium EDTA, Ethylhexylglycerin.', 'Lấy một lượng kem vừa đủ thoa đều khắp mặt và cổ ở bước cuối cùng của chu trình dưỡng da, mát xa nhẹ nhàng theo chiều nâng cơ.', 'Hàn Quốc', '50ml', 1, 4.85, 33, 68, 32, 0, 0, 'Allanto-Liposome Technology, Panthenol, Ceramide NP, Squalane', NOW(), NOW()),
(259, 'Phấn Nước Che Khuyết Điểm Căng Bóng IOPE Air Cushion Cover SPF50+ PA+++ 15g', 'phan-nuoc-che-khuyet-diem-cang-bong-iope-air-cushion-cover-spf50-pa-plus-plus-plus-15g', 'Cushion nguyên bản đầu tiên trên thế giới công nghệ Bio Water tạo lớp nền mỏng nhẹ che phủ cao.', 'IOPE Air Cushion là thương hiệu khai sinh ra khái niệm phấn nước Cushion trên toàn thế giới. Phiên bản Cover thế hệ mới với công nghệ Bio Water dưỡng ẩm sâu kết hợp bột phấn hình cầu siêu vi che phủ hoàn hảo vết thâm, đốm đỏ và lỗ chân lông mà vẫn duy trì độ mỏng nhẹ, căng bóng tự nhiên suốt 12 giờ không bị mốc hay xuống tông.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Titanium Dioxide (CI 77891), Cyclopentasiloxane, Ethylhexyl Methoxycinnamate, Ethylhexyl Salicylate, Glycerin, Lauryl PEG-9 Polydimethylsiloxyethyl Dimethicone, Niacinamide, Butylene Glycol, Zinc Oxide, Iron Oxides (CI 77492), Silica, Disteardimonium Hectorite, Aluminum Hydroxide, Stearic Acid, Adenosine, Disodium EDTA, Parfum/Fragrance.', 'Dùng bông phấn ấn nhẹ vào lõi đệm để lấy lượng phấn vừa đủ. Dặm nhẹ nhàng khắp mặt theo chiều cấu trúc da từ trong ra ngoài.', 'Hàn Quốc', '15g', 1, 4.92, 34, 69, 32, 1, 0, 'Bio Water, Air Cover Powder, SPF 50+ PA+++, Niacinamide', NOW(), NOW()),
(260, 'Kem Dưỡng Vùng Mắt Nâng Cơ Chống Chảy Xệ IOPE Live Lift Eye Cream 25ml', 'kem-duong-vung-mat-nang-co-chong-chay-xe-iope-live-lift-eye-cream-25ml', 'Kem mắt chiết xuất thảo mộc thùa Agave quý hiếm tăng cường độ săn chắc và đàn hồi mí mắt.', 'IOPE Live Lift Eye Cream chứa nguồn năng lượng sinh học mãnh liệt từ cây thùa Agave có khả năng tồn tại qua điều kiện sa mạc khắc nghiệt. Phức hợp Fructan từ cây thùa thẩm thấu sâu, thắt chặt các liên kết mô biểu bì quanh mắt, cải thiện tình trạng sụp mí và bọng mắt chảy xệ, mang lại ánh nhìn tươi trẻ tràn đầy sức sống.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water/Aqua/Eau, Butylene Glycol, Glycerin, Hydrogenated Poly(C6-14 Olefin), Squalane, Pentaerythrityl Tetraethylhexanoate, Agave Americana Leaf Extract, Butyrospermum Parkii (Shea) Butter, Cetearyl Alcohol, 1,2-Hexanediol, Dimethicone, Glyceryl Stearate, Tromethamine, Carbomer, Adenosine, Disodium EDTA, Ethylhexylglycerin.', 'Chấm nhẹ kem lên vùng mí trên và mí dưới, dùng ngón tay áp út vỗ nhẹ nhàng từ khóe mắt trong ra đuôi mắt vào mỗi buổi sáng và tối.', 'Hàn Quốc', '25ml', 1, 4.85, 35, 70, 32, 0, 0, 'Agave Fructan Extract, Squalane, Shea Butter, Adenosine', NOW(), NOW()),
(261, 'Tinh Chất Phục Hồi Tăng Đề Kháng Da Shiseido Ultimune Power Infusing Concentrate 50ml', 'tinh-chat-phuc-hoi-tang-de-khang-da-shiseido-ultimune-power-infusing-concentrate-50ml', 'Huyết thanh số 1 Shiseido công nghệ The Lifeblood kích hoạt lưu thông máu và hệ miễn dịch tế bào da.', 'Shiseido Ultimune Power Infusing Concentrate là biểu tượng của tinh thần làm đẹp Nhật Bản với hơn 200 giải thưởng sắc đẹp quốc tế. Ứng dụng công nghệ ImuGenerationRED độc quyền tác động vào mạng lưới tuần hoàn máu dưới da, kết hợp chiết xuất nấm linh chi Reishi và rễ hoa diên vĩ Iris, serum tăng cường sức đề kháng tế bào, đẩy lùi lão hóa và mang lại làn da khỏe khoắn bừng sáng từ bên trong.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water(Aqua/Eau), Alcohol Denat., Glycerin, Butylene Glycol, PEG/PPG-17/4 Dimethyl Ether, Triethylhexanoin, Cyclohexasiloxane, Dimethicone, Phenoxyethanol, Trehalose, Ammonium Acryloyldimethyltaurate/VP Copolymer, PEG-14M, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Rosa Damascena Flower Water, Tocopheryl Acetate, Rosa Roxburghii Fruit Extract, Ganoderma Lucidum (Mushroom) Stem Extract, Iris Florentina Root Extract, Fragrance(Parfum).', 'Nhấn 2 lần bơm tinh chất thoa đều khắp mặt vào mỗi buổi sáng và tối sau bước nước hoa hồng và trước bước kem dưỡng ẩm.', 'Nhật Bản', '50ml', 1, 4.92, 36, 71, 33, 1, 0, 'Reishi Mushroom Extract, Iris Root Extract, The Lifeblood Technology, Ectoin', NOW(), NOW()),
(262, 'Kem Chống Nắng Đồng Bộ Nhiệt Shiseido The Perfect Protector SynchroShield SPF50+ 50ml', 'kem-chong-nang-dong-bo-nhiet-shiseido-the-perfect-protector-synchroshield-spf50-50ml', 'Kem chống nắng công nghệ SynchroShield càng nóng, càng đổ mồ hôi và gặp nước thì màng bảo vệ càng mạnh.', 'Shiseido The Perfect Protector SynchroShield SPF50+ PA++++ sở hữu công nghệ chống nắng thông minh đỉnh cao WetForce x HeatForce: lớp màng bảo vệ da sẽ tự động trở nên đồng nhất và mạnh mẽ hơn khi tiếp xúc với nhiệt độ cao hoặc nước và mồ hôi. Chứa hơn 50% thành phần dưỡng da bảo vệ tế bào chống lại quá trình lão hóa quang hóa do ánh nắng mặt trời.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water(Aqua/Eau), Diisopropyl Sebacate, Talc, Isododecane, Methyl Methacrylate Crosspolymer, Dimethicone, Ethylhexyl Salicylate, Ethylhexyl Methoxycinnamate, Alcohol, Zinc Oxide, Octocrylene, Titanium Dioxide, PEG-9 Polydimethylsiloxyethyl Dimethicone, Butylene Glycol, Saxifraga Sarmentosa Extract, Camellia Sinensis Leaf Extract, Scutellaria Baicalensis Root Extract, Syzygium Jambos Leaf Extract, Tocopherol, Fragrance(Parfum).', 'Lắc kỹ trước khi dùng. Thoa một lượng vừa đủ lên mặt và cổ trước khi ra ngoài nắng 20 phút. Thoa lại sau khi bơi lội hoặc lau khăn.', 'Nhật Bản', '50ml', 1, 4.85, 37, 72, 33, 1, 1, 'SynchroShield Technology (WetForce + HeatForce), Profense CEL, NatureSurge Complex', NOW(), NOW()),
(263, 'Kem Ủ Tóc Phục Hồi Hư Tổn Cao Cấp Shiseido Fino Premium Touch Hair Treatment Mask 230g', 'kem-u-toc-phuc-hoi-hu-ton-cao-cap-shiseido-fino-premium-touch-hair-treatment-mask-230g', 'Mặt nạ ủ tóc số 1 Nhật Bản chứa sữa ong chúa và Lipidure phục hồi mái tóc xơ rối chuẩn salon.', 'Shiseido Fino Premium Touch Hair Mask là kem ủ tóc bán chạy nhất Nhật Bản dành cho tóc hư tổn do uốn, nhuộm, tẩy hay sấy nhiệt. Công thức chứa 6 dưỡng chất vàng gồm sữa ong chúa Royal Jelly EX nuôi dưỡng nang tóc, Trehalose & Sorbitol giữ ẩm, PCA củng cố biểu bì tóc, Phytosteryl làm mềm và Lipidure phục hồi lõi tóc, đem lại mái tóc bóng mượt mềm rũ tự nhiên.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sorbitol, Dimethicone, Isopentyldiol, Behentrimonium Chloride, Mineral Oil, Cetyl Alcohol, Aminopropyl Dimethicone, Hydroxypropyl Arginine Lauryl/Myristyl Ether HCl, Steartrimonium Chloride, Squalane, Royal Jelly Extract, Phytosteryl/Octyldodecyl Lauroyl Glutamate, Trehalose, Phenoxyethanol, Fragrance, CI 15985, CI 19140.', 'Sau khi gội đầu sạch, vắt ráo bớt nước trên tóc. Lấy một lượng kem ủ vừa đủ thoa đều từ thân tóc đến ngọn tóc, mát xa nhẹ và ủ trong 5-10 phút rồi xả sạch lại bằng nước.', 'Nhật Bản', '230g', 1, 4.92, 38, 73, 33, 1, 0, 'Royal Jelly EX, Trehalose, PCA, Phytosteryl Derivatives, Squalane', NOW(), NOW()),
(264, 'Kem Dưỡng Đặc Trị Nứt Nẻ Gót Chân Và Da Tay Shiseido Urea 10% Cream 100g', 'kem-duong-dac-tri-nut-ne-got-chan-va-da-tay-shiseido-urea-10-cream-100g', 'Kem đặc trị chứa 10% Urea và Vitamin E xóa tan các vết chai sần nứt nẻ gót chân và khuỷu tay khô cứng.', 'Shiseido Urea 10% Cream là sản phẩm chăm sóc vùng da chai sần số 1 tại các hiệu thuốc Nhật Bản. Nồng độ 10% Urea chuẩn y khoa có khả năng phân giải keratin làm mềm các lớp tế bào sừng dày cộm ở gót chân, đầu gối và khuỷu tay, kết hợp Vitamin E và Hyaluronic Acid thẩm thấu sâu làm lành các vết nứt nẻ đau rát, trả lại làn da mịn màng êm ái.', 'https://images.unsplash.com/photo-1556228852-80b6e5eeff06?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'DRY', 'Urea (100mg/g), Tocopherol Acetate (1mg/g), Dipotassium Glycyrrhizate (0.5mg/g), Liquid Paraffin, Squalane, Vaseline, Silicone Oil, Cetanol, Stearyl Alcohol, Glycerin, 1,3-Butylene Glycol, Stearic Acid, Behenic Acid, Triethanolamine, Sodium Hyaluronate, Water.', 'Rửa sạch vùng gót chân hoặc bàn tay rồi lau khô. Thoa kem đều đặn 2-3 lần mỗi ngày lên các vùng da bị nứt nẻ, chai ráp.', 'Nhật Bản', '100g', 1, 4.85, 39, 74, 33, 0, 0, '10% Urea, Tocopheryl Acetate (Vitamin E), Dipotassium Glycyrrhizate, Squalane', NOW(), NOW()),
(265, 'Bông Tẩy Trang 100% Cotton Tự Nhiên Cao Cấp Shiseido Facial Cotton 165 miếng', 'bong-tay-trang-100-cotton-tu-nhien-cao-cap-shiseido-facial-cotton-165-mieng', 'Bông cotton dưỡng da thượng hạng số 1 thế giới dệt từ sợi bông thiên nhiên Nhật Bản siêu mềm mịn.', 'Shiseido Facial Cotton là biểu tượng chăm sóc da xa xỉ kinh điển của thương hiệu Shiseido Nhật Bản được các chuyên gia làm đẹp toàn cầu tôn vinh. Được dệt tỉ mỉ từ 100% sợi bông cotton thiên nhiên tinh khiết với kỹ thuật ép lớp đệm không khí độc quyền, miếng bông siêu dày dặn, lướt êm ái như tơ lụa trên da mà không hề để lại xơ bông, tối ưu hóa độ thẩm thấu của nước cân bằng và nước tẩy trang vào sâu trong biểu bì.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', '100% Natural Japanese Cotton Fibers.', 'Thấm đẫm toner hoặc nước tẩy trang lên miếng bông, kẹp giữa ngón trỏ và ngón áp út rồi nhẹ nhàng lướt trên da theo hướng từ trong ra ngoài và từ dưới lên trên.', 'Nhật Bản', '165 miếng', 1, 4.92, 40, 75, 33, 0, 0, '100% Pure Natural Cotton Fibers, Ultra-soft Multi-layer Weave', NOW(), NOW()),
(266, 'Dầu Tẩy Trang Làm Sạch Sâu Mụn Đầu Đen Kosé Softymo Deep Cleansing Oil 230ml', 'dau-tay-trang-lam-sach-sau-mun-dau-den-kose-softymo-deep-cleansing-oil-230ml', 'Dầu tẩy trang chứa 5 loại dầu thực vật hữu cơ hòa tan sợi bã nhờn và mụn đầu đen vùng mũi.', 'Kosé Softymo Deep Cleansing Oil là dầu tẩy trang quốc dân Nhật Bản với khả năng làm sạch sâu vượt trội. Chứa hỗn hợp 5 loại dầu thực vật hữu cơ tinh khiết (dầu cám gạo, dầu jojoba, dầu ô liu, dầu mè và dầu hạt hoa rum) giúp đánh tan các nút bã nhờn cứng đầu tích tụ ở cánh mũi, làm sạch hoàn toàn mascara kháng nước mà vẫn giữ ẩm êm dịu cho làn da.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Mineral Oil, Oryza Sativa (Rice) Bran Oil, Sorbeth-30 Tetraoleate, Cyclomethicone, Olea Europaea (Olive) Fruit Oil, Sesamum Indicum (Sesame) Seed Oil, Carthamus Tinctorius (Safflower) Seed Oil, Butyrospermum Parkii (Shea) Butter, Tocopherol, Simmondsia Chinensis (Jojoba) Seed Oil, Macadamia Ternifolia Seed Oil, BHT, Glycerin, Propylene Glycol Dicaprate.', 'Lấy 2-3 lần bơm dầu xoa lên mặt khô, mát xa kỹ vùng mũi và cằm trong 1-2 phút để mụn đầu đen bong ra. Thêm nước ấm để nhũ hóa chuyển sang dạng sữa rồi rửa sạch lại với nước.', 'Nhật Bản', '230ml', 1, 4.85, 41, 76, 34, 0, 0, '5 Organic Botanical Oils (Rice Bran, Jojoba, Olive, Sesame, Safflower)', NOW(), NOW()),
(267, 'Nước Hoa Hồng Thảo Dược Dưỡng Sáng Da Kosé Sekkisei Medicated Lotion 200ml', 'nuoc-hoa-hong-thao-duoc-duong-sang-da-kose-sekkisei-medicated-lotion-200ml', 'Nước hoa hồng thảo dược phương Đông chứa hạt ý dĩ Coix Seed làm da sáng trong như tuyết.', 'Kosé Sekkisei Medicated Lotion là dòng nước dưỡng sáng da huyền thoại của Kosé suốt hơn 3 thập kỷ. Kết hợp tinh hoa thảo dược phương Đông quý giá gồm hạt ý dĩ Coix Seed, rễ cây bạch chỉ Angelica và cây mướp gai Melothria, sản phẩm thanh lọc sắc tố melanin xỉn màu, cải thiện tình trạng da không đều màu và trả lại làn da trắng ngần trong suốt như tuyết đầu mùa.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water (Aqua), Alcohol, Glycerin, Angelica Acutiloba Root Extract, Coix Lacryma-Jobi (Job''s Tears) Seed Extract, Dipotassium Glycyrrhizate, Hamamelis Virginiana (Witch Hazel) Extract, Melothria Heterophylla Root Extract, Tocopheryl Acetate, Triticum Vulgare (Wheat) Germ Oil, Citric Acid, Di-C12-15 Pareth-8 Phosphate, Ethylhexyl Methoxycinnamate, Polysorbate 80, Sodium Citrate, Sorbitan Sesquioleate, Triethylhexanoin, Ethylparaben, Methylparaben, Propylparaben, Fragrance (Parfum).', 'Thấm dung dịch ra bông cotton và vỗ nhẹ khắp mặt theo hướng từ trong ra ngoài. Có thể đắp lotion mask trong 3-5 phút để phát huy tối đa công dụng làm sáng da.', 'Nhật Bản', '200ml', 1, 4.92, 42, 77, 34, 1, 1, 'Coix Seed Extract, Angelica Acutiloba Root, Melothria Root, Dipotassium Glycyrrhizate', NOW(), NOW()),
(268, 'Tinh Chất Chống Nắng Nâng Tông Kosé Suncut Tone Up UV Essence SPF50+ 80g', 'tinh-chat-chong-nang-nang-tong-kose-suncut-tone-up-uv-essence-spf50-80g', 'Kem chống nắng sắc tím oải hương Lavender hiệu chỉnh sắc da vàng vọt nâng tông sáng hồng rạng rỡ.', 'Kosé Suncut Tone Up UV Essence SPF50+ PA++++ sở hữu sắc tím hoa oải hương Lavender độc đáo kết hợp cùng các hạt ngọc trai phản chiếu ánh sáng giúp trung hòa sắc tố da vàng xỉn màu, nâng tông da sáng hồng trong veo tự nhiên. Khả năng chống nước Waterproof siêu bền bỉ và công thức bổ sung chiết xuất quả mâm xôi, hoa cúc dưỡng ẩm suốt cả ngày.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Ethylhexyl Methoxycinnamate, Alcohol, Zinc Oxide, Isododecane, Polysilicone-15, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Butylene Glycol, Propylene Glycol Dicaprate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Titanium Dioxide, Silica, Sodium Hyaluronate, Rubus Idaeus (Raspberry) Fruit Extract, Chamomilla Recutita (Matricaria) Flower Extract, Mica, Blue 1 (CI 42090), Red 33 (CI 17200), Fragrance.', 'Lấy lượng kem vừa đủ thoa đều khắp mặt và cổ trước khi ra nắng 20 phút. Thoa lại sau mỗi 2-3 giờ khi vận động nhiều ngoài trời.', 'Nhật Bản', '80g', 1, 4.85, 43, 78, 34, 1, 1, 'Lavender Color-correcting Tint, Pink Pearl Particles, Raspberry Extract, Vitamin C', NOW(), NOW()),
(269, 'Kem Ủ Tóc Phục Hồi Hư Tổn Chiết Xuất Thực Vật Kosé Bioliss Botanical Deep Repair Hair Mask 200g', 'kem-u-toc-phuc-hoi-hu-ton-chiet-xuat-thuc-vat-kose-bioliss-botanical-deep-repair-hair-mask-200g', 'Mặt nạ ủ tóc thực vật hữu cơ chứa tinh dầu Jojoba và Argan phục hồi tóc chẻ ngọn khô xơ cấp tốc.', 'Kosé Cosmeport Bioliss Botanical Deep Repair Hair Mask là liệu pháp ủ tóc chuẩn salon cao cấp với công thức thuần thực vật hữu cơ đạt chuẩn chứng nhận. Chứa nồng độ cao tinh dầu Jojoba ép lạnh, tinh dầu Argan Morocco và ceramide thực vật, kem ủ thẩm thấu sâu vào lõi tóc chỉ sau 1 phút, hàn gắn các lớp biểu bì tóc bị hư tổn do uốn nhuộm sấy nhiệt, đem lại mái tóc suôn mượt óng ả và ngát hương hoa quả tự nhiên.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Dimethicone, Cetearyl Alcohol, Behenyl Alcohol, Behentrimonium Chloride, Glycerin, Hydrogenated Polyisobutene, Argania Spinosa Kernel Oil, Simmondsia Chinensis (Jojoba) Seed Oil, Astrocaryum Murumuru Seed Butter, Hydrolyzed Soy Protein, Isopropyl Alcohol, Citric Acid, Phenoxyethanol, Fragrance.', 'Sau khi gội đầu và xả sạch, vắt ráo bớt nước trên tóc. Lấy lượng kem ủ vừa đủ thoa đều từ thân tóc đến ngọn tóc, mát xa nhẹ nhàng trong 1-3 phút rồi xả sạch lại bằng nước ấm.', 'Nhật Bản', '200g', 1, 4.92, 44, 79, 34, 1, 0, 'Organic Cold-pressed Jojoba Oil, Argan Oil, Botanical Keratin, Amino Acids', NOW(), NOW()),
(270, 'Gel Tẩy Tế Bào Chết Chiết Xuất Trái Cây Kosé Cosmeport Clear Turn Peeling Gel 150ml', 'gel-tay-te-bao-chet-chiet-xuat-trai-cay-kose-cosmeport-clear-turn-peeling-gel-150ml', 'Gel tẩy da chết dịu nhẹ chứa AHA axit trái cây tự nhiên làm sạch sâu bề mặt da không gây rát ngứa.', 'Kosé Cosmeport Clear Turn Peeling Gel là giải pháp làm sạch tế bào sừng già cỗi được phụ nữ Nhật Bản tin dùng. Chứa chiết xuất axit trái cây tự nhiên AHA (táo, cam, chanh) kết hợp cùng Hyaluronic Acid, gel nhẹ nhàng cuốn trôi các tế bào biểu bì sần sùi xỉn màu và bụi bẩn khi xoa nhẹ, giúp da sáng mịn và tăng cường khả năng thẩm thấu kem dưỡng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Glycerin, Carbomer, Steartrimonium Chloride, Pyrus Malus (Apple) Fruit Extract, Citrus Aurantium Dulcis (Orange) Fruit Extract, Citrus Limon (Lemon) Fruit Extract, Sodium Hyaluronate, Butylene Glycol, Fragrance, Phenoxyethanol.', 'Sau khi rửa mặt và lau khô, lấy lượng gel vừa phải thoa đều lên mặt. Mát xa nhẹ nhàng theo hình xoắn ốc trong 1 phút cho đến khi các vụn gôm cuốn sạch tế bào chết, sau đó rửa sạch lại bằng nước ấm. Dùng 1-2 lần/tuần.', 'Nhật Bản', '150ml', 1, 4.85, 45, 80, 34, 1, 0, 'Fruit AHA (Apple, Orange, Lemon Acids), Hyaluronic Acid', NOW(), NOW()),
(271, 'Sữa Tắm Dưỡng Ẩm Chuyên Sâu Dove Deeply Nourishing Body Wash 900g', 'sua-tam-duong-am-chuyen-sau-dove-deeply-nourishing-body-wash-900g', 'Sữa tắm dưỡng ẩm biểu tượng với công nghệ NutriumMoisture nuôi dưỡng làn da mềm mịn ngay sau lần tắm đầu tiên.', 'Dove Deeply Nourishing Body Wash là dòng sữa tắm dưỡng ẩm số 1 toàn cầu chứa 1/4 hàm lượng kem dưỡng ẩm dịu nhẹ kết hợp công nghệ NutriumMoisture độc quyền. Bọt sữa tắm dày mịn thẩm thấu sâu nuôi dưỡng từng lớp tế bào biểu bì, làm sạch bụi bẩn mà không cuốn trôi lớp lipid bảo vệ da, đem lại làn da mịn màng, ẩm mượt ngay sau lần tắm đầu tiên.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Cocamidopropyl Betaine, Sodium Methyl Lauroyl Taurate, Sodium Cocoyl Isethionate, Glycerin, Fragrance, Sodium Chloride, Phenoxyethanol, Carbomer, Sodium Hydroxide, Lauric Acid, Stearic Acid, Palmitic Acid, PPG-7, Coconut Acid, BHT, Tetrasodium EDTA.', 'Cho một lượng sữa tắm vừa đủ ra lòng bàn tay hoặc bông tắm ướt, tạo bọt dày rồi xoa đều khắp cơ thể. Mát xa nhẹ nhàng và tắm sạch lại với nước.', 'Mỹ', '900g', 1, 4.92, 46, 81, 35, 1, 0, '1/4 Moisturizing Cream, NutriumMoisture Technology, Stearic Acid', NOW(), NOW()),
(272, 'Sữa Dưỡng Thể Dầu Dừa Phục Hồi Da Khô Dove Body Love Restoring Care Lotion 400ml', 'sua-duong-the-dau-dua-phuc-hoi-da-kho-dove-body-love-restoring-care-lotion-400ml', 'Sữa dưỡng thể phục hồi da khô nứt chứa tinh dầu dừa tự nhiên và sữa hạnh nhân cấp ẩm suốt 48H.', 'Dove Body Love Restoring Care Lotion lấy cảm hứng từ liệu pháp làm đẹp truyền thống của phụ nữ Ấn Độ. Công thức kết hợp tinh dầu dừa dồi dào dưỡng chất cùng sữa hạnh nhân và phức hợp Ceramide Restoring Serum giúp khóa ẩm sâu suốt 48 giờ, phục hồi làn da khô sần ráp trở nên mềm mại, căng bóng và lưu lại hương dừa hạnh nhân ngọt ngào ấm áp.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'DRY', 'Aqua, Glycerin, Dimethicone, Stearic Acid, Caprylic/Capric Triglyceride, Glycol Stearate, PEG-100 Stearate, Petrolatum, Glyceryl Stearate, Caprylyl Glycol, Phenoxyethanol, Cetyl Alcohol, Parfum, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Disodium EDTA, Stearamide AMP, Carbomer, Cocos Nucifera (Coconut) Oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil.', 'Thoa đều khắp cơ thể mỗi ngày sau khi tắm, mát xa nhẹ nhàng theo hình vòng tròn cho sữa dưỡng thấm sâu vào da.', 'Mỹ', '400ml', 1, 4.85, 47, 82, 35, 1, 0, 'Coconut Oil, Almond Milk, Ceramide Restoring Serum', NOW(), NOW()),
(273, 'Dầu Gội Phục Hồi Hư Tổn Chuyên Sâu Dove Nutritive Solutions Intense Repair Shampoo 640g', 'dau-goi-phuc-hoi-hu-ton-chuyen-sau-dove-nutritive-solutions-intense-repair-shampoo-640g', 'Dầu gội phục hồi tóc chẻ ngọn chứa hoạt chất Keratin Actives nuôi dưỡng sợi tóc từ sâu bên trong.', 'Dove Nutritive Solutions Intense Repair Shampoo với công thức Bio-Nourish kết hợp hoạt chất phục hồi Keratin Actives thẩm thấu sâu vào lõi từng sợi tóc bị hư tổn do hóa chất và nhiệt độ. Dầu gội làm sạch tóc nhẹ nhàng, hàn gắn lớp vảy biểu bì tóc bị xơ rối, ngăn ngừa gãy rụng và nuôi dưỡng mái tóc chắc khỏe bóng mượt dần theo từng lần gội.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Dimethiconol, Cocamidopropyl Betaine, Sodium Chloride, Glycol Distearate, Fragrance, Glycerin, Carbomer, TEA-Dodecylbenzenesulfonate, Guar Hydroxypropyltrimonium Chloride, TEA-Sulfate, Citric Acid, Disodium EDTA, Sodium Gluconate, Trehalose, Sodium Sulfate, DMDM Hydantoin, Magnesium Nitrate.', 'Làm ướt tóc, lấy lượng dầu gội vừa đủ xoa đều lên tóc và da đầu. Mát xa tạo bọt nhẹ nhàng trong 2 phút rồi xả sạch với nước. Kết hợp dùng dầu xả Dove để đạt kết quả tốt nhất.', 'Mỹ', '640g', 1, 4.92, 48, 83, 35, 1, 0, 'Keratin Repair Actives, Bio-Nourish Complex, Sodium Gluconate', NOW(), NOW()),
(274, 'Dầu Xả Phục Hồi Hư Tổn Nuôi Dưỡng Tóc Dove Nutritive Solutions Intense Repair Conditioner 640g', 'dau-xa-phuc-hoi-hu-ton-nuoi-duong-toc-dove-nutritive-solutions-intense-repair-conditioner-640g', 'Dầu xả phục hồi tóc hư tổn tái tạo độ mềm mượt óng ả và ngăn ngừa tóc gãy rụng chẻ ngọn.', 'Dove Nutritive Solutions Intense Repair Conditioner bổ sung công nghệ Keratin Actives thấm sâu vào từng sợi tóc, ngay lập tức gỡ rối và làm mượt bề mặt sợi tóc khô ráp. Dầu xả tạo lớp màng bảo vệ tóc trước nhiệt độ sấy và tia UV, đem lại mái tóc suôn mượt dễ chải và tràn đầy sức sống.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Cetearyl Alcohol, Dimethicone, Stearamidopropyl Dimethylamine, Behentrimonium Chloride, Fragrance, Dipropylene Glycol, Lactic Acid, Amodimethicone, Disodium EDTA, Sodium Gluconate, Trehalose, DMDM Hydantoin, PEG-7 Propylheptyl Ether, Cetrimonium Chloride, Phenoxyethanol, Sodium Chloride.', 'Sau khi gội đầu sạch, thoa dầu xả lên thân và ngọn tóc (tránh chân tóc). Vuốt nhẹ đều và ủ trong 1-2 phút rồi xả sạch lại bằng nước mát.', 'Mỹ', '640g', 1, 4.85, 49, 84, 35, 1, 0, 'Keratin Repair Actives, Cetearyl Alcohol, Dimethicone', NOW(), NOW()),
(275, 'Lăn Khử Mùi Dịu Nhẹ Không Cồn Dove Advanced Care Original Deodorant Roll-On 50ml', 'lan-khu-mui-diu-nhe-khong-con-dove-advanced-care-original-deodorant-roll-on-50ml', 'Lăn nách dưỡng ẩm chứa 1/4 hàm lượng kem dưỡng phục hồi da sần sùi dưới cánh tay sau cạo nhổ suốt 48H.', 'Dove Advanced Care Original Deodorant Roll-On là giải pháp khử mùi dịu nhẹ hàng đầu chứa 1/4 hàm lượng kem dưỡng ẩm Dove độc quyền cùng dầu hạt hướng dương tự nhiên. Sản phẩm kiểm soát mồ hôi và mùi cơ thể hiệu quả suốt 48 giờ, hỗ trợ phục hồi vùng da nách bị thâm sạm và sần sùi tổn thương sau khi dùng nhíp hoặc dao cạo.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua, Aluminum Chlorohydrate, Glycerin, Helianthus Annuus Seed Oil, Steareth-2, Parfum, Steareth-20, Disodium EDTA, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Alpha-Isomethyl Ionone, Benzyl Alcohol, Benzyl Benzoate, Citronellol, Coumarin, Geraniol, Hexyl Cinnamal, Linalool.', 'Lăn đều 2-3 lượt lên vùng da dưới cánh tay khô ráo và sạch sẽ mỗi sáng. Để khô vài giây trước khi mặc quần áo.', 'Mỹ', '50ml', 1, 4.92, 50, 85, 35, 1, 0, '1/4 Moisturizing Cream, Aluminum Chlorohydrate, Helianthus Annuus Seed Oil', NOW(), NOW()),
(276, 'Lăn Khử Mùi Dưỡng Sáng Mờ Thâm Nivea Extra Brightening 8 Super Food Roll-On 50ml', 'lan-khu-mui-duong-sang-mo-tham-nivea-extra-brightening-8-super-food-roll-on-50ml', 'Lăn khử mùi chứa vi dưỡng chất Vitamin C tinh khiết từ 8 loại siêu thực phẩm dưỡng sáng mờ thâm nách.', 'Nivea Extra Brightening 8 Super Food Roll-On ứng dụng công nghệ vi dẫn xuất Vitamin C nồng độ cao chiết xuất từ 8 loại trái cây giàu dưỡng chất (lựu, bơ, dâu tây, sơ ri, v.v.). Sản phẩm nuôi dưỡng sâu tận gốc nang lông, làm mờ các vết thâm sạm tối màu vùng nách và se khít lỗ chân lông, ngăn mùi và mồ hôi tối ưu suốt 48 giờ không chứa cồn.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua, Aluminum Chlorohydrate, PPG-15 Stearyl Ether, Steareth-2, Steareth-21, Sodium Ascorbyl Phosphate, Glycyrrhiza Glabra Root Extract, Punica Granatum Fruit Juice, Persea Gratissima Oil, Fragaria Ananassa Fruit Juice, Rubus Fruticosus Fruit Juice, Rubus Idaeus Fruit Juice, Vaccinium Myrtillus Fruit Juice, Hydrolyzed Pearl, Glycerin, Propylene Glycol, Trisodium EDTA, BHT, Parfum.', 'Lăn trực tiếp lên vùng da nách khô ráo mỗi sáng sau khi tắm. Để khô hoàn toàn trước khi mặc trang phục.', 'Đức', '50ml', 1, 4.85, 51, 86, 36, 1, 0, '8 Super Food Extracts, Vitamin C Micro-particles, Licorice Extract', NOW(), NOW()),
(277, 'Sữa Dưỡng Thể Sáng Da Chống Nắng Nivea Extra White Repair & Protect Lotion SPF30 350ml', 'sua-duong-the-sang-da-chong-nang-nivea-extra-white-repair-and-protect-lotion-spf30-350ml', 'Sữa dưỡng thể chứa hàm lượng Vitamin C gấp 50 lần từ quả Camu Camu và màng lọc chống nắng SPF 30.', 'Nivea Extra White Repair & Protect Lotion là dòng sữa dưỡng thể làm sáng da nổi tiếng chứa chiết xuất siêu quả Camu Camu với hàm lượng Vitamin C cao gấp 50 lần quả chanh. Kết hợp cùng chỉ số chống nắng SPF 30 PA++ bảo vệ da trước ánh nắng gay gắt, sữa dưỡng phục hồi vùng da cháy nắng xỉn màu, ngăn sạm đen trở lại và dưỡng da toàn thân sáng mịn màng.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Aqua, C12-15 Alkyl Benzoate, Glycerin, Alcohol Denat., Butyl Methoxydibenzoylmethane, Octocrylene, Sodium Phenylbenzimidazole Sulfonate, Cetyl Alcohol, Dimethicone, Palmitic Acid, Stearic Acid, Cetyl Palmitate, Glyceryl Stearate, Tapioca Starch, Myrciaria Dubia Fruit Juice, Malpighia Glabra Fruit Juice, Glycyrrhiza Glabra Root Extract, Sodium Ascorbyl Phosphate, Myristic Acid, Arachidic Acid, Oleic Acid, Citric Acid, Trisodium EDTA, Phenoxyethanol, Ethylparaben, Methylparaben, Parfum.', 'Thoa đều khắp cơ thể trước khi ra ngoài vào ban ngày ít nhất 20 phút. Mát xa nhẹ nhàng cho sữa dưỡng thẩm thấu.', 'Đức', '350ml', 1, 4.92, 52, 87, 36, 1, 0, '50x Vitamin C (Camu Camu Extract), SPF 30 PA++, Licorice Extract', NOW(), NOW()),
(278, 'Son Dưỡng Ẩm Chuyên Sâu Không Màu Nivea Lip Care Original Care Deep Moisture 4.8g', 'son-duong-am-chuyen-sau-khong-mau-nivea-lip-care-original-care-deep-moisture-4-8g', 'Son dưỡng môi không màu chứa bơ hạt mỡ tự nhiên và dầu jojoba cấp ẩm liên tục suốt 24H.', 'Nivea Lip Care Original Care là thỏi son dưỡng môi quen thuộc của hàng triệu gia đình với khả năng dưỡng ẩm vượt trội kéo dài 24 giờ. Công thức chứa 100% thành phần có nguồn gốc tự nhiên gồm bơ hạt mỡ hữu cơ Shea Butter và tinh dầu jojoba tự nhiên tan chảy êm ái trên môi, bảo vệ đôi môi khỏi tác động khô nứt của thời tiết hanh khô hay phòng máy lạnh.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Octyldodecanol, Hydrogenated Rapeseed Oil, Ricinus Communis Seed Oil, Cera Alba, Ethylhexyl Stearate, Cetyl Palmitate, Cetearyl Alcohol, Polyglyceryl-3 Diisostearate, Copernicia Cerifera Cera, Butyrospermum Parkii Butter, Persea Gratissima Oil, Simmondsia Chinensis Seed Oil, Tocopherol, Helianthus Annuus Seed Oil, Aqua, BHT.', 'Thoa trực tiếp lên môi bất cứ khi nào cảm thấy môi bị khô ráp hoặc trước khi đi ngủ. Thoa lót trước khi đánh son màu.', 'Đức', '4.8g', 1, 4.85, 53, 88, 36, 0, 0, '100% Natural Shea Butter, Organic Jojoba Oil, Beeswax', NOW(), NOW()),
(279, 'Sữa Tắm Dưỡng Ẩm Dịu Nhẹ Tinh Chất Sữa Nivea Creme Soft Caring Shower Cream 750ml', 'sua-tam-duong-am-diu-nhe-tinh-chat-sua-nivea-creme-soft-caring-shower-cream-750ml', 'Sữa tắm dạng kem chứa dầu hạnh nhân tự nhiên nuôi dưỡng làn da cơ thể mềm mượt đàn hồi.', 'Nivea Creme Soft Caring Shower Cream là sữa tắm kem dưỡng ẩm cao cấp chứa tinh dầu hạnh nhân quý giá Almond Oil cùng dưỡng chất Nivea Creme nguyên bản. Bọt sữa tắm sánh mịn nhẹ nhàng làm sạch bề mặt da cơ thể, duy trì độ cân bằng ẩm tự nhiên cho da mà không gây cảm giác nhờn rít khó chịu sau khi xả nước.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Glycol Distearate, Decyl Glucoside, Parfum, Glycerin, Prunus Amygdalus Dulcis Oil, Sodium Chloride, Citric Acid, Laureth-4, Sodium Benzoate, Linalool, Limonene, Citronellol, Benzyl Alcohol, Geraniol.', 'Làm ướt cơ thể, lấy một lượng sữa tắm vừa đủ tạo bọt với bông tắm rồi mát xa nhẹ nhàng khắp người. Tắm sạch lại với nước ấm.', 'Đức', '750ml', 1, 4.92, 54, 89, 36, 1, 0, 'Almond Oil, Nivea Creme Care Elements, Glycerin', NOW(), NOW()),
(280, 'Nước Tẩy Trang Cấp Ẩm Dịu Nhẹ Nivea MicellAIR Skin Breathe Micellar Water 400ml', 'nuoc-tay-trang-cap-am-diu-nhe-nivea-micellair-skin-breathe-micellar-water-400ml', 'Nước tẩy trang công nghệ MicellAIR hút sạch trang điểm tăng cường hấp thụ oxy cho làn da nhạy cảm.', 'Nivea MicellAIR Skin Breathe Micellar Water sở hữu công nghệ hạt Micellar thông minh hoạt động như nam châm hút sạch các hạt phấn trang điểm, dầu thừa và bụi bẩn mà không cần chà xát mạnh. Công thức 0% cồn, không paraben, không hương liệu bổ sung tinh dầu hạt nho và glycerin cấp ẩm, giúp làn da thở tự do và mềm mại sau khi tẩy trang.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'SENSITIVE', 'Aqua, PEG-40 Hydrogenated Castor Oil, Vitis Vinifera Seed Oil, Glycerin, Sorbitol, Decyl Glucoside, Poloxamer 124, Polyquaternium-10, Disodium Cocoyl Glutamate, Citric Acid, Sodium Chloride, Sodium Acetate, Propylene Glycol, 1,2-Hexanediol, Trisodium EDTA, Phenoxyethanol.', 'Thấm ướt bông tẩy trang với nước tẩy trang Nivea, nhẹ nhàng lau khắp mặt, mắt và môi từ trong ra ngoài. Không cần rửa lại với nước.', 'Đức', '400ml', 1, 4.85, 20, 90, 36, 0, 0, 'MicellAIR Technology, Grape Seed Oil, Glycerin, 0% Alcohol', NOW(), NOW()),
(281, 'Sáp Dưỡng Môi Hồng Hào Dịu Nhẹ Vaseline Lip Therapy Rosy Lips 7g', 'sap-duong-moi-hong-hao-diu-nhe-vaseline-lip-therapy-rosy-lips-7g', 'Sáp dưỡng môi chiết xuất hoa hồng và dầu hạnh nhân làm mềm môi khô nứt và tạo sắc hồng tự nhiên.', 'Vaseline Lip Therapy Rosy Lips là hũ son dưỡng môi biểu tượng được hàng triệu người tin dùng trên thế giới. Thành phần 100% mỡ khoáng tinh khiết Petroleum Jelly kết hợp cùng chiết xuất hoa hồng Damask và dầu hạnh nhân ngọt ngào khóa ẩm tức thì, chữa lành bờ môi nứt nẻ chảy máu và trả lại bờ môi căng bóng, hồng hào tự nhiên.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Petrolatum, Rosa Damascena Flower Oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Aroma (Flavor), Linalool, CI 73360 (Red 30 Lake), CI 77891 (Titanium Dioxide).', 'Dùng đầu ngón tay lấy một lượng sáp vừa đủ thoa đều lên môi bất cứ khi nào môi bị khô hoặc trước khi đi ngủ như lớp mặt nạ ngủ môi.', 'Mỹ', '7g', 1, 4.92, 21, 91, 37, 1, 0, '100% Pure Petroleum Jelly, Damask Rose Extract, Sweet Almond Oil', NOW(), NOW()),
(282, 'Sữa Dưỡng Thể Dưỡng Sáng Đều Màu Vaseline Healthy Bright Daily Brightening Lotion 725ml', 'sua-duong-the-duong-sang-deu-mau-vaseline-healthy-bright-daily-brightening-lotion-725ml', 'Sữa dưỡng thể chứa giọt sáp Vaseline Jelly và Niacinamide dưỡng sáng da toàn thân sau 2 tuần.', 'Vaseline Healthy Bright Daily Brightening Lotion là dòng sữa dưỡng thể dưỡng sáng da bán chạy hàng đầu với các giọt vi sáp Vaseline Jelly siêu nhỏ giúp khóa ẩm sâu trong từng tế bào biểu bì. Bổ sung Niacinamide (Vitamin B3) tinh khiết ức chế vận chuyển melanin và màng chống nắng 3 tác động bảo vệ da khỏi sạm đen do tia tử ngoại.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Isopropyl Myristate, Stearic Acid, Glyceryl Stearate, Mineral Oil, Ethylhexyl Methoxycinnamate, Niacinamide, Glycerin, Triethanolamine, Phenoxyethanol, Dimethicone, Butyl Methoxydibenzoylmethane, Carbomer, Petrolatum, Cetyl Alcohol, Perfume, Methylparaben, Titanium Dioxide, Propylparaben, Disodium EDTA, BHT.', 'Thoa đều khắp cơ thể 2 lần mỗi ngày sáng và tối sau khi tắm. Mát xa nhẹ nhàng theo hình xoắn ốc cho sữa dưỡng thấm sâu.', 'Mỹ', '725ml', 1, 4.85, 22, 92, 37, 1, 0, 'Micro-droplets of Vaseline Jelly, Niacinamide (Vitamin B3), Triple Sunscreens', NOW(), NOW()),
(283, 'Sữa Dưỡng Thể Trắng Da Chống Lão Hóa Vaseline Healthy Bright Gluta-Hya Flawless Glow 300ml', 'sua-duong-the-trang-da-chong-lao-hoa-vaseline-healthy-bright-gluta-hya-flawless-glow-300ml', 'Serum dưỡng thể công nghệ GlutaGlow sáng da gấp 10 lần Vitamin C và Hyaluron cấp ẩm đa tầng.', 'Vaseline Gluta-Hya Serum Burst Lotion Flawless Glow là bước đột phá công nghệ biến sữa dưỡng thể thành những giọt serum tan chảy như nước ngay khi thoa lên da. Hoạt chất độc quyền GlutaGlow có sức mạnh làm sáng da gấp 10 lần Vitamin C, kết hợp 10x Pro-Retinol tẩy tế bào sừng già cỗi làm đều màu da và Hyaluron ngậm nước đa tầng giúp da căng mướt rạng rỡ.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'FEMALE', 'ALL', 'Water, Dimethicone, Isohexadecane, Glycerin, Niacinamide, Glutathione, Sodium Hyaluronate, Retinyl Palmitate, Helianthus Annuus (Sunflower) Seed Oil, Glycine, Cystine, Sodium PCA, Petrolatum, Carbomer, Phenoxyethanol, Fragrance, Methylparaben, Sodium Hydroxide, Disodium EDTA, Titanium Dioxide, BHT, Tocopherol.', 'Thoa lên toàn thân mỗi sáng và tối sau khi tắm. Kết cấu serum lỏng nhẹ thẩm thấu ngay sau 3 giây không hề bết rít dính vào quần áo.', 'Mỹ', '300ml', 1, 4.92, 23, 93, 37, 1, 0, 'GlutaGlow (10x stronger than Vitamin C), 10x Hyaluron, 10x Pro-Retinol', NOW(), NOW()),
(284, 'Kem Dưỡng Móng Và Phục Hồi Da Tay Chuyên Sâu Vaseline Deep Moisture Hand & Nail Cream 60ml', 'kem-duong-mong-va-phuc-hoi-da-tay-chuyen-sau-vaseline-deep-moisture-hand-and-nail-cream-60ml', 'Kem dưỡng tay chứa Keratin và vi sáp Vaseline nuôi dưỡng móng tay chắc khỏe gấp 10 lần sau 2 tuần.', 'Vaseline Deep Moisture Hand & Nail Cream là giải pháp phục hồi tối ưu cho đôi bàn tay khô ráp và móng tay giòn gãy. Chứa hoạt chất Keratin củng cố cấu trúc móng tay chắc khỏe, kết hợp các giọt vi sáp Petroleum Jelly và Vitamin E cấp ẩm sâu, làm mềm mịn các khóe da tay bị xước măng rô mà không để lại cảm giác nhờn dính khi gõ phím.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Aqua, Potassium Lactate, Potato Starch Modified, Stearic Acid, Mineral Oil, Dimethicone, Glycerin, Lactic Acid, Glycol Stearate, Hydrolyzed Keratin, Petrolatum, Tocopheryl Acetate, Glyceryl Stearate, Cetyl Alcohol, Triethanolamine, Phenoxyethanol, Methylparaben, Propylparaben, Disodium EDTA, Parfum.', 'Thoa kem lên bàn tay và từng đầu móng tay, mát xa nhẹ nhàng cho kem thẩm thấu hết. Dùng đều đặn hàng ngày sau khi rửa tay.', 'Mỹ', '60ml', 1, 4.85, 24, 94, 37, 1, 0, 'Keratin Complex, Micro-droplets of Vaseline Jelly, Vitamin E', NOW(), NOW()),
(285, 'Sữa Tắm Sáng Da Dưỡng Ẩm Chuyên Sâu Vaseline Healthy Bright Daily Brightening Body Wash 500ml', 'sua-tam-sang-da-duong-am-chuyen-sau-vaseline-healthy-bright-daily-brightening-body-wash-500ml', 'Sữa tắm chứa vi chất Vaseline Jelly và Niacinamide dưỡng sáng da đều màu và dưỡng ẩm mịn màng.', 'Vaseline Healthy Bright Daily Brightening Body Wash là dòng sữa tắm dưỡng thể sáng da hàng đầu với công nghệ giọt sáp dưỡng Vaseline Jelly siêu vi mô. Kết hợp cùng hoạt chất dưỡng sáng da vàng Niacinamide (Vitamin B3) và Vitamin E, sữa tắm nhẹ nhàng cuốn trôi bụi bẩn tế bào chết bề mặt, nuôi dưỡng làn da xỉn màu trở nên tươi sáng rạng rỡ và ẩm mịn căng tràn sức sống sau mỗi lần tắm.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Myristic Acid, Lauric Acid, Potassium Hydroxide, Sodium Laureth Sulfate, Palmitic Acid, Glycerin, Glycol Distearate, Cocamidopropyl Betaine, Fragrance, Niacinamide, Petrolatum, Tocopheryl Acetate, Sodium Chloride, Phenoxyethanol, BHT, Tetrasodium EDTA, Etidronic Acid.', 'Làm ướt cơ thể. Lấy lượng sữa tắm vừa đủ ra bông tắm hoặc lòng bàn tay, tạo bọt dày mịn và mát xa khắp toàn thân trong 2 phút rồi xả sạch bằng nước mát.', 'Mỹ', '500ml', 1, 4.92, 25, 95, 37, 1, 0, 'Micro-droplets of Vaseline Jelly, Niacinamide (Vitamin B3), Vitamin E', NOW(), NOW()),
(286, 'Dầu Gội Vào Nếp Mượt Mà Tinh Dầu Argan Tresemmé Keratin Smooth Shampoo 850g', 'dau-goi-vao-nep-muot-ma-tinh-dau-argan-tresemme-keratin-smooth-shampoo-850g', 'Dầu gội chuẩn salon chứa tinh dầu Argan Morocco và Keratin giữ tóc vào nếp suôn mượt suốt 72 giờ.', 'Tresemmé Keratin Smooth Shampoo là bí quyết cho mái tóc vào nếp mượt mà chuẩn sàn diễn thời trang thế giới. Công thức nồng độ sulfate thấp kết hợp tinh dầu Argan quý hiếm từ Morocco và protein Keratin thủy phân, làm sạch tóc dịu nhẹ, lấp đầy các khoảng trống hư tổn trên sợi tóc, giúp kiểm soát tóc xơ rối và giữ nếp suôn mượt đến 72 giờ.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Sodium Chloride, Dimethiconol, Fragrance, Glycol Distearate, Carbomer, Hydrolyzed Keratin, Argania Spinosa Kernel Oil, Sclerocarya Birrea Seed Oil, TEA-Dodecylbenzenesulfonate, Guar Hydroxypropyltrimonium Chloride, Citric Acid, Disodium EDTA, DMDM Hydantoin, Mica, Titanium Dioxide.', 'Thoa dầu gội lên tóc ướt, mát xa da đầu và sợi tóc nhẹ nhàng tạo bọt trong 2-3 phút rồi xả sạch lại bằng nước ấm.', 'Mỹ', '850g', 1, 4.85, 26, 96, 38, 1, 0, 'Hydrolyzed Keratin, Moroccan Argan Oil, Low Sulfate Formula', NOW(), NOW()),
(287, 'Dầu Xả Vào Nếp Mượt Mà Tinh Dầu Argan Tresemmé Keratin Smooth Conditioner 640g', 'dau-xa-vao-nep-muot-ma-tinh-dau-argan-tresemme-keratin-smooth-conditioner-640g', 'Dầu xả bổ sung Keratin và tinh dầu Argan phục hồi tóc khô xơ giúp tóc óng ả mềm rũ tự nhiên.', 'Tresemmé Keratin Smooth Conditioner nuôi dưỡng sâu từng sợi tóc từ gốc đến ngọn với phức hợp protein Keratin và tinh dầu Argan. Dầu xả nhanh chóng làm mềm biểu bì tóc xơ rối, bảo vệ tóc trước nhiệt độ của máy sấy và uốn tóc, đem lại mái tóc suôn mượt óng ả chuẩn salon.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Cetearyl Alcohol, Dimethicone, Stearamidopropyl Dimethylamine, Behentrimonium Chloride, Fragrance, Hydrolyzed Keratin, Argania Spinosa Kernel Oil, Sclerocarya Birrea Seed Oil, Lactic Acid, Dipropylene Glycol, Amodimethicone, Potassium Chloride, Disodium EDTA, PEG-7 Propylheptyl Ether, Cetrimonium Chloride, Phenoxyethanol.', 'Sau khi gội đầu, vuốt dầu xả từ thân tóc đến ngọn tóc (cách chân tóc 2-3cm). Giữ nguyên trong 2-3 phút rồi xả sạch lại bằng nước mát.', 'Mỹ', '640g', 1, 4.92, 27, 97, 38, 1, 0, 'Hydrolyzed Keratin, Argan Oil, Behentrimonium Chloride', NOW(), NOW()),
(288, 'Kem Ủ Tóc Vào Nếp Chuẩn Salon Tresemmé Keratin Smooth Deep Smoothing Mask 180ml', 'kem-u-toc-vao-nep-chuan-salon-tresemme-keratin-smooth-deep-smoothing-mask-180ml', 'Kem ủ tóc phục hồi chuyên sâu chứa hàm lượng Keratin đậm đặc xóa tan tình trạng tóc xơ rối.', 'Tresemmé Keratin Smooth Deep Smoothing Mask là liệu pháp ủ tóc phục hồi chuyên sâu tại nhà mang đẳng cấp salon 5 sao. Với nồng độ Keratin đậm đặc và tinh dầu Argan Morocco, kem ủ thẩm thấu sâu vào lõi tóc, tái tạo các sợi tóc bị tổn thương do nhuộm tẩy, loại bỏ hiện tượng chẻ ngọn và đem lại mái tóc bóng mượt như lụa.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Cetearyl Alcohol, Stearamidopropyl Dimethylamine, Behentrimonium Chloride, Dimethicone, Fragrance, Hydrolyzed Keratin, Argania Spinosa Kernel Oil, Sclerocarya Birrea Seed Oil, Lactic Acid, Dipropylene Glycol, Amodimethicone, Potassium Chloride, Disodium EDTA, PEG-7 Propylheptyl Ether, Cetrimonium Chloride, Phenoxyethanol.', 'Sau khi gội đầu sạch, thoa kem ủ đều khắp thân và ngọn tóc ẩm. Massage nhẹ nhàng và ủ trong 5-10 phút rồi xả sạch bằng nước mát. Sử dụng 1-2 lần mỗi tuần.', 'Mỹ', '180ml', 1, 4.85, 28, 98, 38, 1, 0, 'Concentrated Keratin, Argan Oil, Marula Seed Oil', NOW(), NOW()),
(289, 'Dầu Gội Ngăn Gãy Rụng Phục Hồi Liên Kết Tóc Tresemmé Salon Rebond 850g', 'dau-goi-ngan-gay-rung-phuc-hoi-lien-ket-toc-tresemme-salon-rebond-850g', 'Dầu gội công nghệ TRESplex Rebond hàn gắn liên kết tóc đứt gãy giảm gãy rụng tới 98%.', 'Tresemmé Salon Rebond Shampoo ứng dụng công nghệ đột phá TRESplex Rebond len lỏi vào từng sợi tóc bị hư tổn nặng nề do tẩy nhuộm và uốn nhiệt, hàn gắn lại các liên kết disulfide bị đứt gãy bên trong lõi tóc. Sản phẩm giảm gãy rụng tóc tới 98% và khôi phục mái tóc chắc khỏe dẻo dai.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Dimethiconol, Cocamidopropyl Betaine, Sodium Chloride, Fragrance, Glycol Distearate, Gluconolactone, Trehalose, Sodium Sulfate, Biotin, Carbomer, TEA-Dodecylbenzenesulfonate, Guar Hydroxypropyltrimonium Chloride, Citric Acid, Disodium EDTA, DMDM Hydantoin.', 'Thoa dầu gội lên tóc ướt, tạo bọt và mát xa nhẹ nhàng da đầu và sợi tóc trong 2 phút rồi xả sạch với nước.', 'Mỹ', '850g', 1, 4.92, 29, 99, 38, 1, 0, 'TRESplex Rebond Technology, Biotin, Gluconolactone', NOW(), NOW()),
(290, 'Dầu Xả Ngăn Gãy Rụng Chuyên Sâu Tresemmé Salon Rebond Conditioner 640g', 'dau-xa-ngan-gay-rung-chuyen-sau-tresemme-salon-rebond-conditioner-640g', 'Dầu xả tái tạo liên kết sợi tóc ngăn ngừa rụng tóc và bảo vệ mái tóc nhuộm uốn.', 'Tresemmé Salon Rebond Conditioner là bước phục hồi không thể thiếu cho mái tóc yếu gãy rụng. Dầu xả bao bọc sợi tóc bằng màng dưỡng chất TRESplex Rebond, bảo vệ sợi tóc trước các lực kéo căng khi chải đầu và tác động nhiệt độ cao, giúp tóc suôn mềm và phục hồi sức sống nguyên bản.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Cetearyl Alcohol, Dimethicone, Stearamidopropyl Dimethylamine, Behentrimonium Chloride, Fragrance, Gluconolactone, Trehalose, Sodium Sulfate, Biotin, Lactic Acid, Amodimethicone, Disodium EDTA, PEG-7 Propylheptyl Ether, Cetrimonium Chloride, Phenoxyethanol.', 'Thoa dầu xả từ thân đến ngọn tóc sau khi gội sạch đầu, giữ trong 2-3 phút rồi xả sạch lại bằng nước mát.', 'Mỹ', '640g', 1, 4.85, 30, 100, 38, 1, 0, 'TRESplex Rebond Complex, Biotin, Lactic Acid', NOW(), NOW()),
(291, 'Dầu Gội Phục Hồi Toàn Diện Tóc Hư Tổn Pantene Pro-V Total Damage Care Shampoo 900ml', 'dau-goi-phuc-hoi-toan-dien-toc-hu-ton-pantene-pro-v-total-damage-care-shampoo-900ml', 'Dầu gội chứa công thức Pro-Vitamin B5 nuôi dưỡng sâu và phục hồi 10 dấu hiệu tóc hư tổn.', 'Pantene Pro-V Total Damage Care Shampoo là dầu gội phục hồi hư tổn số 1 với công thức dưỡng chất Pro-V (Pro-Vitamin B5: Panthenol và Panthenyl Ethyl Ether) thẩm thấu vào tận lõi tóc. Sản phẩm ngăn ngừa 10 dấu hiệu hư tổn của tóc gồm chẻ ngọn, khô xơ, gãy rụng, xỉn màu và tóc yếu, đem lại mái tóc bóng khỏe mượt mà từ gốc đến ngọn.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Sodium Citrate, Sodium Xylenesulfonate, Sodium Chloride, Sodium Lauryl Sulfate, Fragrance, Stearyl Alcohol, Cetyl Alcohol, Dimethiconol, Citric Acid, Sodium Benzoate, Dimethicone, Guar Hydroxypropyltrimonium Chloride, Panthenol, Panthenyl Ethyl Ether, Histidine, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Làm ướt tóc, thoa dầu gội và mát xa nhẹ nhàng da đầu và sợi tóc trong 2 phút, sau đó xả sạch lại bằng nước mát.', 'Mỹ', '900ml', 1, 4.92, 31, 101, 39, 1, 0, 'Pro-V Formula (Panthenol, Panthenyl Ethyl Ether), Histidine', NOW(), NOW()),
(292, 'Dầu Xả Ngăn Rụng Tóc Nuôi Dưỡng Chân Tóc Pantene Pro-V Hair Fall Control Conditioner 650ml', 'dau-xa-ngan-rung-toc-nuoi-duong-chan-toc-pantene-pro-v-hair-fall-control-conditioner-650ml', 'Dầu xả chứa dưỡng chất Pro-V và tinh chất gạo củng cố sợi tóc chắc khỏe giảm rụng tóc do gãy rụng.', 'Pantene Pro-V Hair Fall Control Conditioner kết hợp tinh túy từ công thức Pro-Vitamin B5 và chiết xuất dầu cám gạo thiên nhiên Nhật Bản. Dầu xả bao bọc sợi tóc giúp giảm ma sát khi chải đầu, củng cố độ bền dẻo dai của thân tóc từ gốc đến ngọn và giảm thiểu rụng tóc do đứt gãy tới 98%.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Glycerin, Stearyl Alcohol, Behentrimonium Methosulfate, Bis-Aminopropyl Dimethicone, Cetyl Alcohol, Fragrance, Dicetyldimonium Chloride, Isopropyl Alcohol, Benzyl Alcohol, Disodium EDTA, Panthenol, Panthenyl Ethyl Ether, Histidine, Citric Acid, Oryza Sativa (Rice) Bran Oil, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Sau khi gội đầu sạch, thoa đều dầu xả lên thân tóc và ngọn tóc ẩm. Để dưỡng chất ngấm trong 2-3 phút rồi xả sạch lại bằng nước.', 'Mỹ', '650ml', 1, 4.85, 32, 102, 39, 1, 0, 'Pro-V Complex, Rice Oil Essence, Histidine', NOW(), NOW()),
(293, 'Kem Ủ Tóc Collagen Phục Hồi Chuyên Sâu Pantene Pro-V Miracles Collagen Hair Mask 180ml', 'kem-u-toc-collagen-phuc-hoi-chuyen-sau-pantene-pro-v-miracles-collagen-hair-mask-180ml', 'Mặt nạ tóc bổ sung Collagen thủy phân và Pro-V đậm đặc phục hồi mái tóc xơ rối khô ráp thần tốc.', 'Pantene Pro-V Miracles Collagen Hair Treatment Mask là liệu trình phục hồi tóc hư tổn nặng với sự kết hợp của Collagen thủy phân và gấp đôi hàm lượng Pro-Vitamin B5. Kem ủ thấm sâu và nuôi dưỡng từng lõi tóc bị tổn thương, phục hồi độ đàn hồi và độ bóng mượt bồng bềnh tự nhiên cho mái tóc chỉ sau 3 phút ủ tóc.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Stearyl Alcohol, Bis-Aminopropyl Dimethicone, Behentrimonium Methosulfate, Cetyl Alcohol, Fragrance, Isopropyl Alcohol, Benzyl Alcohol, Disodium EDTA, Polysorbate 20, Panthenol, Panthenyl Ethyl Ether, Histidine, Citric Acid, Collagen, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Sau khi gội đầu sạch, thoa kem ủ đều khắp thân tóc và ngọn tóc ẩm. Massage nhẹ nhàng và ủ trong 3-5 phút rồi xả sạch lại với nước.', 'Mỹ', '180ml', 1, 4.92, 33, 103, 39, 1, 0, 'Hydrolyzed Collagen, Pro-V Complex, Biotin, Histidine', NOW(), NOW()),
(294, 'Dầu Gội Mượt Mà Óng Ả Pantene Pro-V Silky Smooth Care Shampoo 900ml', 'dau-goi-muot-ma-ong-a-pantene-pro-v-silky-smooth-care-shampoo-900ml', 'Dầu gội bổ sung độ ẩm kiểm soát tóc xơ rối cho mái tóc vào nếp suôn mượt óng ả suốt cả ngày.', 'Pantene Pro-V Silky Smooth Care Shampoo khóa ẩm sâu cho từng sợi tóc khô ráp với công thức Pro-V giàu độ ẩm. Dầu gội cân bằng độ ẩm cho tóc trong mọi điều kiện thời tiết, chống lại tình trạng tóc bông xù mất nếp khi trời nồm ẩm, đem lại mái tóc suôn mượt như lụa và dễ vào nếp.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Sodium Citrate, Sodium Xylenesulfonate, Sodium Chloride, Sodium Lauryl Sulfate, Fragrance, Stearyl Alcohol, Cetyl Alcohol, Dimethiconol, Citric Acid, Sodium Benzoate, Dimethicone, Guar Hydroxypropyltrimonium Chloride, Panthenol, Panthenyl Ethyl Ether, Histidine, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Làm ướt tóc, thoa dầu gội và tạo bọt mát xa nhẹ nhàng trong 2 phút rồi xả sạch bằng nước mát.', 'Mỹ', '900ml', 1, 4.85, 34, 104, 39, 1, 0, 'Pro-V Moisture Complex, Histidine, Dimethiconol', NOW(), NOW()),
(295, 'Kem Xả 3 Phút Phục Hồi Hư Tổn Pantene Pro-V Total Damage Care 3 Minute Miracle Conditioner 300ml', 'kem-xa-3-phut-phuc-hoi-hu-ton-pantene-pro-v-total-damage-care-3-minute-miracle-conditioner-300ml', 'Kem xả đậm đặc phục hồi 3 tháng hư tổn của tóc chỉ trong 3 phút với tinh chất Pro-V cô đặc.', 'Pantene 3 Minute Miracle Conditioner là kem xả phục hồi kỳ diệu giúp tái sinh mái tóc khô xơ chẻ ngọn chỉ trong 3 phút mỗi ngày. Chứa gấp 2 lần hàm lượng dưỡng chất Pro-V cô đặc thẩm thấu sâu vào biểu bì tóc, sửa chữa tổn thương từ bên trong và đem lại mái tóc mềm mượt óng ả mà không hề gây bết dính sợi tóc.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Silicone Quaternium-26, Stearyl Alcohol, Behentrimonium Methosulfate, Cetyl Alcohol, Fragrance, Isopropyl Alcohol, Benzyl Alcohol, Disodium EDTA, Polysorbate 20, Panthenol, Panthenyl Ethyl Ether, Histidine, Citric Acid, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Sau khi gội đầu, thoa kem xả lên thân và ngọn tóc ướt. Giữ nguyên trong đúng 3 phút rồi xả sạch lại bằng nước mát.', 'Mỹ', '300ml', 1, 4.92, 35, 105, 39, 1, 0, '2x Concentrated Pro-V, Histidine, Bis-Aminopropyl Dimethicone', NOW(), NOW()),
(296, 'Dầu Gội Sạch Gàu Bạc Hà Băng Lạnh Head & Shoulders Cool Menthol Shampoo 850ml', 'dau-goi-sach-gau-bac-ha-bang-lanh-head-and-shoulders-cool-menthol-shampoo-850ml', 'Dầu gội sạch gàu số 1 thế giới với tinh chất bạc hà sảng khoái và hoạt chất kẽm ZPT sạch gàu ngứa 100%.', 'Head & Shoulders Cool Menthol Shampoo là dầu gội trị gàu biểu tượng toàn cầu với tinh chất bạc hà thiên nhiên mát lạnh mang lại cảm giác sảng khoái băng giá tức thì cho da đầu. Hoạt chất kẽm Zinc Pyrithione (ZPT) được chứng minh lâm sàng tiêu diệt tận gốc nấm men Malassezia gây gàu, loại bỏ 100% vảy gàu nhìn thấy được và ngăn gàu tái phát.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Sodium Laureth Sulfate, Sodium Xylenesulfonate, Zinc Carbonate, Cocamide MEA, Cocamidopropyl Betaine, Sodium Chloride, Sodium Benzoate, Fragrance, Zinc Pyrithione, Dimethicone, Menthol, Guar Hydroxypropyltrimonium Chloride, Magnesium Carbonate Hydroxide, Methylchloroisothiazolinone, Methylisothiazolinone, CI 42090, CI 17200.', 'Làm ướt tóc, lấy lượng dầu gội vừa đủ xoa bóp nhẹ nhàng lên da đầu và tóc trong 2 phút để tinh chất bạc hà phát huy tác dụng mát lạnh, sau đó xả sạch với nước.', 'Mỹ', '850ml', 1, 4.85, 36, 106, 40, 1, 0, 'Zinc Pyrithione (ZPT), Natural Menthol, Zinc Carbonate', NOW(), NOW()),
(297, 'Dầu Gội Sạch Gàu Hương Chanh Tươi Mát Kiềm Dầu Head & Shoulders Lemon Fresh Shampoo 850ml', 'dau-goi-sach-gau-huong-chanh-tuoi-mat-kiem-dau-head-and-shoulders-lemon-fresh-shampoo-850ml', 'Dầu gội chiết xuất chanh vàng tươi kiềm dầu da đầu loại bỏ bã nhờn và sạch gàu ngứa suốt 72 giờ.', 'Head & Shoulders Lemon Fresh Shampoo được đặc chế cho da đầu nhiều dầu nhờn và dễ bết dính. Chiết xuất quả chanh vàng tươi mát kết hợp hoạt chất kháng gàu ZPT làm sạch sâu lượng bã nhờn dư thừa bít tắc chân tóc, giữ cho mái tóc luôn bồng bềnh, thơm mát hương chanh tươi sảng khoái suốt 72 giờ.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'OILY', 'Water, Sodium Laureth Sulfate, Sodium Xylenesulfonate, Zinc Carbonate, Cocamide MEA, Cocamidopropyl Betaine, Sodium Chloride, Fragrance, Citrus Limon (Lemon) Fruit Extract, Zinc Pyrithione, Dimethicone, Guar Hydroxypropyltrimonium Chloride, Magnesium Carbonate Hydroxide, Sodium Benzoate, Methylchloroisothiazolinone, Methylisothiazolinone, CI 19140, CI 42090.', 'Làm ướt tóc, thoa dầu gội lên tóc và da đầu mát xa kỹ trong 2 phút rồi xả sạch bằng nước.', 'Mỹ', '850ml', 1, 4.92, 37, 107, 40, 1, 0, 'Citrus Extract, Zinc Pyrithione (ZPT), Zinc Carbonate', NOW(), NOW()),
(298, 'Dầu Gội Sạch Gàu Ngăn Rụng Tóc Head & Shoulders Anti-Hairfall Shampoo 850ml', 'dau-goi-sach-gau-ngan-rung-toc-head-and-shoulders-anti-hairfall-shampoo-850ml', 'Dầu gội sạch gàu kết hợp tinh chất dầu sâm nuôi dưỡng chân tóc chắc khỏe giảm gãy rụng tóc hiệu quả.', 'Head & Shoulders Anti-Hairfall Shampoo bảo vệ da đầu toàn diện khỏi tác nhân gây gàu và hiện tượng rụng tóc do gãy rụng. Tinh chất nhân sâm quý giá cung cấp dưỡng chất nuôi dưỡng chân tóc, tăng cường độ bám của nang tóc và phục hồi cấu trúc sợi tóc dẻo dai từ gốc đến ngọn.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Sodium Laureth Sulfate, Zinc Carbonate, Glycol Distearate, Cocamide MEA, Cocamidopropyl Betaine, Sodium Chloride, Fragrance, Zinc Pyrithione, Panax Ginseng Root Extract, Dimethicone, Guar Hydroxypropyltrimonium Chloride, Sodium Benzoate, Magnesium Carbonate Hydroxide, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Thoa dầu gội lên tóc ướt, tạo bọt và mát xa da đầu nhẹ nhàng trong 2-3 phút để dưỡng chất nhân sâm thấm sâu vào chân tóc rồi xả sạch với nước.', 'Mỹ', '850ml', 1, 4.85, 38, 108, 40, 1, 0, 'Zinc Pyrithione (ZPT), Ginseng Extract, Dimethicone', NOW(), NOW()),
(299, 'Dầu Xả Sạch Gàu Cấp Ẩm Da Đầu Head & Shoulders Sub Zero Cool Menthol Conditioner 300ml', 'dau-xa-sach-gau-cap-am-da-dau-head-and-shoulders-sub-zero-cool-menthol-conditioner-300ml', 'Dầu xả sạch gàu chuyên dụng có thể thoa trực tiếp lên da đầu giúp cấp ẩm làm mát và dưỡng tóc mềm mượt.', 'Head & Shoulders Sub Zero Cool Menthol Conditioner là dầu xả đặc biệt có công thức an toàn để thoa trực tiếp lên da đầu mà không gây bít tắc chân tóc. Chứa hoạt chất ZPT và bạc hà mát lạnh làm dịu cơn ngứa da đầu, cấp ẩm sâu chống khô da đầu và giữ cho mái tóc luôn suôn mượt tơi xốp.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'NORMAL', 'Water, Stearyl Alcohol, Cetyl Alcohol, Stearamidopropyl Dimethylamine, Glutamic Acid, Dimethicone, Fragrance, Zinc Pyrithione, Menthol, Benzyl Alcohol, Citric Acid, Sodium Chloride, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Sau khi gội đầu sạch, thoa dầu xả lên cả tóc và da đầu. Mát xa nhẹ nhàng trong 1-2 phút để cảm nhận cảm giác mát lạnh sảng khoái rồi xả sạch lại bằng nước.', 'Mỹ', '300ml', 1, 4.92, 39, 109, 40, 1, 0, 'Zinc Pyrithione, Menthol, Scalp Hydrating Complex', NOW(), NOW()),
(300, 'Dầu Gội Kiểm Soát Dầu Ngừa Ngứa Da Đầu Head & Shoulders Itchy Scalp Care Shampoo 850ml', 'dau-goi-kiem-soat-dau-ngua-ngua-da-dau-head-and-shoulders-itchy-scalp-care-shampoo-850ml', 'Dầu gội dập tắt cơn ngứa da đầu tức thì chứa chiết xuất khuynh diệp Eucalyptus và kẽm ZPT.', 'Head & Shoulders Itchy Scalp Care Shampoo mang lại cảm giác nhẹ nhõm tức thì cho da đầu bị ngứa ngáy dữ dội do gàu. Chiết xuất lá khuynh diệp tự nhiên Eucalyptus xoa dịu các kích ứng ngứa rát, trong khi hoạt chất ZPT loại bỏ mảng gàu bám dai dẳng, mang lại da đầu khỏe mạnh sạch gàu và mái tóc thơm mát suốt 72 giờ.', 'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?auto=format&fit=crop&w=800&q=85', 'ACTIVE', 'PRODUCT', 'UNISEX', 'ALL', 'Water, Sodium Laureth Sulfate, Zinc Carbonate, Glycol Distearate, Cocamide MEA, Cocamidopropyl Betaine, Sodium Chloride, Fragrance, Zinc Pyrithione, Eucalyptus Globulus Leaf Extract, Dimethicone, Guar Hydroxypropyltrimonium Chloride, Sodium Benzoate, Magnesium Carbonate Hydroxide, Methylchloroisothiazolinone, Methylisothiazolinone.', 'Làm ướt tóc và da đầu, lấy một lượng vừa đủ xoa đều và gãi nhẹ da đầu trong 2 phút rồi xả sạch lại bằng nước mát.', 'Mỹ', '850ml', 1, 4.85, 40, 110, 40, 1, 0, 'Eucalyptus Extract, Zinc Pyrithione (ZPT), Zinc Carbonate', NOW(), NOW());

